const PROVIDER_LOCK_FILE_NAME: &str = "carina-providers.lock";

/// Return the provider lock-file path for a project directory.
pub fn provider_lock_path(project_dir: &Path) -> PathBuf {
    project_dir.join(PROVIDER_LOCK_FILE_NAME)
}

/// Distinguishes the shapes a lock entry can take. Encoded as a tagged
/// enum so that invalid field combinations (e.g. `version = ""` *and*
/// `revision = "main"`, the root cause of #2028) can't be constructed at
/// all — no runtime validator, no empty-string filler.
///
/// Serialized with an explicit `mode` discriminator so the on-disk shape is
/// unambiguous:
///
/// ```toml
/// [[provider]]
/// name = "aws"; source = "..."; sha256 = "..."
/// mode = "version"
/// version = "0.5.2"
/// constraint = "~0.5.0"
/// ```
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "mode", rename_all = "lowercase")]
pub enum LockEntryKind {
    /// Released provider pinned to a semver tag (or registry version).
    Version {
        version: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        constraint: Option<String>,
    },
    /// GitHub release pinned to both its semver cache key and exact tag.
    #[serde(rename = "release")]
    GithubRelease {
        version: Version,
        tag: ReleaseTag,
        asset_id: AssetId,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        constraint: Option<String>,
    },
    /// Provider built from a git revision (branch/tag/SHA) via CI artifacts.
    Revision {
        revision: String,
        resolved_sha: CommitSha,
        artifact_id: ArtifactId,
    },
    /// Registry-hosted provider resolved by following a branch revision.
    RegistryRevision { revision: String, version: String },
    /// Local `file://` provider — identified entirely by `source`.
    File,
}

impl LockEntryKind {
    /// The concrete published version this entry pins, for modes that have one.
    fn resolved_version(&self) -> Option<Cow<'_, str>> {
        match self {
            LockEntryKind::Version {
                version,
                constraint: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version,
            } => Some(Cow::Borrowed(version)),
            LockEntryKind::GithubRelease {
                version,
                tag: _,
                asset_id: _,
                constraint: _,
            } => Some(Cow::Owned(version.to_string())),
            LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::File => None,
        }
    }

    fn resolution_slot(&self) -> LockEntryResolutionSlot<'_> {
        match self {
            Self::Version {
                version: _,
                constraint,
            } => LockEntryResolutionSlot::Version(constraint.as_deref()),
            Self::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint,
            } => LockEntryResolutionSlot::GithubRelease(constraint.as_deref()),
            Self::Revision {
                revision,
                resolved_sha: _,
                artifact_id: _,
            } => LockEntryResolutionSlot::Revision(revision),
            Self::RegistryRevision {
                revision,
                version: _,
            } => LockEntryResolutionSlot::RegistryRevision(revision),
            Self::File => LockEntryResolutionSlot::File,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LockEntryResolutionSlot<'a> {
    Version(Option<&'a str>),
    GithubRelease(Option<&'a str>),
    Revision(&'a str),
    RegistryRevision(&'a str),
    File,
}

/// Uninhabited marker for an entry that cannot carry registry metadata.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum NoRegistryLock {}

/// A single provider entry in carina-providers.lock.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(bound(serialize = "R: Serialize", deserialize = "R: Deserialize<'de>"))]
pub struct LockEntry<R = NoRegistryLock> {
    pub name: String,
    pub source: String,
    #[serde(flatten)]
    pub kind: LockEntryKind,
    pub sha256: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub registry: Option<R>,
}

impl LockEntry<NoRegistryLock> {
    fn into_stored(self) -> LockEntry<RegistryLock> {
        let registry = match self.registry {
            None => None,
            Some(uninhabited) => match uninhabited {},
        };
        LockEntry {
            name: self.name,
            source: self.source,
            kind: self.kind,
            sha256: self.sha256,
            registry,
        }
    }
}

/// A registry hostname normalized once at the lock-file boundary.
///
/// Registry host map keys and provider references both use this type, so case
/// differences cannot make a host record appear missing after migration.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CanonicalRegistryHostname(String);

impl CanonicalRegistryHostname {
    fn new(mut hostname: String) -> Self {
        hostname.make_ascii_lowercase();
        Self(hostname)
    }

    fn as_str(&self) -> &str {
        &self.0
    }
}

impl Borrow<str> for CanonicalRegistryHostname {
    fn borrow(&self) -> &str {
        self.as_str()
    }
}

impl fmt::Display for CanonicalRegistryHostname {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

impl From<String> for CanonicalRegistryHostname {
    fn from(hostname: String) -> Self {
        Self::new(hostname)
    }
}

impl From<&str> for CanonicalRegistryHostname {
    fn from(hostname: &str) -> Self {
        Self::new(hostname.to_owned())
    }
}

impl Serialize for CanonicalRegistryHostname {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        serializer.serialize_str(self.as_str())
    }
}

impl<'de> Deserialize<'de> for CanonicalRegistryHostname {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        String::deserialize(deserializer).map(Self::new)
    }
}

/// Registry-only pinning metadata. Kept outside [`LockEntryKind`] so the
/// version/revision/file shape remains a closed tagged enum.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(into = "RegistryLockSerde")]
pub struct RegistryLock {
    resolved_hostname: CanonicalRegistryHostname,
    /// The greatest fully validated sequence observed for this source. This is
    /// durable across downstream failures but is not a rollback floor.
    sequence: RegistrySequence,
    sequence_anchor: RegistrySequenceAnchor,
    valid_until_present: bool,
    yanked_versions: YankedRegistryVersions,
    signature: RegistrySignatureProtection,
    transparency_log_present: bool,
}

const PROVIDERS_V1_DISCOVERY_FIELD: &str = "providers.v1";
const REGISTRY_DISCOVERY_PATH: &str = "/.well-known/carina.json";

mod unconsumed_discovery_values {
    use super::{BTreeMap, PROVIDERS_V1_DISCOVERY_FIELD, fmt};

    /// Discovery values retained for round-tripping but not consumed by this
    /// client. The map is deliberately opaque: adding a consumer requires an
    /// explicit API change here instead of an unnoticed lookup in retained
    /// material.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub(super) struct UnconsumedDiscoveryValues(BTreeMap<String, String>);

    #[derive(Debug)]
    pub(super) struct UnconsumedDiscoveryValuesError;

    impl fmt::Display for UnconsumedDiscoveryValuesError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(
                f,
                "unconsumed registry discovery values must not contain providers.v1"
            )
        }
    }

    impl std::error::Error for UnconsumedDiscoveryValuesError {}

    impl UnconsumedDiscoveryValues {
        pub(super) fn try_from_values(
            values: BTreeMap<String, String>,
        ) -> Result<Self, UnconsumedDiscoveryValuesError> {
            if values.contains_key(PROVIDERS_V1_DISCOVERY_FIELD) {
                return Err(UnconsumedDiscoveryValuesError);
            }
            Ok(Self(values))
        }

        pub(super) fn without_consumed(mut values: BTreeMap<String, String>) -> Self {
            values.remove(PROVIDERS_V1_DISCOVERY_FIELD);
            Self(values)
        }

        pub(super) fn extend_resolved_values<'a>(
            &'a self,
            resolved: &mut BTreeMap<&'a str, &'a str>,
        ) {
            resolved.extend(
                self.0
                    .iter()
                    .map(|(field, value)| (field.as_str(), value.as_str())),
            );
        }

        pub(super) fn into_values(self) -> BTreeMap<String, String> {
            self.0
        }

        pub(super) fn is_empty(&self) -> bool {
            self.0.is_empty()
        }
    }
}

use unconsumed_discovery_values::{UnconsumedDiscoveryValues, UnconsumedDiscoveryValuesError};

/// The indivisible resolved discovery values pinned for one registry host.
///
/// The open map is intentional: values written by a newer client remain
/// representable and survive lock updates by an older client that does not
/// consume them yet.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RegistryDiscoveryPin {
    api_base_url: String,
    additional: UnconsumedDiscoveryValues,
}

#[derive(Debug)]
enum RegistryDiscoveryPinError {
    MissingProvidersV1,
    InvalidApiBaseUrl {
        value: String,
        source: Option<url::ParseError>,
    },
}

impl fmt::Display for RegistryDiscoveryPinError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingProvidersV1 => write!(
                f,
                "registry discovery values are missing required providers.v1"
            ),
            Self::InvalidApiBaseUrl { value, source } => {
                write!(
                    f,
                    "registry discovery providers.v1 pinned value must be an absolute HTTPS URL: {value:?}"
                )?;
                if let Some(source) = source {
                    write!(f, ": {source}")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for RegistryDiscoveryPinError {}

impl RegistryDiscoveryPin {
    fn from_values(values: BTreeMap<String, String>) -> Result<Self, RegistryDiscoveryPinError> {
        let api_base_url = values
            .get(PROVIDERS_V1_DISCOVERY_FIELD)
            .cloned()
            .ok_or(RegistryDiscoveryPinError::MissingProvidersV1)?;
        validate_persisted_api_base_url(&api_base_url)?;
        Ok(Self {
            api_base_url,
            additional: UnconsumedDiscoveryValues::without_consumed(values),
        })
    }

    fn into_values(self) -> BTreeMap<String, String> {
        let mut values = self.additional.into_values();
        values.insert(PROVIDERS_V1_DISCOVERY_FIELD.into(), self.api_base_url);
        values
    }

    fn resolved_values(&self) -> BTreeMap<&str, &str> {
        let mut values = BTreeMap::new();
        self.additional.extend_resolved_values(&mut values);
        values.insert(PROVIDERS_V1_DISCOVERY_FIELD, &self.api_base_url);
        values
    }

    fn api_base_url(&self) -> &str {
        &self.api_base_url
    }

    fn consumed_values(&self) -> Self {
        Self {
            api_base_url: self.api_base_url.clone(),
            additional: UnconsumedDiscoveryValues::default(),
        }
    }

    /// Iterate over the concrete discovery values held by this pin.
    pub fn values(&self) -> impl Iterator<Item = (&str, &str)> {
        self.resolved_values().into_iter()
    }
}

impl Serialize for RegistryDiscoveryPin {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        self.resolved_values().serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for RegistryDiscoveryPin {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let values = BTreeMap::<String, String>::deserialize(deserializer)?;
        Self::from_values(values).map_err(serde::de::Error::custom)
    }
}

/// A host either has its currently consumed discovery values pinned, is
/// explicitly awaiting first contact after an operator-authorized re-pin, or
/// is blocked until an operator authorizes discarding a migrated legacy pin.
/// Opaque values retained from newer clients remain carried where applicable.
#[derive(Debug, Clone, PartialEq, Eq)]
enum RegistryDiscoveryPinState {
    Pinned(RegistryDiscoveryPin),
    Unpinned(UnconsumedDiscoveryValues),
    MigrationPendingAuthorization(LegacyRegistryDiscoveryPins),
}

/// The only host states that registry discovery is allowed to consume.
///
/// Constructing this view rejects migration-pending state, so resolution
/// cannot accidentally treat migration as an operator-authorized re-pin.
enum AuthorizedRegistryDiscoveryState<'a> {
    Pinned(&'a RegistryDiscoveryPin),
    Unpinned(&'a UnconsumedDiscoveryValues),
}

impl AuthorizedRegistryDiscoveryState<'_> {
    fn pin(&self) -> Option<&RegistryDiscoveryPin> {
        match self {
            Self::Pinned(pin) => Some(pin),
            Self::Unpinned(_) => None,
        }
    }

    fn additional_values(&self) -> &UnconsumedDiscoveryValues {
        match self {
            Self::Pinned(pin) => &pin.additional,
            Self::Unpinned(additional) => additional,
        }
    }
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(into = "RegistryHostLockSerde")]
struct RegistryHostLock {
    discovery: RegistryDiscoveryPinState,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct RegistryHostLockSerde {
    discovery_pin_present: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    discovery_values: Option<BTreeMap<String, String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    migration_pending_discovery_pins: Option<LegacyRegistryDiscoveryPins>,
    /// Read-only compatibility alias written before pending state became a set.
    #[serde(default, skip_serializing)]
    migration_pending_discovery_pin: Option<LegacyRegistryDiscoveryPin>,
}

#[derive(Debug)]
enum RegistryHostLockError {
    Inconsistent,
    InvalidDiscoveryPin(RegistryDiscoveryPinError),
    InvalidUnconsumedDiscoveryValues(UnconsumedDiscoveryValuesError),
}

impl fmt::Display for RegistryHostLockError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Inconsistent => write!(
                f,
                "registry host lock is inconsistent: providers.v1 must be present in discovery_values exactly when discovery_pin_present is true; migration_pending_discovery_pins (or its legacy single-pin alias) is valid only as the sole discovery material while discovery_pin_present is false; other discovery values may remain in an ordinary unpinned state"
            ),
            Self::InvalidDiscoveryPin(error) => error.fmt(f),
            Self::InvalidUnconsumedDiscoveryValues(error) => error.fmt(f),
        }
    }
}

impl std::error::Error for RegistryHostLockError {}

impl RegistryHostLock {
    fn pinned(pin: RegistryDiscoveryPin) -> Self {
        Self {
            discovery: RegistryDiscoveryPinState::Pinned(pin),
        }
    }

    fn authorized_discovery(
        &self,
    ) -> Result<AuthorizedRegistryDiscoveryState<'_>, &LegacyRegistryDiscoveryPins> {
        match &self.discovery {
            RegistryDiscoveryPinState::Pinned(pin) => {
                Ok(AuthorizedRegistryDiscoveryState::Pinned(pin))
            }
            RegistryDiscoveryPinState::Unpinned(additional) => {
                Ok(AuthorizedRegistryDiscoveryState::Unpinned(additional))
            }
            RegistryDiscoveryPinState::MigrationPendingAuthorization(pin) => Err(pin),
        }
    }

    #[cfg(test)]
    fn pin_for_test(&self) -> Option<&RegistryDiscoveryPin> {
        match &self.discovery {
            RegistryDiscoveryPinState::Pinned(pin) => Some(pin),
            RegistryDiscoveryPinState::Unpinned(_)
            | RegistryDiscoveryPinState::MigrationPendingAuthorization(_) => None,
        }
    }
}

impl TryFrom<RegistryHostLockSerde> for RegistryHostLock {
    type Error = RegistryHostLockError;

    fn try_from(value: RegistryHostLockSerde) -> Result<Self, Self::Error> {
        let discovery = match (
            value.discovery_pin_present,
            value.discovery_values,
            value.migration_pending_discovery_pins,
            value.migration_pending_discovery_pin,
        ) {
            (true, Some(values), None, None) => RegistryDiscoveryPinState::Pinned(
                RegistryDiscoveryPin::from_values(values)
                    .map_err(RegistryHostLockError::InvalidDiscoveryPin)?,
            ),
            (false, None, None, None) => {
                RegistryDiscoveryPinState::Unpinned(UnconsumedDiscoveryValues::default())
            }
            (false, Some(additional), None, None) => RegistryDiscoveryPinState::Unpinned(
                UnconsumedDiscoveryValues::try_from_values(additional)
                    .map_err(RegistryHostLockError::InvalidUnconsumedDiscoveryValues)?,
            ),
            (false, None, Some(pins), None) => {
                RegistryDiscoveryPinState::MigrationPendingAuthorization(pins)
            }
            (false, None, None, Some(pin)) => {
                RegistryDiscoveryPinState::MigrationPendingAuthorization(pin.into())
            }
            _ => return Err(RegistryHostLockError::Inconsistent),
        };
        Ok(Self { discovery })
    }
}

impl From<RegistryHostLock> for RegistryHostLockSerde {
    fn from(value: RegistryHostLock) -> Self {
        match value.discovery {
            RegistryDiscoveryPinState::Pinned(pin) => Self {
                discovery_pin_present: true,
                discovery_values: Some(pin.into_values()),
                migration_pending_discovery_pins: None,
                migration_pending_discovery_pin: None,
            },
            RegistryDiscoveryPinState::Unpinned(additional) => Self {
                discovery_pin_present: false,
                discovery_values: if additional.is_empty() {
                    None
                } else {
                    Some(additional.into_values())
                },
                migration_pending_discovery_pins: None,
                migration_pending_discovery_pin: None,
            },
            RegistryDiscoveryPinState::MigrationPendingAuthorization(pins) => Self {
                discovery_pin_present: false,
                discovery_values: None,
                migration_pending_discovery_pins: Some(pins),
                migration_pending_discovery_pin: None,
            },
        }
    }
}

impl<'de> Deserialize<'de> for RegistryHostLock {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        RegistryHostLockSerde::deserialize(deserializer)?
            .try_into()
            .map_err(serde::de::Error::custom)
    }
}

/// Discovery material retained while migrating a v1 provider entry or v2
/// registry host record.
///
/// Neither value is a v3 discovery pin: v3 pins the resolved discovery-value
/// map, while v1 and v2 pinned the API base alongside a hash of the document
/// bytes.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(deny_unknown_fields)]
pub struct LegacyRegistryDiscoveryPin {
    api_base_url: String,
    discovery_sha256: String,
}

/// Distinct legacy discovery pins retained for one registry host.
///
/// The set is non-empty by construction: an empty host has ordinary unpinned
/// discovery state instead of migration-pending state.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(transparent)]
struct LegacyRegistryDiscoveryPins(BTreeSet<LegacyRegistryDiscoveryPin>);

impl LegacyRegistryDiscoveryPins {
    fn insert(&mut self, pin: LegacyRegistryDiscoveryPin) {
        self.0.insert(pin);
    }

    fn iter(&self) -> impl ExactSizeIterator<Item = &LegacyRegistryDiscoveryPin> {
        self.0.iter()
    }

    #[cfg(test)]
    fn len(&self) -> usize {
        self.0.len()
    }
}

impl From<LegacyRegistryDiscoveryPin> for LegacyRegistryDiscoveryPins {
    fn from(pin: LegacyRegistryDiscoveryPin) -> Self {
        Self(BTreeSet::from([pin]))
    }
}

impl<'de> Deserialize<'de> for LegacyRegistryDiscoveryPins {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let pins = BTreeSet::deserialize(deserializer)?;
        if pins.is_empty() {
            return Err(serde::de::Error::custom(
                "migration_pending_discovery_pins must not be empty",
            ));
        }
        Ok(Self(pins))
    }
}

#[derive(Debug)]
enum LegacyRegistryDiscoveryPinState {
    Pinned(LegacyRegistryDiscoveryPin),
    Unpinned,
}

#[derive(Debug)]
struct LegacyRegistryHostLock {
    discovery: LegacyRegistryDiscoveryPinState,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LegacyRegistryHostLockSerde {
    discovery_pin_present: bool,
    #[serde(default)]
    api_base_url: Option<String>,
    #[serde(default)]
    discovery_sha256: Option<String>,
}

#[derive(Debug)]
struct LegacyRegistryHostLockError;

impl fmt::Display for LegacyRegistryHostLockError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "v2 registry host lock is inconsistent: api_base_url and discovery_sha256 must be present together exactly when discovery_pin_present is true"
        )
    }
}

impl std::error::Error for LegacyRegistryHostLockError {}

impl TryFrom<LegacyRegistryHostLockSerde> for LegacyRegistryHostLock {
    type Error = LegacyRegistryHostLockError;

    fn try_from(value: LegacyRegistryHostLockSerde) -> Result<Self, Self::Error> {
        let discovery = match (
            value.discovery_pin_present,
            value.api_base_url,
            value.discovery_sha256,
        ) {
            (true, Some(api_base_url), Some(discovery_sha256)) => {
                LegacyRegistryDiscoveryPinState::Pinned(LegacyRegistryDiscoveryPin {
                    api_base_url,
                    discovery_sha256,
                })
            }
            (false, None, None) => LegacyRegistryDiscoveryPinState::Unpinned,
            _ => return Err(LegacyRegistryHostLockError),
        };
        Ok(Self { discovery })
    }
}

impl<'de> Deserialize<'de> for LegacyRegistryHostLock {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        LegacyRegistryHostLockSerde::deserialize(deserializer)?
            .try_into()
            .map_err(serde::de::Error::custom)
    }
}

/// Versions that this lock has observed as yanked. The resolver can only add
/// observations, so normal lock updates cannot remove a recorded yank.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(transparent)]
pub struct YankedRegistryVersions(BTreeSet<String>);

impl YankedRegistryVersions {
    pub fn contains(&self, version: &str) -> bool {
        self.0.contains(version)
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    fn from_serialized(versions: BTreeSet<String>) -> Self {
        Self(versions)
    }

    fn into_serialized(self) -> BTreeSet<String> {
        self.0
    }

    fn with_observed(mut self, versions: &[RegistryVersion]) -> Self {
        self.0.extend(
            versions
                .iter()
                .filter(|version| version.yanked)
                .map(|version| version.version.clone()),
        );
        self
    }

    fn union(mut self, other: &Self) -> Self {
        self.0.extend(other.0.iter().cloned());
        self
    }

    fn stripped_from(&self, versions: &[RegistryVersion]) -> Vec<String> {
        self.0
            .iter()
            .filter(|known_yanked| {
                let is_present = versions
                    .iter()
                    .any(|version| version.version == known_yanked.as_str());
                let is_still_yanked = versions
                    .iter()
                    .any(|version| version.version == known_yanked.as_str() && version.yanked);
                is_present && !is_still_yanked
            })
            .cloned()
            .collect()
    }
}

/// Security observations made before a provider has a registry lock entry to
/// carry them. An entry moves out of this map as soon as the provider is
/// pinned, keeping each source's ratchets in exactly one persisted location.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(transparent)]
struct UnpinnedRegistryRatchets(BTreeMap<String, RegistryRatchets>);

impl UnpinnedRegistryRatchets {
    fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    fn get(&self, source: &str) -> Option<&RegistryRatchets> {
        self.0.get(source)
    }

    fn merge(
        &mut self,
        source: String,
        ratchets: RegistryRatchets,
    ) -> Result<(), RegistryIdentityPinConflict> {
        match self.0.entry(source) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(ratchets);
            }
            std::collections::btree_map::Entry::Occupied(mut entry) => {
                let merged = entry.get().clone().merge(&ratchets)?;
                entry.insert(merged);
            }
        }
        Ok(())
    }

    fn remove(&mut self, source: &str) -> Option<RegistryRatchets> {
        self.0.remove(source)
    }

    fn into_canonical(self) -> Result<Self, RegistryIdentityPinConflictRecord> {
        let mut canonical = Self::default();
        for (source, ratchets) in self.0 {
            let provider = canonical_lock_source(&source);
            canonical
                .merge(provider.clone(), ratchets)
                .map_err(|source| RegistryIdentityPinConflictRecord { provider, source })?;
        }
        Ok(canonical)
    }
}

/// Whether a fully validated registry listing carried a sequence observation.
/// The contradictory `present = true, value = None` state cannot be constructed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegistrySequence {
    Absent,
    Present(u64),
}

/// The anti-rollback sequence established by a successful provider resolve.
/// This state exists only on a pinned [`RegistryLock`]; a pre-pin observation
/// cannot represent either a rollback floor or a pending reset.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RegistrySequenceAnchor {
    Unestablished,
    /// An explicit re-bootstrap was committed, but no subsequent resolution
    /// has successfully established (or consumed the absence of) an anchor.
    ResetPending,
    Established(u64),
}

/// The persisted state seen before validating a registry listing. Unlike an
/// anchor alone, this distinguishes a source with no lock record from an
/// existing source whose first sequence-less resolution already completed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RegistrySequencePreviousState {
    FirstContact,
    Unestablished,
    ResetPending,
    Established(u64),
}

/// Signature protection recorded for a registry provider. The signature
/// requirement is a monotonic ratchet, while the identity pin can be cleared
/// explicitly so the next signed artifact establishes a replacement pin.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegistrySignatureProtection {
    NotRequired,
    Required(SignerPinState),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReleaseChannel {
    Stable,
    Prerelease,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LegacySignerPin {
    pub certificate_san: String,
    pub oidc_issuer: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourcePin {
    pub oidc_issuer: String,
    pub repository_owner_id: String,
    pub repository_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WorkflowPin(pub String);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WorkflowPins {
    Stable(WorkflowPin),
    Prerelease(WorkflowPin),
    Both {
        stable: WorkflowPin,
        prerelease: WorkflowPin,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CurrentSignerPins {
    pub source: SourcePin,
    pub workflows: WorkflowPins,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SignerPinState {
    Unpinned,
    Legacy(LegacySignerPin),
    Current(CurrentSignerPins),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DiscardedSignerPins {
    Legacy(LegacySignerPin),
    Current(CurrentSignerPins),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ListedVersion {
    raw: String,
    parsed: Version,
}

impl ListedVersion {
    fn parse(raw: &str) -> Result<Self, String> {
        let parsed = Version::parse(raw)
            .map_err(|error| format!("Registry returned invalid version {raw:?}: {error}"))?;
        Ok(Self {
            raw: raw.to_string(),
            parsed,
        })
    }

    fn channel(&self) -> ReleaseChannel {
        if self.parsed.pre.is_empty() {
            ReleaseChannel::Stable
        } else {
            ReleaseChannel::Prerelease
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum SignerTransition {
    Unchanged,
    FirstContact,
    ChannelPinned(ReleaseChannel),
    LegacyConverted,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SignerAcceptance {
    next: SignerPinState,
    transition: SignerTransition,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum SignerRejection {
    StableSourceRef {
        expected: String,
        actual: String,
    },
    LegacyIdentity,
    SourceMismatch {
        expected: Box<SourcePin>,
        actual: Box<SourcePin>,
    },
    Workflow {
        channel: ReleaseChannel,
        expected: WorkflowPin,
        actual: WorkflowPin,
    },
}

impl fmt::Display for SignerRejection {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::StableSourceRef { expected, actual } => write!(
                f,
                "stable provider certificate source ref mismatch: expected {expected:?}, got {actual:?}"
            ),
            Self::LegacyIdentity => {
                write!(
                    f,
                    "certificate SAN or OIDC issuer differs from the legacy lock pin"
                )
            }
            Self::SourceMismatch { expected, actual } => write!(
                f,
                "certificate source differs from the lock pin: expected {expected:?}, got {actual:?}"
            ),
            Self::Workflow {
                channel,
                expected,
                actual,
            } => write!(
                f,
                "certificate workflow for {channel:?} differs from the lock pin: expected {:?}, got {:?}",
                expected.0, actual.0
            ),
        }
    }
}

fn decide_signer(
    expected: &SignerPinState,
    identity: &signing::VerifiedSignerIdentity,
    version: &ListedVersion,
) -> Result<SignerAcceptance, SignerRejection> {
    let channel = version.channel();
    if channel == ReleaseChannel::Stable {
        let expected_ref = format!("refs/tags/v{}", version.raw);
        if identity.source_ref() != expected_ref {
            return Err(SignerRejection::StableSourceRef {
                expected: expected_ref,
                actual: identity.source_ref().to_string(),
            });
        }
    }

    let source = SourcePin {
        oidc_issuer: identity.source().oidc_issuer.clone(),
        repository_owner_id: identity.source().repository_owner_id.clone(),
        repository_id: identity.source().repository_id.clone(),
    };
    let workflow = WorkflowPin(identity.workflow().to_string());

    match expected {
        SignerPinState::Unpinned => Ok(SignerAcceptance {
            next: SignerPinState::Current(CurrentSignerPins {
                source,
                workflows: WorkflowPins::for_channel(channel, workflow),
            }),
            transition: SignerTransition::FirstContact,
        }),
        SignerPinState::Legacy(pin) => {
            // Legacy locks got oidc_issuer from Fulcio extension 1.1; the source
            // issuer is extension 1.8. GitHub Actions writes the same
            // token.actions.githubusercontent.com value to both extensions.
            if pin.certificate_san != identity.certificate_san()
                || pin.oidc_issuer != identity.source().oidc_issuer
            {
                return Err(SignerRejection::LegacyIdentity);
            }
            Ok(SignerAcceptance {
                next: SignerPinState::Current(CurrentSignerPins {
                    source,
                    workflows: WorkflowPins::for_channel(channel, workflow),
                }),
                transition: SignerTransition::LegacyConverted,
            })
        }
        SignerPinState::Current(pins) => {
            if pins.source != source {
                return Err(SignerRejection::SourceMismatch {
                    expected: Box::new(pins.source.clone()),
                    actual: Box::new(source),
                });
            }
            match pins.workflows.workflow_for(channel) {
                Some(expected_workflow) if expected_workflow != &workflow => {
                    Err(SignerRejection::Workflow {
                        channel,
                        expected: expected_workflow.clone(),
                        actual: workflow,
                    })
                }
                Some(_) => Ok(SignerAcceptance {
                    next: expected.clone(),
                    transition: SignerTransition::Unchanged,
                }),
                None => Ok(SignerAcceptance {
                    next: SignerPinState::Current(CurrentSignerPins {
                        source: pins.source.clone(),
                        workflows: pins.workflows.clone().with_channel(channel, workflow),
                    }),
                    transition: SignerTransition::ChannelPinned(channel),
                }),
            }
        }
    }
}

impl WorkflowPins {
    fn for_channel(channel: ReleaseChannel, workflow: WorkflowPin) -> Self {
        match channel {
            ReleaseChannel::Stable => Self::Stable(workflow),
            ReleaseChannel::Prerelease => Self::Prerelease(workflow),
        }
    }

    fn workflow_for(&self, channel: ReleaseChannel) -> Option<&WorkflowPin> {
        match (self, channel) {
            (Self::Stable(workflow), ReleaseChannel::Stable)
            | (Self::Prerelease(workflow), ReleaseChannel::Prerelease) => Some(workflow),
            (Self::Both { stable, .. }, ReleaseChannel::Stable) => Some(stable),
            (Self::Both { prerelease, .. }, ReleaseChannel::Prerelease) => Some(prerelease),
            (Self::Stable(_), ReleaseChannel::Prerelease)
            | (Self::Prerelease(_), ReleaseChannel::Stable) => None,
        }
    }

    fn with_channel(self, channel: ReleaseChannel, workflow: WorkflowPin) -> Self {
        match (self, channel) {
            (Self::Stable(stable), ReleaseChannel::Prerelease) => Self::Both {
                stable,
                prerelease: workflow,
            },
            (Self::Prerelease(prerelease), ReleaseChannel::Stable) => Self::Both {
                stable: workflow,
                prerelease,
            },
            (existing, _) => existing,
        }
    }

    fn into_options(self) -> (Option<String>, Option<String>) {
        match self {
            Self::Stable(stable) => (Some(stable.0), None),
            Self::Prerelease(prerelease) => (None, Some(prerelease.0)),
            Self::Both { stable, prerelease } => (Some(stable.0), Some(prerelease.0)),
        }
    }

    fn merge(&self, other: &Self) -> Option<Self> {
        let stable = merge_optional_workflow(
            self.workflow_for(ReleaseChannel::Stable),
            other.workflow_for(ReleaseChannel::Stable),
        )?;
        let prerelease = merge_optional_workflow(
            self.workflow_for(ReleaseChannel::Prerelease),
            other.workflow_for(ReleaseChannel::Prerelease),
        )?;
        match (stable, prerelease) {
            (Some(stable), Some(prerelease)) => Some(Self::Both { stable, prerelease }),
            (Some(stable), None) => Some(Self::Stable(stable)),
            (None, Some(prerelease)) => Some(Self::Prerelease(prerelease)),
            (None, None) => None,
        }
    }
}

fn merge_optional_workflow(
    left: Option<&WorkflowPin>,
    right: Option<&WorkflowPin>,
) -> Option<Option<WorkflowPin>> {
    match (left, right) {
        (Some(left), Some(right)) if left != right => None,
        (Some(workflow), Some(_) | None) | (None, Some(workflow)) => Some(Some(workflow.clone())),
        (None, None) => Some(None),
    }
}

impl DiscardedSignerPins {
    fn merge(self, other: Self) -> Result<Self, RegistryIdentityPinConflict> {
        let conflict_left = self.clone();
        let conflict_right = other.clone();
        match (self, other) {
            (Self::Legacy(left), Self::Legacy(right)) if left == right => Ok(Self::Legacy(left)),
            (Self::Current(left), Self::Current(right)) if left.source == right.source => left
                .workflows
                .merge(&right.workflows)
                .map(|workflows| {
                    Self::Current(CurrentSignerPins {
                        source: left.source,
                        workflows,
                    })
                })
                .ok_or(RegistryIdentityPinConflict {
                    left: Box::new(conflict_left),
                    right: Box::new(conflict_right),
                }),
            _ => Err(RegistryIdentityPinConflict {
                left: Box::new(conflict_left),
                right: Box::new(conflict_right),
            }),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RegistryIdentityPinConflict {
    pub left: Box<DiscardedSignerPins>,
    pub right: Box<DiscardedSignerPins>,
}

#[derive(Debug)]
struct RegistryIdentityPinConflictRecord {
    provider: String,
    source: RegistryIdentityPinConflict,
}

impl fmt::Display for RegistryIdentityPinConflict {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "conflicting registry signer pins: {:?} and {:?}",
            self.left, self.right
        )
    }
}

impl std::error::Error for RegistryIdentityPinConflict {}

/// Freshness values discarded by an explicit registry re-bootstrap.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegistryFreshness {
    pub sequence: Option<u64>,
    pub sequence_anchor: Option<u64>,
}

enum RegistryRecoveryTarget<R> {
    Pinned {
        index: usize,
        sequence_anchor: RegistrySequenceAnchor,
        state: R,
    },
    Unpinned {
        state: R,
    },
}

impl<R> RegistryRecoveryTarget<R> {
    fn state(&self) -> &R {
        match self {
            Self::Pinned { state, .. } | Self::Unpinned { state } => state,
        }
    }

    fn sequence_anchor(&self) -> Option<RegistrySequenceAnchor> {
        match self {
            Self::Pinned {
                sequence_anchor, ..
            } => Some(*sequence_anchor),
            Self::Unpinned { .. } => None,
        }
    }

    fn map_state<S>(self, map: impl FnOnce(R) -> S) -> RegistryRecoveryTarget<S> {
        match self {
            Self::Pinned {
                index,
                sequence_anchor,
                state,
            } => RegistryRecoveryTarget::Pinned {
                index,
                sequence_anchor,
                state: map(state),
            },
            Self::Unpinned { state } => RegistryRecoveryTarget::Unpinned { state: map(state) },
        }
    }

    fn try_map_state<S, E>(
        self,
        map: impl FnOnce(R) -> Result<S, E>,
    ) -> Result<RegistryRecoveryTarget<S>, E> {
        match self {
            Self::Pinned {
                index,
                sequence_anchor,
                state,
            } => Ok(RegistryRecoveryTarget::Pinned {
                index,
                sequence_anchor,
                state: map(state)?,
            }),
            Self::Unpinned { state } => Ok(RegistryRecoveryTarget::Unpinned { state: map(state)? }),
        }
    }
}

/// Failure to inspect or mutate registry provider or host recovery state.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegistryLockRecoveryError {
    InvalidProvider { provider: String, reason: String },
    NotRegistryProvider { provider: String },
    ProviderStateNotFound { provider: String },
    RegistryHostStateNotFound { host: String },
    DiscoveryAlreadyUnpinned { host: String },
    SignatureNotRequired { provider: String },
    IdentityAlreadyUnpinned { provider: String },
    IdentityPinConflict(RegistryIdentityPinConflict),
}

impl fmt::Display for RegistryLockRecoveryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidProvider { provider, reason } => {
                write!(f, "Invalid registry provider {provider:?}: {reason}")
            }
            Self::NotRegistryProvider { provider } => write!(
                f,
                "Provider {provider:?} is not registry-hosted; provider recovery operations apply only to [hostname/]namespace/name sources"
            ),
            Self::ProviderStateNotFound { provider } => write!(
                f,
                "No registry security state for provider {provider:?} was found in carina-providers.lock"
            ),
            Self::RegistryHostStateNotFound { host } => write!(
                f,
                "No registry discovery state for host {host:?} was found in carina-providers.lock"
            ),
            Self::DiscoveryAlreadyUnpinned { host } => write!(
                f,
                "Registry host {host:?} is already awaiting a new discovery pin"
            ),
            Self::SignatureNotRequired { provider } => write!(
                f,
                "Registry provider {provider:?} has no ratcheted signature requirement or identity pin to replace"
            ),
            Self::IdentityAlreadyUnpinned { provider } => write!(
                f,
                "Registry provider {provider:?} already requires a signature and is awaiting a new identity pin"
            ),
            Self::IdentityPinConflict(error) => error.fmt(f),
        }
    }
}

impl std::error::Error for RegistryLockRecoveryError {}

/// Durable security observations for one registry source. Sequence anchors
/// are deliberately absent: only a successfully pinned [`RegistryLock`] can
/// carry an anti-rollback reference point or a pending reset marker.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(into = "RegistryRatchetsSerde")]
struct RegistryRatchets {
    sequence: RegistrySequence,
    valid_until_present: bool,
    yanked_versions: YankedRegistryVersions,
    signature: RegistrySignatureProtection,
    transparency_log_present: bool,
}

struct ResolvedRegistryRecovery {
    source_key: String,
    target: RegistryRecoveryTarget<RegistryRatchets>,
}

struct RegistryIdentityRepinState {
    pin: DiscardedSignerPins,
    residual: RegistryIdentityRepinResidual,
}

struct RegistryIdentityRepinResidual {
    sequence: RegistrySequence,
    valid_until_present: bool,
    yanked_versions: YankedRegistryVersions,
    transparency_log_present: bool,
}

struct RegistryRebootstrapState {
    sequence: RegistrySequence,
    residual: RegistryRebootstrapResidual,
}

struct RegistryRebootstrapResidual {
    valid_until_present: bool,
    yanked_versions: YankedRegistryVersions,
    signature: RegistrySignatureProtection,
    transparency_log_present: bool,
}

impl Default for RegistryRatchets {
    fn default() -> Self {
        Self {
            sequence: RegistrySequence::Absent,
            valid_until_present: false,
            yanked_versions: YankedRegistryVersions::default(),
            signature: RegistrySignatureProtection::NotRequired,
            transparency_log_present: false,
        }
    }
}

impl RegistryRatchets {
    fn merge(mut self, other: &Self) -> Result<Self, RegistryIdentityPinConflict> {
        let signature = self.signature.merge(&other.signature)?;
        self.sequence = match (self.sequence.value(), other.sequence.value()) {
            (Some(left), Some(right)) => RegistrySequence::Present(left.max(right)),
            (None, Some(sequence)) => RegistrySequence::Present(sequence),
            (Some(sequence), None) => RegistrySequence::Present(sequence),
            (None, None) => RegistrySequence::Absent,
        };
        self.valid_until_present |= other.valid_until_present;
        self.yanked_versions = self.yanked_versions.union(&other.yanked_versions);
        self.signature = signature;
        self.transparency_log_present |= other.transparency_log_present;
        Ok(self)
    }

    fn merge_into_registry(
        self,
        registry: &mut RegistryLock,
    ) -> Result<(), RegistryIdentityPinConflict> {
        let merged = RegistryRatchets::from(&*registry).merge(&self)?;
        let Self {
            sequence,
            valid_until_present,
            yanked_versions,
            signature,
            transparency_log_present,
        } = merged;
        registry.sequence = sequence;
        registry.valid_until_present = valid_until_present;
        registry.yanked_versions = yanked_versions;
        registry.signature = signature;
        registry.transparency_log_present = transparency_log_present;
        Ok(())
    }

    fn into_identity_repin_state(
        self,
        provider: String,
    ) -> Result<RegistryIdentityRepinState, RegistryLockRecoveryError> {
        let Self {
            sequence,
            valid_until_present,
            yanked_versions,
            signature,
            transparency_log_present,
        } = self;
        let pin = match signature {
            RegistrySignatureProtection::Required(SignerPinState::Legacy(pin)) => {
                DiscardedSignerPins::Legacy(pin)
            }
            RegistrySignatureProtection::Required(SignerPinState::Current(pins)) => {
                DiscardedSignerPins::Current(pins)
            }
            RegistrySignatureProtection::Required(SignerPinState::Unpinned) => {
                return Err(RegistryLockRecoveryError::IdentityAlreadyUnpinned { provider });
            }
            RegistrySignatureProtection::NotRequired => {
                return Err(RegistryLockRecoveryError::SignatureNotRequired { provider });
            }
        };
        Ok(RegistryIdentityRepinState {
            pin,
            residual: RegistryIdentityRepinResidual {
                sequence,
                valid_until_present,
                yanked_versions,
                transparency_log_present,
            },
        })
    }

    fn into_rebootstrap_state(self) -> RegistryRebootstrapState {
        let Self {
            sequence,
            valid_until_present,
            yanked_versions,
            signature,
            transparency_log_present,
        } = self;
        RegistryRebootstrapState {
            sequence,
            residual: RegistryRebootstrapResidual {
                valid_until_present,
                yanked_versions,
                signature,
                transparency_log_present,
            },
        }
    }
}

impl RegistryIdentityRepinResidual {
    fn into_ratchets(self) -> RegistryRatchets {
        RegistryRatchets {
            sequence: self.sequence,
            valid_until_present: self.valid_until_present,
            yanked_versions: self.yanked_versions,
            signature: RegistrySignatureProtection::Required(SignerPinState::Unpinned),
            transparency_log_present: self.transparency_log_present,
        }
    }

    fn apply_to_registry(self, registry: &mut RegistryLock) {
        let RegistryRatchets {
            sequence,
            valid_until_present,
            yanked_versions,
            signature,
            transparency_log_present,
        } = self.into_ratchets();
        registry.sequence = sequence;
        registry.valid_until_present = valid_until_present;
        registry.yanked_versions = yanked_versions;
        registry.signature = signature;
        registry.transparency_log_present = transparency_log_present;
    }
}

impl RegistryRebootstrapResidual {
    fn into_ratchets(self) -> RegistryRatchets {
        RegistryRatchets {
            sequence: RegistrySequence::Absent,
            valid_until_present: self.valid_until_present,
            yanked_versions: self.yanked_versions,
            signature: self.signature,
            transparency_log_present: self.transparency_log_present,
        }
    }

    fn apply_to_registry(self, registry: &mut RegistryLock) {
        let RegistryRatchets {
            sequence,
            valid_until_present,
            yanked_versions,
            signature,
            transparency_log_present,
        } = self.into_ratchets();
        registry.sequence = sequence;
        registry.valid_until_present = valid_until_present;
        registry.yanked_versions = yanked_versions;
        registry.signature = signature;
        registry.transparency_log_present = transparency_log_present;
    }
}

impl UnpinnedRegistryRatchets {
    fn commit_identity_repin(
        &mut self,
        source: &str,
        residual: RegistryIdentityRepinResidual,
    ) -> bool {
        let Some(ratchets) = self.0.get_mut(source) else {
            return false;
        };
        *ratchets = residual.into_ratchets();
        true
    }

    fn commit_rebootstrap(&mut self, source: &str, residual: RegistryRebootstrapResidual) -> bool {
        let Some(ratchets) = self.0.get_mut(source) else {
            return false;
        };
        *ratchets = residual.into_ratchets();
        true
    }
}

impl From<&RegistryLock> for RegistryRatchets {
    fn from(registry: &RegistryLock) -> Self {
        Self {
            sequence: registry.sequence.clone(),
            valid_until_present: registry.valid_until_present,
            yanked_versions: registry.yanked_versions.clone(),
            signature: registry.signature.clone(),
            transparency_log_present: registry.transparency_log_present,
        }
    }
}

#[derive(Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum RegistrySignatureStateSerde {
    NotRequired,
    RequiredUnpinned,
    RequiredLegacy,
    RequiredCurrent,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct RegistrySignatureProtectionSerde {
    signature_state: RegistrySignatureStateSerde,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    legacy_certificate_identity: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    legacy_certificate_oidc_issuer: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    source_oidc_issuer: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    source_repository_owner_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    source_repository_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    stable_workflow: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    prerelease_workflow: Option<String>,
}

impl TryFrom<RegistrySignatureProtectionSerde> for RegistrySignatureProtection {
    type Error = RegistryLockError;

    fn try_from(value: RegistrySignatureProtectionSerde) -> Result<Self, Self::Error> {
        let RegistrySignatureProtectionSerde {
            signature_state,
            legacy_certificate_identity,
            legacy_certificate_oidc_issuer,
            source_oidc_issuer,
            source_repository_owner_id,
            source_repository_id,
            stable_workflow,
            prerelease_workflow,
        } = value;
        let has_legacy =
            legacy_certificate_identity.is_some() || legacy_certificate_oidc_issuer.is_some();
        let has_current = source_oidc_issuer.is_some()
            || source_repository_owner_id.is_some()
            || source_repository_id.is_some()
            || stable_workflow.is_some()
            || prerelease_workflow.is_some();
        let state = match signature_state {
            RegistrySignatureStateSerde::NotRequired if !has_legacy && !has_current => {
                return Ok(Self::NotRequired);
            }
            RegistrySignatureStateSerde::RequiredUnpinned if !has_legacy && !has_current => {
                SignerPinState::Unpinned
            }
            RegistrySignatureStateSerde::RequiredLegacy if !has_current => {
                let (Some(certificate_san), Some(oidc_issuer)) =
                    (legacy_certificate_identity, legacy_certificate_oidc_issuer)
                else {
                    return Err(RegistryLockError::InconsistentSignature);
                };
                SignerPinState::Legacy(LegacySignerPin {
                    certificate_san,
                    oidc_issuer,
                })
            }
            RegistrySignatureStateSerde::RequiredCurrent if !has_legacy => {
                let (Some(oidc_issuer), Some(repository_owner_id), Some(repository_id)) = (
                    source_oidc_issuer,
                    source_repository_owner_id,
                    source_repository_id,
                ) else {
                    return Err(RegistryLockError::InconsistentSignature);
                };
                let workflows = match (stable_workflow, prerelease_workflow) {
                    (Some(stable), Some(prerelease)) => WorkflowPins::Both {
                        stable: WorkflowPin(stable),
                        prerelease: WorkflowPin(prerelease),
                    },
                    (Some(stable), None) => WorkflowPins::Stable(WorkflowPin(stable)),
                    (None, Some(prerelease)) => WorkflowPins::Prerelease(WorkflowPin(prerelease)),
                    (None, None) => return Err(RegistryLockError::InconsistentSignature),
                };
                SignerPinState::Current(CurrentSignerPins {
                    source: SourcePin {
                        oidc_issuer,
                        repository_owner_id,
                        repository_id,
                    },
                    workflows,
                })
            }
            RegistrySignatureStateSerde::NotRequired
            | RegistrySignatureStateSerde::RequiredUnpinned
            | RegistrySignatureStateSerde::RequiredLegacy
            | RegistrySignatureStateSerde::RequiredCurrent => {
                return Err(RegistryLockError::InconsistentSignature);
            }
        };
        Ok(Self::Required(state))
    }
}

impl From<RegistrySignatureProtection> for RegistrySignatureProtectionSerde {
    fn from(value: RegistrySignatureProtection) -> Self {
        match value {
            RegistrySignatureProtection::NotRequired => Self {
                signature_state: RegistrySignatureStateSerde::NotRequired,
                legacy_certificate_identity: None,
                legacy_certificate_oidc_issuer: None,
                source_oidc_issuer: None,
                source_repository_owner_id: None,
                source_repository_id: None,
                stable_workflow: None,
                prerelease_workflow: None,
            },
            RegistrySignatureProtection::Required(SignerPinState::Unpinned) => Self {
                signature_state: RegistrySignatureStateSerde::RequiredUnpinned,
                legacy_certificate_identity: None,
                legacy_certificate_oidc_issuer: None,
                source_oidc_issuer: None,
                source_repository_owner_id: None,
                source_repository_id: None,
                stable_workflow: None,
                prerelease_workflow: None,
            },
            RegistrySignatureProtection::Required(SignerPinState::Legacy(pin)) => Self {
                signature_state: RegistrySignatureStateSerde::RequiredLegacy,
                legacy_certificate_identity: Some(pin.certificate_san),
                legacy_certificate_oidc_issuer: Some(pin.oidc_issuer),
                source_oidc_issuer: None,
                source_repository_owner_id: None,
                source_repository_id: None,
                stable_workflow: None,
                prerelease_workflow: None,
            },
            RegistrySignatureProtection::Required(SignerPinState::Current(pins)) => {
                let (stable_workflow, prerelease_workflow) = pins.workflows.into_options();
                Self {
                    signature_state: RegistrySignatureStateSerde::RequiredCurrent,
                    legacy_certificate_identity: None,
                    legacy_certificate_oidc_issuer: None,
                    source_oidc_issuer: Some(pins.source.oidc_issuer),
                    source_repository_owner_id: Some(pins.source.repository_owner_id),
                    source_repository_id: Some(pins.source.repository_id),
                    stable_workflow,
                    prerelease_workflow,
                }
            }
        }
    }
}

impl Serialize for RegistrySignatureProtection {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        RegistrySignatureProtectionSerde::from(self.clone()).serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for RegistrySignatureProtection {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        RegistrySignatureProtectionSerde::deserialize(deserializer)?
            .try_into()
            .map_err(serde::de::Error::custom)
    }
}

fn sequence_from_wire(
    present: bool,
    sequence: Option<u64>,
) -> Result<RegistrySequence, RegistryLockError> {
    match (present, sequence) {
        (false, None) => Ok(RegistrySequence::Absent),
        (true, Some(sequence)) => Ok(RegistrySequence::Present(sequence)),
        _ => Err(RegistryLockError::InconsistentSequence),
    }
}

fn sequence_anchor_from_wire(
    established: bool,
    reset_pending: bool,
    sequence: Option<u64>,
) -> Result<RegistrySequenceAnchor, RegistryLockError> {
    match (established, reset_pending, sequence) {
        (false, false, None) => Ok(RegistrySequenceAnchor::Unestablished),
        (false, true, None) => Ok(RegistrySequenceAnchor::ResetPending),
        (true, false, Some(sequence)) => Ok(RegistrySequenceAnchor::Established(sequence)),
        _ => Err(RegistryLockError::InconsistentSequence),
    }
}

fn sequence_anchor_to_wire(anchor: RegistrySequenceAnchor) -> (bool, bool, Option<u64>) {
    match anchor {
        RegistrySequenceAnchor::Unestablished => (false, false, None),
        RegistrySequenceAnchor::ResetPending => (false, true, None),
        RegistrySequenceAnchor::Established(sequence) => (true, false, Some(sequence)),
    }
}

fn validate_sequence_anchor(
    sequence: &RegistrySequence,
    anchor: RegistrySequenceAnchor,
) -> Result<(), RegistryLockError> {
    match (sequence, anchor) {
        (RegistrySequence::Absent, RegistrySequenceAnchor::Established(_)) => {
            Err(RegistryLockError::InconsistentSequence)
        }
        (RegistrySequence::Present(observed), RegistrySequenceAnchor::Established(anchor))
            if anchor > *observed =>
        {
            Err(RegistryLockError::InconsistentSequence)
        }
        (
            RegistrySequence::Absent | RegistrySequence::Present(_),
            RegistrySequenceAnchor::Unestablished | RegistrySequenceAnchor::ResetPending,
        )
        | (RegistrySequence::Present(_), RegistrySequenceAnchor::Established(_)) => Ok(()),
    }
}

