#[derive(Debug)]
enum RegistryLockError {
    InconsistentSequence,
    InconsistentSignature,
}

impl fmt::Display for RegistryLockError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InconsistentSequence => write!(
                f,
                "registry lock is inconsistent: the sequence observation, reset-pending marker, and established sequence anchor must be encoded consistently, and an anchor cannot exceed its observation"
            ),
            Self::InconsistentSignature => write!(
                f,
                "registry lock is inconsistent: legacy certificate_identity and certificate_oidc_issuer must appear together, while current signer pins require exactly one source and at least one workflow"
            ),
        }
    }
}

impl std::error::Error for RegistryLockError {}

impl<'de> Deserialize<'de> for RegistryLock {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        RegistryLockSerde::deserialize(deserializer)?
            .try_into()
            .map_err(serde::de::Error::custom)
    }
}

impl RegistrySignatureProtection {
    fn is_required(&self) -> bool {
        matches!(self, Self::Required(_))
    }

    fn pin_state(&self) -> Option<&SignerPinState> {
        match self {
            Self::Required(state) => Some(state),
            Self::NotRequired => None,
        }
    }

    fn established_pins(&self) -> Option<DiscardedSignerPins> {
        match self {
            Self::Required(SignerPinState::Legacy(pin)) => {
                Some(DiscardedSignerPins::Legacy(pin.clone()))
            }
            Self::Required(SignerPinState::Current(pins)) => {
                Some(DiscardedSignerPins::Current(pins.clone()))
            }
            Self::NotRequired | Self::Required(SignerPinState::Unpinned) => None,
        }
    }

    fn merge(&self, other: &Self) -> Result<Self, RegistryIdentityPinConflict> {
        let required = self.is_required() || other.is_required();
        let pins = match (self.established_pins(), other.established_pins()) {
            (Some(left), Some(right)) => Some(left.merge(right)?),
            (Some(pin), None) | (None, Some(pin)) => Some(pin),
            (None, None) => None,
        };
        Ok(match pins {
            Some(DiscardedSignerPins::Legacy(pin)) => Self::Required(SignerPinState::Legacy(pin)),
            Some(DiscardedSignerPins::Current(pins)) => {
                Self::Required(SignerPinState::Current(pins))
            }
            None if required => Self::Required(SignerPinState::Unpinned),
            None => Self::NotRequired,
        })
    }
}

impl RegistrySequence {
    fn value(&self) -> Option<u64> {
        match self {
            Self::Absent => None,
            Self::Present(sequence) => Some(*sequence),
        }
    }
}

impl RegistrySequenceAnchor {
    fn value(self) -> Option<u64> {
        match self {
            Self::Unestablished | Self::ResetPending => None,
            Self::Established(sequence) => Some(sequence),
        }
    }

    fn into_previous_state(self) -> RegistrySequencePreviousState {
        match self {
            Self::Unestablished => RegistrySequencePreviousState::Unestablished,
            Self::ResetPending => RegistrySequencePreviousState::ResetPending,
            Self::Established(sequence) => RegistrySequencePreviousState::Established(sequence),
        }
    }
}

impl RegistryLock {
    pub fn resolved_hostname(&self) -> &str {
        self.resolved_hostname.as_str()
    }

    pub fn yanked_versions(&self) -> &YankedRegistryVersions {
        &self.yanked_versions
    }
}

/// Why a raw lock entry could not be represented by the current typed schema.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LegacyReason {
    GithubDirectVersionWithoutTag {
        version: String,
        sha256: String,
    },
    RevisionWithoutArtifactId {
        revision: String,
        resolved_sha: CommitSha,
        sha256: String,
    },
}

impl fmt::Display for LegacyReason {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::GithubDirectVersionWithoutTag { version, sha256: _ } => write!(
                formatter,
                "GitHub direct version entry {version} without an exact release tag"
            ),
            Self::RevisionWithoutArtifactId {
                revision,
                resolved_sha,
                sha256: _,
            } => write!(
                formatter,
                "GitHub revision entry {revision} at {resolved_sha} without an artifact ID"
            ),
        }
    }
}

/// A raw legacy lock entry retained for safe migration or a typed error.
#[derive(Debug, Clone, PartialEq)]
pub struct LegacyLockEntry {
    pub source: String,
    pub reason: LegacyReason,
    raw: toml::Table,
}

impl LegacyLockEntry {
    fn error(&self, project_dir: &Path) -> LegacyLockEntryError {
        LegacyLockEntryError {
            source: self.source.clone(),
            reason: self.reason.clone(),
            project_dir: project_dir.to_path_buf(),
        }
    }
}

/// Why a GitHub-direct legacy table could not be retained safely.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LegacyLockEntryParseError {
    /// A checksum or version pin was absent or was not a TOML string.
    MissingStringField { source: String, field: &'static str },
    /// The legacy version pin is not a semantic version.
    InvalidVersion { source: String, version: String },
    /// The legacy revision pin does not contain a canonical Git commit SHA.
    InvalidResolvedSha { source: String, value: String },
}

impl fmt::Display for LegacyLockEntryParseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingStringField { source, field } => write!(
                formatter,
                "legacy GitHub version entry for '{source}' is missing string field '{field}'"
            ),
            Self::InvalidVersion { source, version } => write!(
                formatter,
                "legacy GitHub version entry for '{source}' has invalid semantic version '{version}'"
            ),
            Self::InvalidResolvedSha { source, value } => write!(
                formatter,
                "legacy GitHub revision entry for '{source}' has invalid resolved SHA '{value}'"
            ),
        }
    }
}

impl std::error::Error for LegacyLockEntryParseError {}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LegacyLockEntryError {
    pub source: String,
    pub reason: LegacyReason,
    project_dir: PathBuf,
}

impl fmt::Display for LegacyLockEntryError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "carina-providers.lock contains a legacy entry for '{}' ({}). Run `{}` to re-resolve it and rewrite the lock.",
            self.source,
            self.reason,
            ProjectCommand::new("init", &self.project_dir)
        )
    }
}

impl std::error::Error for LegacyLockEntryError {}

fn github_direct_version_without_tag(
    entry: &toml::Table,
) -> Result<Option<(String, LegacyReason)>, LegacyLockEntryParseError> {
    if entry.get("mode").and_then(toml::Value::as_str) != Some("version") {
        return Ok(None);
    }
    let Some(source) = entry.get("source").and_then(toml::Value::as_str) else {
        return Ok(None);
    };
    if !matches!(
        source.parse::<ProviderSource>(),
        Ok(ProviderSource::Remote(RemoteSource::GithubDirect(_)))
    ) {
        return Ok(None);
    }
    let required = |field: &'static str| {
        entry
            .get(field)
            .and_then(toml::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| LegacyLockEntryParseError::MissingStringField {
                source: source.to_string(),
                field,
            })
    };
    let version = required("version")?;
    Version::parse(&version).map_err(|_| LegacyLockEntryParseError::InvalidVersion {
        source: source.to_string(),
        version: version.clone(),
    })?;
    Ok(Some((
        source.to_string(),
        LegacyReason::GithubDirectVersionWithoutTag {
            version,
            sha256: required("sha256")?,
        },
    )))
}

fn revision_without_artifact_id(
    entry: &toml::Table,
) -> Result<Option<(String, LegacyReason)>, LegacyLockEntryParseError> {
    const REQUIRED_KEYS: [&str; 6] = [
        "name",
        "source",
        "mode",
        "revision",
        "resolved_sha",
        "sha256",
    ];

    if entry.get("mode").and_then(toml::Value::as_str) != Some("revision") {
        return Ok(None);
    }
    let Some(source) = entry.get("source").and_then(toml::Value::as_str) else {
        return Ok(None);
    };
    if !matches!(
        source.parse::<ProviderSource>(),
        Ok(ProviderSource::Remote(RemoteSource::GithubDirect(_)))
    ) {
        return Ok(None);
    }
    let expected_len = REQUIRED_KEYS.len() + usize::from(entry.contains_key("registry"));
    if entry.len() != expected_len || !REQUIRED_KEYS.iter().all(|key| entry.contains_key(*key)) {
        return Ok(None);
    }
    let required = |field: &'static str| {
        entry
            .get(field)
            .and_then(toml::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| LegacyLockEntryParseError::MissingStringField {
                source: source.to_string(),
                field,
            })
    };
    let resolved_sha = required("resolved_sha")?;
    let resolved_sha = CommitSha::new(resolved_sha.clone()).map_err(|_| {
        LegacyLockEntryParseError::InvalidResolvedSha {
            source: source.to_string(),
            value: resolved_sha,
        }
    })?;
    Ok(Some((
        source.to_string(),
        LegacyReason::RevisionWithoutArtifactId {
            revision: required("revision")?,
            resolved_sha,
            sha256: required("sha256")?,
        },
    )))
}

/// Split migratable legacy entries from tables accepted by the typed schema.
pub(crate) fn split_legacy_entries(
    entries: Vec<toml::Table>,
) -> Result<(Vec<toml::Table>, Vec<LegacyLockEntry>), LegacyLockEntryParseError> {
    let mut retained = Vec::with_capacity(entries.len());
    let mut legacy = Vec::new();
    for entry in entries {
        let classified =
            github_direct_version_without_tag(&entry)?.or(revision_without_artifact_id(&entry)?);
        match classified {
            Some((source, reason)) => {
                legacy.push(LegacyLockEntry {
                    source,
                    reason,
                    raw: entry,
                });
            }
            None => retained.push(entry),
        }
    }
    Ok((retained, legacy))
}

/// The full carina-providers.lock file.
///
/// `LockFile` deliberately implements neither `Serialize` nor `Deserialize`.
/// Serialization is performed by [`GuardedLockFile::save`], while
/// deserialization is routed through [`Self::load`], which checks the format
/// version before the current schema can consume or rewrite the file.
#[derive(Debug, Clone)]
pub struct LockFile {
    version: u32,
    registry_host: BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
    pub provider: Vec<LockEntry<RegistryLock>>,
    egress: BTreeMap<EgressArtifactKey, crate::EgressLockRecord>,
    legacy: Vec<LegacyLockEntry>,
    unpinned_registry_ratchets: UnpinnedRegistryRatchets,
}

/// Identity of the lock entry that owns an egress record.
///
/// Remote provider sources can legitimately have multiple locked artifacts,
/// so the source alone is not an artifact identity.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct EgressArtifactKey {
    source: String,
    sha256: String,
}

impl EgressArtifactKey {
    fn from_entry(entry: &LockEntry<RegistryLock>) -> Self {
        Self {
            source: canonical_lock_source(&entry.source),
            sha256: entry.sha256.clone(),
        }
    }
}

enum SourceLockEntry<'a> {
    Typed(&'a LockEntry<RegistryLock>),
    Legacy(&'a LegacyLockEntry),
}

/// The crate-internal serialization view of [`LockFile`]. Field order and
/// omission rules are part of the lock-file byte format and must stay aligned
/// with the former direct `LockFile` serialization.
#[derive(Serialize)]
struct SerializableLockFile<'a> {
    version: &'a u32,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    registry_host: &'a BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
    provider: Vec<SerializableProviderEntry<'a>>,
    #[serde(default, skip_serializing_if = "UnpinnedRegistryRatchets::is_empty")]
    unpinned_registry_ratchets: &'a UnpinnedRegistryRatchets,
}

#[derive(Serialize)]
#[serde(untagged)]
enum SerializableProviderEntry<'a> {
    Current(SerializableCurrentProviderEntry<'a>),
    Legacy(&'a toml::Table),
}

#[derive(Serialize)]
struct SerializableCurrentProviderEntry<'a> {
    #[serde(flatten)]
    entry: &'a LockEntry<RegistryLock>,
    #[serde(skip_serializing_if = "Option::is_none")]
    egress: Option<&'a crate::EgressLockRecord>,
}

mod registry_lock_with_host {
    use super::*;

    /// A provider registry record paired with the host pin it references. This
    /// is the only result of converting verified discovery into persisted state.
    pub(super) struct RegistryLockWithHost {
        host: (CanonicalRegistryHostname, RegistryHostLock),
        registry: RegistryLock,
        sequence_notice: Option<RegistrySequenceNotice>,
    }

    impl RegistryLock {
        pub(super) fn from_resolved_registry(
            registry: ResolvedRegistry,
            ratchets: RegistryRatchets,
            validated_sequence: ValidatedRegistrySequence,
            source_key: &RemoteSourceKey,
        ) -> RegistryLockWithHost {
            let ResolvedRegistry {
                hostname,
                discovery_pin,
            } = registry;
            let RegistryRatchets {
                sequence,
                valid_until_present,
                yanked_versions,
                signature,
                transparency_log_present,
            } = ratchets;
            let (sequence_anchor, sequence_notice) =
                validated_sequence.into_anchor_and_notice(source_key);
            let hostname = CanonicalRegistryHostname::from(hostname);
            RegistryLockWithHost {
                host: (hostname.clone(), RegistryHostLock::pinned(discovery_pin)),
                registry: Self {
                    resolved_hostname: hostname,
                    sequence,
                    sequence_anchor,
                    valid_until_present,
                    yanked_versions,
                    signature,
                    transparency_log_present,
                },
                sequence_notice,
            }
        }
    }

    impl GuardedLockFile<'_> {
        /// Insert a registry provider together with its host record and the
        /// notice released by the guarded lock's next successful save.
        pub(super) fn upsert_registry_with_host(
            &mut self,
            entry: LockEntry<NoRegistryLock>,
            registry_with_host: RegistryLockWithHost,
        ) {
            let RegistryLockWithHost {
                host: (hostname, host),
                registry,
                sequence_notice,
            } = registry_with_host;
            self.registry_host.insert(hostname, host);

            let mut entry = entry.into_stored();
            entry.registry = Some(registry);
            self.upsert_entry(entry);
            self.queue_registry_sequence_notice(sequence_notice);
        }
    }
}

/// A validated identity re-pin that has not mutated its lock file yet.
/// The exclusive borrow keeps the previewed state unchanged until this value
/// is either consumed by [`Self::commit`] or dropped.
pub struct PreparedRegistryIdentityRepin<'a> {
    lock_file: &'a mut LockFile,
    source_key: String,
    target: RegistryRecoveryTarget<RegistryIdentityRepinState>,
}

/// A validated registry re-bootstrap that has not mutated its lock file yet.
/// The exclusive borrow keeps the previewed state unchanged until this value
/// is either consumed by [`Self::commit`] or dropped.
pub struct PreparedRegistryRebootstrap<'a> {
    lock_file: &'a mut LockFile,
    source_key: String,
    target: RegistryRecoveryTarget<RegistryRebootstrapState>,
}

/// A validated host discovery re-pin that holds the one resolved host record
/// used by commit and the concrete values it will discard.
pub struct PreparedRegistryDiscoveryRepin<'a> {
    host: &'a mut RegistryHostLock,
    hostname: String,
    discarded: PreparedRegistryDiscoveryRepinState,
}

enum PreparedRegistryDiscoveryRepinState {
    Pinned {
        discarded: RegistryDiscoveryPin,
        retained: UnconsumedDiscoveryValues,
    },
    MigrationPending(LegacyRegistryDiscoveryPins),
}

