#[derive(Default, Deserialize)]
#[serde(transparent)]
struct UnpinnedRegistryRatchetsV3(BTreeMap<String, RegistryRatchetsV3>);

/// Yank observations written by 3a080a0d before v1 generalized the root-level
/// storage into `unpinned_registry_ratchets`.
#[derive(Default, Deserialize)]
#[serde(transparent)]
struct UnpinnedRegistryYanksV1(BTreeMap<String, BTreeSet<String>>);

impl RegistryLockV1 {
    fn into_v3(
        self,
    ) -> (
        CanonicalRegistryHostname,
        LegacyRegistryDiscoveryPin,
        RegistryLockV3,
    ) {
        let Self {
            resolved_hostname,
            api_base_url,
            discovery_sha256,
            sequence_present,
            sequence,
            sequence_anchor_established,
            sequence_anchor,
            valid_until_present,
            yanked_versions,
            signature_present,
            certificate_identity,
            certificate_oidc_issuer,
            transparency_log_present,
        } = self;
        let (sequence_anchor_established, sequence_anchor) = match sequence_anchor_established {
            Some(established) => (established, sequence_anchor),
            // Before 7ef946a9, `sequence` itself was both the greatest
            // observation and the rollback/fast-forward baseline.
            None if sequence_anchor.is_none() => (sequence_present, sequence),
            // This combination was never emitted. Preserve it as an
            // inconsistent wire pair so the shared v3 validator rejects it.
            None => (false, sequence_anchor),
        };
        let discovery_pin = LegacyRegistryDiscoveryPin {
            api_base_url,
            discovery_sha256,
        };
        let registry = RegistryLockV3 {
            resolved_hostname: resolved_hostname.clone(),
            sequence_present,
            sequence,
            sequence_anchor_established,
            sequence_anchor,
            valid_until_present,
            yanked_versions,
            signature_present,
            certificate_identity,
            certificate_oidc_issuer,
            transparency_log_present,
        };
        (resolved_hostname, discovery_pin, registry)
    }
}

struct MigratedV1ProviderEntries {
    registry_host: BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
    discarded_discovery_pins: BTreeMap<CanonicalRegistryHostname, LegacyRegistryDiscoveryPins>,
    provider: Vec<LockEntry<RegistryLockV3>>,
}

fn migrate_v1_provider_entries(
    entries: Vec<LockEntry<RegistryLockV1>>,
) -> MigratedV1ProviderEntries {
    let mut discovery_pins: BTreeMap<CanonicalRegistryHostname, LegacyRegistryDiscoveryPins> =
        BTreeMap::new();
    let mut provider = Vec::with_capacity(entries.len());
    for entry in entries {
        let registry = match entry.registry {
            Some(registry) => {
                let (hostname, discovery_pin, registry) = registry.into_v3();
                discovery_pins
                    .entry(hostname)
                    .and_modify(|pins| pins.insert(discovery_pin.clone()))
                    .or_insert_with(|| discovery_pin.into());
                Some(registry)
            }
            None => None,
        };
        provider.push(LockEntry {
            name: entry.name,
            source: entry.source,
            kind: entry.kind,
            sha256: entry.sha256,
            registry,
        });
    }
    let registry_host = discovery_pins
        .iter()
        .map(|(hostname, pins)| {
            (
                hostname.clone(),
                RegistryHostLock {
                    discovery: RegistryDiscoveryPinState::MigrationPendingAuthorization(
                        pins.clone(),
                    ),
                },
            )
        })
        .collect();
    MigratedV1ProviderEntries {
        registry_host,
        discarded_discovery_pins: discovery_pins,
        provider,
    }
}

fn merge_v1_unpinned_registry_yanks(
    yanks: UnpinnedRegistryYanksV1,
    mut ratchets: UnpinnedRegistryRatchetsV3,
) -> UnpinnedRegistryRatchetsV3 {
    for (source, yanked_versions) in yanks.0 {
        ratchets
            .0
            .entry(source)
            .or_default()
            .yanked_versions
            .extend(yanked_versions);
    }
    ratchets
}

fn signature_from_v3(
    signature_present: bool,
    certificate_identity: Option<String>,
    certificate_oidc_issuer: Option<String>,
) -> Result<RegistrySignatureProtection, RegistryLockError> {
    match (
        signature_present,
        certificate_identity,
        certificate_oidc_issuer,
    ) {
        (false, None, None) => Ok(RegistrySignatureProtection::NotRequired),
        (true, None, None) => Ok(RegistrySignatureProtection::Required(
            SignerPinState::Unpinned,
        )),
        (true, Some(certificate_san), Some(oidc_issuer)) => Ok(
            RegistrySignatureProtection::Required(SignerPinState::Legacy(LegacySignerPin {
                certificate_san,
                oidc_issuer,
            })),
        ),
        _ => Err(RegistryLockError::InconsistentSignature),
    }
}

impl TryFrom<RegistryLockV3> for RegistryLock {
    type Error = RegistryLockError;

    fn try_from(value: RegistryLockV3) -> Result<Self, Self::Error> {
        let sequence = sequence_from_wire(value.sequence_present, value.sequence)?;
        let sequence_anchor = sequence_anchor_from_wire(
            value.sequence_anchor_established,
            false,
            value.sequence_anchor,
        )?;
        validate_sequence_anchor(&sequence, sequence_anchor)?;
        Ok(Self {
            resolved_hostname: value.resolved_hostname,
            sequence,
            sequence_anchor,
            valid_until_present: value.valid_until_present,
            yanked_versions: YankedRegistryVersions::from_serialized(value.yanked_versions),
            signature: signature_from_v3(
                value.signature_present,
                value.certificate_identity,
                value.certificate_oidc_issuer,
            )?,
            transparency_log_present: value.transparency_log_present,
        })
    }
}

impl TryFrom<RegistryRatchetsV3> for RegistryRatchets {
    type Error = RegistryLockError;

    fn try_from(value: RegistryRatchetsV3) -> Result<Self, Self::Error> {
        Ok(Self {
            sequence: sequence_from_wire(value.sequence_present, value.sequence)?,
            valid_until_present: value.valid_until_present,
            yanked_versions: YankedRegistryVersions::from_serialized(value.yanked_versions),
            signature: signature_from_v3(
                value.signature_present,
                value.certificate_identity,
                value.certificate_oidc_issuer,
            )?,
            transparency_log_present: value.transparency_log_present,
        })
    }
}

fn migrate_v3_provider_entries(
    entries: Vec<LockEntry<RegistryLockV3>>,
) -> Result<Vec<LockEntry<RegistryLock>>, RegistryLockError> {
    entries
        .into_iter()
        .map(|entry| {
            Ok(LockEntry {
                name: entry.name,
                source: entry.source,
                kind: entry.kind,
                sha256: entry.sha256,
                registry: entry.registry.map(TryInto::try_into).transpose()?,
            })
        })
        .collect()
}

fn migrate_v3_ratchets(
    ratchets: UnpinnedRegistryRatchetsV3,
) -> Result<UnpinnedRegistryRatchets, RegistryLockError> {
    ratchets
        .0
        .into_iter()
        .map(|(source, ratchets)| Ok((source, ratchets.try_into()?)))
        .collect::<Result<BTreeMap<_, _>, RegistryLockError>>()
        .map(UnpinnedRegistryRatchets)
}

fn migrate_legacy_registry_hosts(
    legacy_hosts: BTreeMap<CanonicalRegistryHostname, LegacyRegistryHostLock>,
) -> (
    BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
    BTreeMap<CanonicalRegistryHostname, LegacyRegistryDiscoveryPins>,
) {
    let mut discarded_discovery_pins = BTreeMap::new();
    let registry_host = legacy_hosts
        .into_iter()
        .map(|(host, legacy_host)| {
            let discovery = match legacy_host.discovery {
                LegacyRegistryDiscoveryPinState::Pinned(pin) => {
                    let pins = LegacyRegistryDiscoveryPins::from(pin);
                    discarded_discovery_pins.insert(host.clone(), pins.clone());
                    RegistryDiscoveryPinState::MigrationPendingAuthorization(pins)
                }
                LegacyRegistryDiscoveryPinState::Unpinned => {
                    RegistryDiscoveryPinState::Unpinned(UnconsumedDiscoveryValues::default())
                }
            };
            (host, RegistryHostLock { discovery })
        })
        .collect();
    (registry_host, discarded_discovery_pins)
}

fn canonicalize_registry_host_keys<T>(
    registry_host: BTreeMap<String, T>,
    path: &Path,
) -> Result<BTreeMap<CanonicalRegistryHostname, T>, LockFileError> {
    let mut canonical = BTreeMap::new();
    for (hostname, host) in registry_host {
        let hostname = CanonicalRegistryHostname::from(hostname);
        if canonical.insert(hostname.clone(), host).is_some() {
            return Err(LockFileError::RegistryHostKeyConflict {
                path: path.to_path_buf(),
                hostname: hostname.to_string(),
            });
        }
    }
    Ok(canonical)
}

fn parse_lock_toml<T>(content: &str, path: &Path) -> Result<T, LockFileError>
where
    T: DeserializeOwned,
{
    toml::from_str(content).map_err(|source| LockFileError::Parse {
        path: path.to_path_buf(),
        source,
    })
}

fn parse_lock_table<T>(table: &toml::Table, path: &Path) -> Result<T, LockFileError>
where
    T: DeserializeOwned,
{
    toml::Value::Table(table.clone())
        .try_into()
        .map_err(|source| LockFileError::Parse {
            path: path.to_path_buf(),
            source,
        })
}

fn split_lock_table_legacy_entries(
    content: &str,
    path: &Path,
) -> Result<(toml::Table, Vec<LegacyLockEntry>), LockFileError> {
    let mut table: toml::Table = parse_lock_toml(content, path)?;
    let entries = match table.remove("provider") {
        Some(value) => {
            value
                .try_into::<Vec<toml::Table>>()
                .map_err(|source| LockFileError::Parse {
                    path: path.to_path_buf(),
                    source,
                })?
        }
        None => Vec::new(),
    };
    let (retained, legacy) =
        split_legacy_entries(entries).map_err(|source| LockFileError::LegacyEntryParse {
            path: path.to_path_buf(),
            source,
        })?;
    table.insert(
        "provider".to_string(),
        toml::Value::Array(retained.into_iter().map(toml::Value::Table).collect()),
    );
    Ok((table, legacy))
}

/// Details of a provider-lock migration applied in memory.
///
/// The event carries every legacy discovery pin that now requires operator
/// authorization before it can be discarded, plus legacy GitHub sources that
/// remain verbatim until successful resolution replaces them. The load
/// operation itself never rewrites the on-disk file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LockFileMigration {
    project_dir: PathBuf,
    from: u32,
    to: u32,
    discarded_discovery_pins: BTreeMap<CanonicalRegistryHostname, LegacyRegistryDiscoveryPins>,
    legacy_sources: Vec<String>,
}

impl LockFileMigration {
    pub fn discarded_discovery_pins(
        &self,
        host: &str,
    ) -> Option<impl ExactSizeIterator<Item = &LegacyRegistryDiscoveryPin>> {
        let host = CanonicalRegistryHostname::from(host);
        self.discarded_discovery_pins
            .get(host.as_str())
            .map(LegacyRegistryDiscoveryPins::iter)
    }

    fn fmt_with_discovery_repin(
        &self,
        f: &mut fmt::Formatter<'_>,
        repinned_host: Option<&str>,
    ) -> fmt::Result {
        writeln!(
            f,
            "Provider lock format migration: version {} -> version {}",
            self.from, self.to
        )?;
        writeln!(
            f,
            "Lock file: {}",
            provider_lock_path(&self.project_dir).display()
        )?;
        if !self.legacy_sources.is_empty() {
            writeln!(f, "Legacy GitHub entries retained for conversion:")?;
            for source in &self.legacy_sources {
                writeln!(f, "  {source}")?;
            }
            writeln!(
                f,
                "Each entry remains verbatim until a successful `{}` replaces it with an exact release tag and asset ID or a revision artifact ID.",
                ProjectCommand::new("init", &self.project_dir)
            )?;
        }
        if self.discarded_discovery_pins.is_empty() {
            if self.from <= 2 {
                writeln!(
                    f,
                    "Migration found no v{} discovery pins requiring operator authorization.",
                    self.from
                )?;
            } else if self.from == 4 && self.to == 5 {
                writeln!(
                    f,
                    "Version 5 adds only the optional reset-pending sequence-anchor marker; existing v4 lock state is unchanged."
                )?;
            } else if self.from < self.to {
                writeln!(
                    f,
                    "Existing signer state is preserved; any legacy signer pin remains gated until verified conversion."
                )?;
            }
            writeln!(
                f,
                "All provider entries and provider security state will be retained."
            )?;
            return write!(
                f,
                "The on-disk lock remains unchanged until Carina next saves it."
            );
        }
        for (host, pins) in &self.discarded_discovery_pins {
            writeln!(f, "Registry host: {host}")?;
            if repinned_host == Some(host.as_str()) {
                for pin in pins.iter() {
                    writeln!(
                        f,
                        "Discarding v{} pinned discovery API base: {}",
                        self.from, pin.api_base_url
                    )?;
                    writeln!(
                        f,
                        "Discarding v{} discovery document SHA-256: {}",
                        self.from, pin.discovery_sha256
                    )?;
                }
            } else {
                for pin in pins.iter() {
                    writeln!(
                        f,
                        "Retaining v{} pinned discovery API base pending authorization: {}",
                        self.from, pin.api_base_url
                    )?;
                    writeln!(
                        f,
                        "Retaining v{} discovery document SHA-256 pending authorization: {}",
                        self.from, pin.discovery_sha256
                    )?;
                }
                let refusal = RegistryRefusal::DiscoveryMigrationAuthorizationRequired {
                    target: HostRefusalTarget::new(host.as_str(), &self.project_dir),
                };
                writeln!(f, "{refusal}")?;
            }
        }
        writeln!(
            f,
            "All provider entries and provider security state will be retained."
        )?;
        write!(
            f,
            "The on-disk lock remains unchanged until Carina next saves it."
        )
    }
}

impl fmt::Display for LockFileMigration {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.fmt_with_discovery_repin(f, None)
    }
}

struct ParsedLegacyLockBody {
    registry_host: BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
    provider: Vec<LockEntry<RegistryLockV3>>,
    unpinned_registry_ratchets: UnpinnedRegistryRatchetsV3,
    discarded_discovery_pins: BTreeMap<CanonicalRegistryHostname, LegacyRegistryDiscoveryPins>,
}

fn finish_legacy_lock_migration(
    from: u32,
    body: ParsedLegacyLockBody,
    legacy: Vec<LegacyLockEntry>,
    path: &Path,
    project_dir: &Path,
) -> Result<LoadedLockFile, LockFileError> {
    let legacy_sources = legacy.iter().map(|entry| entry.source.clone()).collect();
    let ParsedLegacyLockBody {
        registry_host,
        provider,
        unpinned_registry_ratchets,
        discarded_discovery_pins,
    } = body;
    let provider = migrate_v3_provider_entries(provider).map_err(|error| {
        LockFileError::InvalidRegistryState {
            path: path.to_path_buf(),
            detail: error.to_string(),
        }
    })?;
    let unpinned_registry_ratchets =
        migrate_v3_ratchets(unpinned_registry_ratchets).map_err(|error| {
            LockFileError::InvalidRegistryState {
                path: path.to_path_buf(),
                detail: error.to_string(),
            }
        })?;
    let lock_file = LockFile::from_parts(
        registry_host,
        provider,
        BTreeMap::new(),
        unpinned_registry_ratchets,
        legacy,
        path,
        project_dir,
    )?;
    let migration = LockFileMigration {
        project_dir: project_dir.to_path_buf(),
        from,
        to: LockFile::CURRENT_VERSION,
        discarded_discovery_pins,
        legacy_sources,
    };
    Ok(LoadedLockFile::Migrated {
        lock_file,
        migration,
    })
}

/// A provider lock tagged with whether load migrated its wire format.
///
/// Production callers destructure this result so retained legacy security
/// state can be surfaced alongside the in-memory current-format lock.
#[derive(Debug)]
pub enum LoadedLockFile {
    Pristine(LockFile),
    Migrated {
        lock_file: LockFile,
        migration: LockFileMigration,
    },
}

impl LoadedLockFile {
    pub fn into_parts(self) -> (LockFile, Option<LockFileMigration>) {
        match self {
            Self::Pristine(lock_file) => (lock_file, None),
            Self::Migrated {
                lock_file,
                migration,
            } => (lock_file, Some(migration)),
        }
    }

    #[cfg(test)]
    fn into_lock_file(self) -> LockFile {
        self.into_parts().0
    }

    fn into_resolution_lock_file(self) -> LockFile {
        match self {
            Self::Pristine(lock_file) => lock_file,
            Self::Migrated {
                lock_file,
                migration,
            } => {
                eprintln!("{migration}");
                lock_file
            }
        }
    }
}

/// Keep the complete error variant set and its rendered-message samples in one
/// declaration. Adding a variant cannot compile until it also supplies the
/// sample scanned by `lock_file_error_messages_never_instruct_wholesale_deletion`.
macro_rules! define_lock_file_error {
    ($($variant:ident $fields:tt => $sample:expr),+ $(,)?) => {
        #[derive(Debug)]
        pub enum LockFileError {
            $($variant $fields,)+
        }

        #[cfg(test)]
        impl LockFileError {
            fn display_test_samples() -> Vec<(&'static str, Self)> {
                vec![$((stringify!($variant), $sample),)+]
            }
        }
    };
}

define_lock_file_error! {
    Read {
        path: PathBuf,
        source: io::Error,
    } => Self::Read {
        path: PathBuf::from("carina-providers.lock"),
        source: io::Error::new(io::ErrorKind::PermissionDenied, "permission denied"),
    },
    MissingVersion {
        path: PathBuf,
    } => Self::MissingVersion {
        path: PathBuf::from("carina-providers.lock"),
    },
    VersionTooNew {
        found: u32,
        supported: u32,
    } => Self::VersionTooNew {
        found: LockFile::CURRENT_VERSION + 1,
        supported: LockFile::CURRENT_VERSION,
    },
    InvalidVersion {
        found: u32,
    } => Self::InvalidVersion {
        found: 0,
    },
    MissingRegistryHostRecord {
        project_dir: PathBuf,
        provider: String,
        hostname: String,
    } => Self::MissingRegistryHostRecord {
        project_dir: PathBuf::from("."),
        provider: "carina-rs/aws".into(),
        hostname: "registry.carina-rs.dev".into(),
    },
    RegistryHostKeyConflict {
        path: PathBuf,
        hostname: String,
    } => Self::RegistryHostKeyConflict {
        path: PathBuf::from("carina-providers.lock"),
        hostname: "registry.carina-rs.dev".into(),
    },
    Parse {
        path: PathBuf,
        source: toml::de::Error,
    } => {
        let source = match toml::from_str::<LockFileVersion>("version = [") {
            Ok(_) => panic!("malformed TOML unexpectedly parsed"),
            Err(error) => error,
        };
        Self::Parse {
            path: PathBuf::from("carina-providers.lock"),
            source,
        }
    },
    LegacyEntryParse {
        path: PathBuf,
        source: LegacyLockEntryParseError,
    } => Self::LegacyEntryParse {
        path: PathBuf::from("carina-providers.lock"),
        source: LegacyLockEntryParseError::MissingStringField {
            source: "github.com/acme/widget".into(),
            field: "sha256",
        },
    },
    InvalidGithubReleasePin {
        path: PathBuf,
        source: String,
        version: String,
        tag: ReleaseTag,
    } => Self::InvalidGithubReleasePin {
        path: PathBuf::from("carina-providers.lock"),
        source: "github.com/acme/widget".into(),
        version: "1.0.0".into(),
        tag: ReleaseTag::from_lock("v2.0.0".into()),
    },
    InvalidRegistryState {
        path: PathBuf,
        detail: String,
    } => Self::InvalidRegistryState {
        path: PathBuf::from("carina-providers.lock"),
        detail: "inconsistent migrated registry state".into(),
    },
    RegistryIdentityPinConflict {
        path: PathBuf,
        provider: String,
        source: Box<RegistryIdentityPinConflict>,
    } => Self::RegistryIdentityPinConflict {
        path: PathBuf::from("carina-providers.lock"),
        provider: "carina-rs/aws".into(),
        source: Box::new(RegistryIdentityPinConflict {
            left: Box::new(DiscardedSignerPins::Legacy(LegacySignerPin {
                certificate_san: "identity-a".into(),
                oidc_issuer: "issuer-a".into(),
            })),
            right: Box::new(DiscardedSignerPins::Legacy(LegacySignerPin {
                certificate_san: "identity-b".into(),
                oidc_issuer: "issuer-b".into(),
            })),
        }),
    },
}

impl fmt::Display for LockFileError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Read { path, source } => {
                write!(f, "Failed to read {}: {source}", path.display())
            }
            Self::MissingVersion { path } => write!(
                f,
                "Lock file {} has no format version and predates lock format versioning. It cannot be distinguished from a lock whose protection fields were stripped by an older Carina binary. Because automatic migration is unsafe, restore this file from version control or backup so its recorded protection state remains intact; if no trustworthy copy exists, preserve it for manual inspection and make any decision to move it aside explicitly.",
                path.display()
            ),
            Self::InvalidRegistryState { path, detail } => write!(
                f,
                "Failed to migrate registry security state from {}: {detail}",
                path.display()
            ),
            Self::LegacyEntryParse { path, source } => write!(
                f,
                "Failed to parse legacy provider entry in {}: {source}",
                path.display()
            ),
            Self::InvalidGithubReleasePin {
                path,
                source,
                version,
                tag,
            } => write!(
                f,
                "Malformed GitHub release entry for '{source}' in {}: version '{version}' does not match tag '{tag}'",
                path.display()
            ),
            Self::VersionTooNew { found, supported } => write!(
                f,
                "Lock file version {found} is newer than supported version {supported}. Please upgrade Carina."
            ),
            Self::InvalidVersion { found } => write!(
                f,
                "Lock file version {found} is not a valid lock format. Restore a valid lock from version control or backup, or preserve this file for manual recovery."
            ),
            Self::MissingRegistryHostRecord {
                project_dir,
                provider,
                hostname,
            } => {
                let path = provider_lock_path(project_dir);
                write!(
                    f,
                    "Lock file {} records registry provider {provider:?} as resolved through host {hostname:?}, but that host record is missing. The host record must be restored before a normal `{}` can re-resolve against that host and re-establish the discovery pin.",
                    path.display(),
                    ProjectCommand::new("init", project_dir)
                )
            }
            Self::RegistryHostKeyConflict { path, hostname } => write!(
                f,
                "Lock file {} contains multiple registry host records that canonicalize to {hostname:?}. Loading cannot choose between their security states; reconcile those host records in place without discarding protection state, or restore the file from version control or backup.",
                path.display()
            ),
            Self::Parse { path, source } => write!(
                f,
                "Failed to parse {}: {source}\nhint: correct the reported malformed record in place, preserving every other provider and registry protection record; otherwise restore the file from version control or backup.",
                path.display()
            ),
            Self::RegistryIdentityPinConflict {
                path,
                provider,
                source,
            } => write!(
                f,
                "Lock file {} contains {source} in records for registry provider {provider:?}; correct those provider records in place so their identity pins agree, preserving all other provider and registry protection records; otherwise restore the file from version control or backup.",
                path.display(),
            ),
        }
    }
}

impl std::error::Error for LockFileError {}

#[derive(Debug)]
pub enum LockConstraintError {
    LockFile(LockFileError),
    LegacyEntry(Box<LegacyLockEntryError>),
    ConstraintMismatch {
        provider: String,
        locked_version: String,
        constraint: String,
        project_dir: PathBuf,
    },
}

impl fmt::Display for LockConstraintError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LockFile(error) => error.fmt(f),
            Self::LegacyEntry(error) => error.fmt(f),
            Self::ConstraintMismatch {
                provider,
                locked_version,
                constraint,
                project_dir,
            } => write!(
                f,
                "Provider '{provider}' locked at version {locked_version}, but constraint '{constraint}' requires a different version.\nRun `{}` to resolve.",
                ProjectCommand::new("init --upgrade", project_dir)
            ),
        }
    }
}

impl std::error::Error for LockConstraintError {}

impl From<LockFileError> for LockConstraintError {
    fn from(error: LockFileError) -> Self {
        Self::LockFile(error)
    }
}

impl Default for LockFile {
    fn default() -> Self {
        Self {
            version: Self::CURRENT_VERSION,
            registry_host: BTreeMap::new(),
            provider: Vec::new(),
            egress: BTreeMap::new(),
            legacy: Vec::new(),
            unpinned_registry_ratchets: UnpinnedRegistryRatchets::default(),
        }
    }
}

impl<'a> PreparedRegistryIdentityRepin<'a> {
    /// Return the identity pin that committing this recovery will discard.
    pub fn identity_pin(&self) -> &DiscardedSignerPins {
        &self.target.state().pin
    }

    /// Consume this prepared recovery and clear its previewed identity pin.
    pub fn commit(self) -> Result<(), RegistryLockRecoveryError> {
        let Self {
            lock_file,
            source_key,
            target,
        } = self;
        lock_file.commit_prepared_registry_identity_repin(source_key, target)
    }
}

impl PreparedRegistryRebootstrap<'_> {
    /// Return the observation and anchor that committing this recovery will discard.
    pub fn freshness(&self) -> RegistryFreshness {
        RegistryFreshness {
            sequence: self.target.state().sequence.value(),
            sequence_anchor: self
                .target
                .sequence_anchor()
                .and_then(RegistrySequenceAnchor::value),
        }
    }

    /// Consume this prepared recovery and clear its previewed freshness pair.
    pub fn commit(self) -> Result<(), RegistryLockRecoveryError> {
        let Self {
            lock_file,
            source_key,
            target,
        } = self;
        lock_file.commit_prepared_registry_rebootstrap(source_key, target)
    }
}

impl fmt::Display for PreparedRegistryDiscoveryRepin<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(f, "Registry host: {}", self.hostname)?;
        match &self.discarded {
            PreparedRegistryDiscoveryRepinState::Pinned { discarded, .. } => {
                for (field, value) in discarded.values() {
                    writeln!(f, "Discarding pinned discovery value {field}: {value}")?;
                }
            }
            PreparedRegistryDiscoveryRepinState::MigrationPending(pins) => {
                for pin in pins.iter() {
                    writeln!(
                        f,
                        "Discarding migrated legacy discovery API base: {}",
                        pin.api_base_url
                    )?;
                    writeln!(
                        f,
                        "Discarding migrated legacy discovery document SHA-256: {}",
                        pin.discovery_sha256
                    )?;
                }
            }
        }
        write!(
            f,
            "All provider entries and provider security state will be retained."
        )
    }
}

struct PreparedRegistryDiscoveryRepinDisplay<'preview, 'lock> {
    prepared: &'preview PreparedRegistryDiscoveryRepin<'lock>,
    migration: Option<&'preview LockFileMigration>,
}

impl fmt::Display for PreparedRegistryDiscoveryRepinDisplay<'_, '_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let PreparedRegistryDiscoveryRepinState::MigrationPending(prepared_pins) =
            &self.prepared.discarded
            && let Some(migration) = self.migration
            && migration
                .discarded_discovery_pins
                .get(self.prepared.hostname.as_str())
                == Some(prepared_pins)
        {
            return migration.fmt_with_discovery_repin(f, Some(&self.prepared.hostname));
        }
        self.prepared.fmt(f)
    }
}

impl PreparedRegistryDiscoveryRepin<'_> {
    /// Render this recovery with an explicit load-time migration report.
    ///
    /// Callers that did not just load a migrated lock can use this type's
    /// ordinary [`fmt::Display`] implementation, which uses generic legacy
    /// wording without inventing stale version context.
    pub fn display_with_migration<'a>(
        &'a self,
        migration: Option<&'a LockFileMigration>,
    ) -> impl fmt::Display + 'a {
        PreparedRegistryDiscoveryRepinDisplay {
            prepared: self,
            migration,
        }
    }

    /// Clear the consumed values without touching provider-owned state or
    /// pinned discovery values this client does not consume.
    pub fn commit(self) {
        let Self {
            host, discarded, ..
        } = self;
        let retained = match discarded {
            PreparedRegistryDiscoveryRepinState::Pinned { retained, .. } => retained,
            PreparedRegistryDiscoveryRepinState::MigrationPending(_) => {
                UnconsumedDiscoveryValues::default()
            }
        };
        host.discovery = RegistryDiscoveryPinState::Unpinned(retained);
    }
}

pub(crate) fn resolve_parent(path: &Path) -> &Path {
    // Empty parents (bare relative filenames) and paths with no parent (such as
    // roots) both fall back to the current directory. For bare filenames, this
    // keeps the temporary file on the target's mount.
    path.parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or(Path::new("."))
}

// Linux allows at most 40 symlink traversals during pathname resolution. Use
// the same bound so dangling-chain fallback cannot loop forever on platforms
// where canonicalize does not diagnose a cycle first.
const MAX_LOCK_FILE_SYMLINK_HOPS: usize = 40;

#[cfg(unix)]
fn filesystem_loop_error() -> io::Error {
    // ErrorKind::FilesystemLoop is not yet directly constructible on stable
    // Rust, but std maps the platform's ELOOP code to that kind.
    io::Error::from_raw_os_error(libc::ELOOP)
}

#[cfg(windows)]
fn filesystem_loop_error() -> io::Error {
    // WinError.h's ERROR_CANT_RESOLVE_FILENAME maps to FilesystemLoop in std.
    const ERROR_CANT_RESOLVE_FILENAME: i32 = 1921;
    io::Error::from_raw_os_error(ERROR_CANT_RESOLVE_FILENAME)
}

pub(crate) fn resolve_lock_file_save_path(path: &Path) -> io::Result<PathBuf> {
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return Ok(path.to_path_buf());
        }
        Err(error) => return Err(error),
    };
    if !metadata.file_type().is_symlink() {
        return Ok(path.to_path_buf());
    }

    match fs::canonicalize(path) {
        Ok(target) => Ok(target),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            let mut link_path = path.to_path_buf();
            for _ in 0..MAX_LOCK_FILE_SYMLINK_HOPS {
                let target = fs::read_link(&link_path)?;
                let target = if target.is_absolute() {
                    target
                } else {
                    resolve_parent(&link_path).join(target)
                };

                match fs::symlink_metadata(&target) {
                    Ok(metadata) if metadata.file_type().is_symlink() => {
                        link_path = target;
                    }
                    Ok(_) => return Ok(target),
                    Err(error) if error.kind() == io::ErrorKind::NotFound => {
                        return Ok(target);
                    }
                    Err(error) => return Err(error),
                }
            }
            Err(filesystem_loop_error())
        }
        Err(error) => Err(error),
    }
}

#[cfg(test)]
type LockFileRenameHook = Box<dyn FnOnce(&Path, &Path) -> io::Result<()>>;

#[cfg(test)]
std::thread_local! {
    static LOCK_FILE_RENAME_HOOK: std::cell::RefCell<Option<LockFileRenameHook>> =
        const { std::cell::RefCell::new(None) };
}

#[cfg(test)]
pub(crate) fn rename_lock_file_for_test(from: &Path, to: &Path) -> io::Result<()> {
    if let Some(rename) = LOCK_FILE_RENAME_HOOK.with(|hook| hook.borrow_mut().take()) {
        return rename(from, to);
    }
    fs::rename(from, to)
}

impl LockFile {
    /// v5 adds an explicit reset-pending sequence-anchor state to pinned
    /// registry records. v4 locks migrate with an unestablished or established
    /// anchor exactly as encoded; pre-pin observations carry no anchor state.
    ///
    /// v4 stores signer source and per-channel workflow pins extracted from
    /// verified certificates. v3 full-SAN pins migrate losslessly into the
    /// explicit legacy state and are converted only by a matching signature.
    ///
    /// v3: Registry discovery pins contain the resolved values the client
    /// consumes, keyed by discovery field. The open map preserves values an
    /// older client does not consume.
    ///
    /// v1 and v2 pinned both the resolved API base and a hash of the discovery
    /// document bytes. Loading either format preserves every provider-owned
    /// record and retains each legacy host pin in a resolution-blocking state
    /// because neither value can truthfully be reinterpreted as a v3 pin. Only
    /// an operator-authorized discovery re-pin can leave that state.
    pub const CURRENT_VERSION: u32 = 5;

    fn registry_host_lock(&self, hostname: &str) -> Option<&RegistryHostLock> {
        self.registry_host.get(hostname)
    }

    fn legacy_github_version_pin(&self, source: &RemoteSourceKey) -> Option<(String, String)> {
        self.legacy.iter().find_map(|entry| match &entry.reason {
            _ if !Self::sources_match(&entry.source, source.as_str()) => None,
            LegacyReason::GithubDirectVersionWithoutTag { version, sha256 } => {
                Some((version.clone(), sha256.clone()))
            }
            LegacyReason::RevisionWithoutArtifactId { .. } => None,
        })
    }

    pub(crate) fn legacy_revision_pin(
        &self,
        source: &RemoteSourceKey,
        revision: &str,
    ) -> Option<(CommitSha, String)> {
        self.legacy.iter().find_map(|entry| match &entry.reason {
            _ if !Self::sources_match(&entry.source, source.as_str()) => None,
            LegacyReason::RevisionWithoutArtifactId {
                revision: locked_revision,
                resolved_sha,
                sha256,
            } if locked_revision == revision => Some((resolved_sha.clone(), sha256.clone())),
            LegacyReason::GithubDirectVersionWithoutTag { .. }
            | LegacyReason::RevisionWithoutArtifactId { .. } => None,
        })
    }

    fn sources_match(existing: &str, requested: &str) -> bool {
        existing == requested || canonical_lock_source(existing) == canonical_lock_source(requested)
    }

    /// Load `carina-providers.lock`.
    ///
    /// Returns `Ok(None)` when the file is absent (normal first-run case).
    /// A present file is tagged as pristine or migrated so callers can surface
    /// retained legacy security state and any discovery material awaiting
    /// operator authorization.
    /// Parse errors — including an entry that can't be discriminated into a
    /// [`LockEntryKind`] variant — surface as `Err` rather than being silently
    /// collapsed into a default-empty lock.
    ///
    /// `project_dir` is also the user-facing project argument used in
    /// remediation commands; callers must not derive it from a canonicalized
    /// lock path.
    pub fn load(project_dir: &Path) -> Result<Option<LoadedLockFile>, LockFileError> {
        let path = provider_lock_path(project_dir);
        let Some(content) = Self::read_from_path(&path)? else {
            return Ok(None);
        };
        Self::parse_toml_str(&content, &path, project_dir).map(Some)
    }

    fn read_from_path(path: &Path) -> Result<Option<String>, LockFileError> {
        let content = match fs::read_to_string(path) {
            Ok(s) => s,
            Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(None),
            Err(source) => {
                return Err(LockFileError::Read {
                    path: path.to_path_buf(),
                    source,
                });
            }
        };
        Ok(Some(content))
    }

    #[cfg(test)]
    fn load_from_path(path: &Path) -> Result<Option<LoadedLockFile>, LockFileError> {
        let Some(content) = Self::read_from_path(path)? else {
            return Ok(None);
        };
        Self::parse_toml_str(&content, path, resolve_parent(path)).map(Some)
    }

    /// Validated parse seam. It is private so callers cannot deserialize a
    /// `LockFile` around the version gate or lose the typed migration event.
    fn parse_toml_str(
        content: &str,
        path: &Path,
        project_dir: &Path,
    ) -> Result<LoadedLockFile, LockFileError> {
        let version: LockFileVersion = parse_lock_toml(content, path)?;
        let version = version
            .version
            .ok_or_else(|| LockFileError::MissingVersion {
                path: path.to_path_buf(),
            })?;
        if version > Self::CURRENT_VERSION {
            return Err(LockFileError::VersionTooNew {
                found: version,
                supported: Self::CURRENT_VERSION,
            });
        }
        let (table, legacy_entries) = split_lock_table_legacy_entries(content, path)?;

        match version {
            Self::CURRENT_VERSION => {
                let unchecked: UncheckedLockFile = parse_lock_table(&table, path)?;
                let legacy_sources = legacy_entries
                    .iter()
                    .map(|entry| entry.source.clone())
                    .collect::<Vec<_>>();
                let lock_file = Self::from_unchecked(unchecked, legacy_entries, path, project_dir)?;
                if legacy_sources.is_empty() {
                    Ok(LoadedLockFile::Pristine(lock_file))
                } else {
                    Ok(LoadedLockFile::Migrated {
                        lock_file,
                        migration: LockFileMigration {
                            project_dir: project_dir.to_path_buf(),
                            from: version,
                            to: Self::CURRENT_VERSION,
                            discarded_discovery_pins: BTreeMap::new(),
                            legacy_sources,
                        },
                    })
                }
            }
            4 => {
                let unchecked: UncheckedLockFileV4 = parse_lock_table(&table, path)?;
                if let Some(entry) = unchecked.provider.iter().find(|entry| {
                    entry.registry.as_ref().is_some_and(|registry| {
                        registry.sequence_anchor == RegistrySequenceAnchor::ResetPending
                    })
                }) {
                    return Err(LockFileError::InvalidRegistryState {
                        path: path.to_path_buf(),
                        detail: format!(
                            "lock format v4 cannot contain a reset-pending sequence anchor for provider {:?}",
                            entry.source
                        ),
                    });
                }
                let legacy_sources = legacy_entries
                    .iter()
                    .map(|entry| entry.source.clone())
                    .collect();
                let registry_host = canonicalize_registry_host_keys(unchecked.registry_host, path)?;
                let lock_file = Self::from_parts(
                    registry_host,
                    unchecked.provider,
                    BTreeMap::new(),
                    unchecked.unpinned_registry_ratchets,
                    legacy_entries,
                    path,
                    project_dir,
                )?;
                Ok(LoadedLockFile::Migrated {
                    lock_file,
                    migration: LockFileMigration {
                        project_dir: project_dir.to_path_buf(),
                        from: version,
                        to: Self::CURRENT_VERSION,
                        discarded_discovery_pins: BTreeMap::new(),
                        legacy_sources,
                    },
                })
            }
            3 => {
                let legacy: UncheckedLockFileV3 = parse_lock_table(&table, path)?;
                let registry_host = canonicalize_registry_host_keys(legacy.registry_host, path)?;
                finish_legacy_lock_migration(
                    version,
                    ParsedLegacyLockBody {
                        registry_host,
                        provider: legacy.provider,
                        unpinned_registry_ratchets: legacy.unpinned_registry_ratchets,
                        discarded_discovery_pins: BTreeMap::new(),
                    },
                    legacy_entries,
                    path,
                    project_dir,
                )
            }
            2 => {
                let legacy: UncheckedLockFileV2 = parse_lock_table(&table, path)?;

                let legacy_hosts = canonicalize_registry_host_keys(legacy.registry_host, path)?;
                let (registry_host, discarded_discovery_pins) =
                    migrate_legacy_registry_hosts(legacy_hosts);
                finish_legacy_lock_migration(
                    version,
                    ParsedLegacyLockBody {
                        registry_host,
                        provider: legacy.provider,
                        unpinned_registry_ratchets: legacy.unpinned_registry_ratchets,
                        discarded_discovery_pins,
                    },
                    legacy_entries,
                    path,
                    project_dir,
                )
            }
            1 => {
                let legacy: UncheckedLockFileV1 = parse_lock_table(&table, path)?;
                let migrated = migrate_v1_provider_entries(legacy.provider);
                let unpinned_registry_ratchets = merge_v1_unpinned_registry_yanks(
                    legacy.unpinned_registry_yanks,
                    legacy.unpinned_registry_ratchets,
                );
                finish_legacy_lock_migration(
                    version,
                    ParsedLegacyLockBody {
                        registry_host: migrated.registry_host,
                        provider: migrated.provider,
                        unpinned_registry_ratchets,
                        discarded_discovery_pins: migrated.discarded_discovery_pins,
                    },
                    legacy_entries,
                    path,
                    project_dir,
                )
            }
            _ => Err(LockFileError::InvalidVersion { found: version }),
        }
    }

    #[cfg(test)]
    fn from_toml_str(content: &str, path: &Path) -> Result<Self, LockFileError> {
        Self::parse_toml_str(content, path, resolve_parent(path))
            .map(LoadedLockFile::into_lock_file)
    }

    fn from_unchecked(
        unchecked: UncheckedLockFile,
        legacy: Vec<LegacyLockEntry>,
        path: &Path,
        project_dir: &Path,
    ) -> Result<Self, LockFileError> {
        let UncheckedLockFile {
            _version: _,
            registry_host,
            provider,
            unpinned_registry_ratchets,
        } = unchecked;
        let registry_host = canonicalize_registry_host_keys(registry_host, path)?;
        let mut egress = BTreeMap::new();
        let provider = provider
            .into_iter()
            .map(|current| {
                if let Some(record) = current.egress {
                    egress.insert(EgressArtifactKey::from_entry(&current.entry), record);
                }
                current.entry
            })
            .collect();
        Self::from_parts(
            registry_host,
            provider,
            egress,
            unpinned_registry_ratchets,
            legacy,
            path,
            project_dir,
        )
    }

    fn from_parts(
        registry_host: BTreeMap<CanonicalRegistryHostname, RegistryHostLock>,
        provider: Vec<LockEntry<RegistryLock>>,
        egress: BTreeMap<EgressArtifactKey, crate::EgressLockRecord>,
        unpinned_registry_ratchets: UnpinnedRegistryRatchets,
        legacy: Vec<LegacyLockEntry>,
        path: &Path,
        project_dir: &Path,
    ) -> Result<Self, LockFileError> {
        let unpinned_registry_ratchets =
            unpinned_registry_ratchets
                .into_canonical()
                .map_err(|conflict| LockFileError::RegistryIdentityPinConflict {
                    path: path.to_path_buf(),
                    provider: conflict.provider,
                    source: Box::new(conflict.source),
                })?;
        for entry in &provider {
            match &entry.kind {
                LockEntryKind::GithubRelease {
                    version,
                    tag,
                    asset_id: _,
                    constraint: _,
                } => {
                    let version_matches_tag = tag
                        .semver()
                        .is_some_and(|tag_version| version == &tag_version);
                    if !version_matches_tag {
                        return Err(LockFileError::InvalidGithubReleasePin {
                            path: path.to_path_buf(),
                            source: entry.source.clone(),
                            version: version.to_string(),
                            tag: tag.clone(),
                        });
                    }
                }
                LockEntryKind::Version {
                    version: _,
                    constraint: _,
                }
                | LockEntryKind::Revision {
                    revision: _,
                    resolved_sha: _,
                    artifact_id: _,
                }
                | LockEntryKind::RegistryRevision {
                    revision: _,
                    version: _,
                }
                | LockEntryKind::File => {}
            }
        }
        for entry in &provider {
            let Some(registry) = &entry.registry else {
                continue;
            };
            if !registry_host.contains_key(registry.resolved_hostname()) {
                return Err(LockFileError::MissingRegistryHostRecord {
                    project_dir: project_dir.to_path_buf(),
                    provider: canonical_lock_source(&entry.source),
                    hostname: registry.resolved_hostname().to_owned(),
                });
            }
        }
        let mut lock = Self {
            version: Self::CURRENT_VERSION,
            registry_host,
            provider,
            egress,
            legacy,
            unpinned_registry_ratchets,
        };
        lock.attach_unpinned_registry_ratchets()
            .map_err(|conflict| LockFileError::RegistryIdentityPinConflict {
                path: path.to_path_buf(),
                provider: conflict.provider,
                source: Box::new(conflict.source),
            })?;
        Ok(lock)
    }

    pub(crate) fn to_toml_string(&self) -> Result<String, toml::ser::Error> {
        let provider = self
            .provider
            .iter()
            .map(|entry| {
                SerializableProviderEntry::Current(SerializableCurrentProviderEntry {
                    entry,
                    egress: self.egress.get(&EgressArtifactKey::from_entry(entry)),
                })
            })
            .chain(
                self.legacy
                    .iter()
                    .map(|entry| SerializableProviderEntry::Legacy(&entry.raw)),
            )
            .collect();
        toml::to_string_pretty(&SerializableLockFile {
            version: &self.version,
            registry_host: &self.registry_host,
            provider,
            unpinned_registry_ratchets: &self.unpinned_registry_ratchets,
        })
    }

    #[cfg(any(test, feature = "test-utils"))]
    pub fn save(&self, path: &Path) -> io::Result<()> {
        crate::install_lock::save_lock_file_fixture(self, path)
    }

    /// Find an entry matching `(source, version)` for modes with a published
    /// version pin. Git revision and file entries never match.
    fn find(&self, source: &str, version: &str) -> Option<&LockEntry<RegistryLock>> {
        self.provider.iter().find(|e| {
            Self::sources_match(&e.source, source)
                && e.kind.resolved_version().as_deref() == Some(version)
        })
    }

    /// Find a version pin selected by a validated remote provider source.
    pub fn find_by_source_key_and_version(
        &self,
        source: &RemoteSourceKey,
        version: &str,
    ) -> Option<&LockEntry<RegistryLock>> {
        self.find(source.as_str(), version)
    }

    fn find_by_source(&self, source: &str) -> Option<&LockEntry<RegistryLock>> {
        self.provider
            .iter()
            .find(|e| Self::sources_match(&e.source, source))
    }

    fn find_by_remote_config<P: PlaceholderKind, B: BindingAddress>(
        &self,
        config: &ProviderConfig<P, B>,
        source: &RemoteSource,
    ) -> Option<&LockEntry<RegistryLock>> {
        let source_key = source.source_key();
        self.provider.iter().find(|entry| {
            Self::sources_match(&entry.source, source_key.as_str())
                && lock_entry_matches_remote_config(entry, config, source)
        })
    }

    /// Return the egress record owned by the lock entry for this exact
    /// verified declaration's canonical source.
    pub fn locked_egress(
        &self,
        declaration: &crate::VerifiedEgressDeclaration,
        project_dir: &Path,
    ) -> Option<crate::LockedEgress> {
        self.locked_egress_for_artifact(
            declaration.source(),
            declaration.sha256().as_str(),
            project_dir,
        )
    }

    fn locked_egress_for_artifact(
        &self,
        source: &crate::CanonicalSource,
        sha256: &str,
        project_dir: &Path,
    ) -> Option<crate::LockedEgress> {
        let entry = self.find_by_verified_artifact(source, sha256, project_dir)?;
        let locked_source = crate::CanonicalSource::from_lock_source(&entry.source, project_dir)?;
        let record = self
            .egress
            .get(&EgressArtifactKey::from_entry(entry))?
            .clone();
        Some(crate::LockedEgress::new(
            locked_source,
            crate::Sha256::from_lock(entry.sha256.clone()),
            record,
            project_dir,
        ))
    }

    fn find_by_verified_artifact(
        &self,
        source: &crate::CanonicalSource,
        sha256: &str,
        project_dir: &Path,
    ) -> Option<&LockEntry<RegistryLock>> {
        self.provider.iter().find(|entry| {
            let source_matches = if source.is_file() {
                crate::CanonicalSource::from_lock_source(&entry.source, project_dir).as_ref()
                    == Some(source)
            } else {
                Self::sources_match(&entry.source, &source.to_string())
            };
            source_matches && (source.is_file() || entry.sha256 == sha256)
        })
    }

    fn egress_record_for_display(
        &self,
        source: &crate::CanonicalSource,
        project_dir: &Path,
    ) -> Option<&crate::EgressLockRecord> {
        self.provider.iter().find_map(|entry| {
            let locked_source =
                crate::CanonicalSource::from_lock_source(&entry.source, project_dir)?;
            if &locked_source != source {
                return None;
            }
            self.egress.get(&EgressArtifactKey::from_entry(entry))
        })
    }

    fn explicit_egress_for_carry_over(
        &self,
        declaration: &crate::VerifiedEgressDeclaration,
        project_dir: &Path,
    ) -> Option<crate::LockedEgress> {
        self.provider.iter().find_map(|entry| {
            let locked_source =
                crate::CanonicalSource::from_lock_source(&entry.source, project_dir)?;
            if &locked_source != declaration.source() {
                return None;
            }
            let record = self.egress.get(&EgressArtifactKey::from_entry(entry))?;
            if record.hosts()? != declaration.patterns() {
                return None;
            }
            let locked = crate::LockedEgress::new(
                locked_source,
                crate::Sha256::from_lock(entry.sha256.clone()),
                record.clone(),
                project_dir,
            );
            locked.explicit_consent().is_some().then_some(locked)
        })
    }

    fn record_egress_consent(
        &mut self,
        declaration: &crate::VerifiedEgressDeclaration,
        consent: crate::EgressConsent,
        project_dir: &Path,
    ) -> Result<(), crate::EgressConsentError> {
        crate::ConsentedEgress::from_consent(declaration.clone(), consent.clone())?;
        let record = match consent {
            crate::EgressConsent::CarinaRsSigned(_) => {
                crate::EgressLockRecord::carina_rs_signed(declaration.patterns().clone())
            }
            crate::EgressConsent::Explicit(_) => {
                crate::EgressLockRecord::explicit(declaration.patterns().clone())
            }
        };
        let entry = self
            .find_by_verified_artifact(
                declaration.source(),
                declaration.sha256().as_str(),
                project_dir,
            )
            .ok_or(crate::EgressConsentError::MissingLockEntry)?;
        let artifact_key = EgressArtifactKey::from_entry(entry);
        self.egress.insert(artifact_key, record);
        Ok(())
    }

    fn clear_empty_egress_declaration(
        &mut self,
        declaration: crate::VerifiedEgressDeclaration,
        project_dir: &Path,
    ) -> Result<(), crate::EgressConsentError> {
        crate::ConsentedEgress::nothing_declared(declaration.clone())?;
        let entry = self
            .find_by_verified_artifact(
                declaration.source(),
                declaration.sha256().as_str(),
                project_dir,
            )
            .ok_or(crate::EgressConsentError::MissingLockEntry)?;
        let artifact_key = EgressArtifactKey::from_entry(entry);
        self.egress.remove(&artifact_key);
        Ok(())
    }

    fn find_registry_by_source_with_index(&self, source: &str) -> Option<(usize, &RegistryLock)> {
        self.provider.iter().enumerate().find_map(|(index, entry)| {
            Self::sources_match(&entry.source, source)
                .then_some(entry.registry.as_ref())
                .flatten()
                .map(|registry| (index, registry))
        })
    }

    fn find_registry_by_source(&self, source: &str) -> Option<&RegistryLock> {
        self.find_registry_by_source_with_index(source)
            .map(|(_, registry)| registry)
    }

    /// Find a lock entry selected by a validated remote provider source.
    pub fn find_by_source_key(&self, source: &RemoteSourceKey) -> Option<&LockEntry<RegistryLock>> {
        self.find_by_source(source.as_str())
    }

    fn find_source_entry(&self, source: &RemoteSourceKey) -> Option<SourceLockEntry<'_>> {
        self.legacy
            .iter()
            .find(|entry| Self::sources_match(&entry.source, source.as_str()))
            .map(SourceLockEntry::Legacy)
            .or_else(|| self.find_by_source_key(source).map(SourceLockEntry::Typed))
    }

    fn resolve_registry_recovery(
        &self,
        provider: &str,
    ) -> Result<ResolvedRegistryRecovery, RegistryLockRecoveryError> {
        let source = provider.parse::<ProviderSource>().map_err(|reason| {
            RegistryLockRecoveryError::InvalidProvider {
                provider: provider.to_string(),
                reason: reason.to_string(),
            }
        })?;
        let source_key = match source {
            ProviderSource::Remote(RemoteSource::Registry(source)) => {
                source.source_key().to_string()
            }
            ProviderSource::File(_) | ProviderSource::Remote(RemoteSource::GithubDirect(_)) => {
                return Err(RegistryLockRecoveryError::NotRegistryProvider {
                    provider: provider.to_string(),
                });
            }
        };
        if let Some((index, registry)) = self.find_registry_by_source_with_index(&source_key) {
            let recorded = RegistryRatchets::from(registry);
            let state = match self.unpinned_registry_ratchets.get(&source_key) {
                Some(unpinned) => recorded
                    .merge(unpinned)
                    .map_err(RegistryLockRecoveryError::IdentityPinConflict)?,
                None => recorded,
            };
            return Ok(ResolvedRegistryRecovery {
                source_key,
                target: RegistryRecoveryTarget::Pinned {
                    index,
                    sequence_anchor: registry.sequence_anchor,
                    state,
                },
            });
        }
        let state = self
            .unpinned_registry_ratchets
            .get(&source_key)
            .cloned()
            .ok_or_else(|| RegistryLockRecoveryError::ProviderStateNotFound {
                provider: source_key.clone(),
            })?;
        Ok(ResolvedRegistryRecovery {
            source_key,
            target: RegistryRecoveryTarget::Unpinned { state },
        })
    }

    fn commit_prepared_registry_identity_repin(
        &mut self,
        source_key: String,
        target: RegistryRecoveryTarget<RegistryIdentityRepinState>,
    ) -> Result<(), RegistryLockRecoveryError> {
        match target {
            RegistryRecoveryTarget::Pinned { index, state, .. } => {
                let registry = self
                    .provider
                    .get_mut(index)
                    .and_then(|entry| entry.registry.as_mut())
                    .ok_or_else(|| RegistryLockRecoveryError::ProviderStateNotFound {
                        provider: source_key.clone(),
                    })?;
                state.residual.apply_to_registry(registry);
                self.unpinned_registry_ratchets.remove(&source_key);
            }
            RegistryRecoveryTarget::Unpinned { state } => {
                if !self
                    .unpinned_registry_ratchets
                    .commit_identity_repin(&source_key, state.residual)
                {
                    return Err(RegistryLockRecoveryError::ProviderStateNotFound {
                        provider: source_key,
                    });
                }
            }
        }
        Ok(())
    }

    fn commit_prepared_registry_rebootstrap(
        &mut self,
        source_key: String,
        target: RegistryRecoveryTarget<RegistryRebootstrapState>,
    ) -> Result<(), RegistryLockRecoveryError> {
        match target {
            RegistryRecoveryTarget::Pinned { index, state, .. } => {
                let registry = self
                    .provider
                    .get_mut(index)
                    .and_then(|entry| entry.registry.as_mut())
                    .ok_or_else(|| RegistryLockRecoveryError::ProviderStateNotFound {
                        provider: source_key.clone(),
                    })?;
                state.residual.apply_to_registry(registry);
                registry.sequence_anchor = RegistrySequenceAnchor::ResetPending;
                self.unpinned_registry_ratchets.remove(&source_key);
            }
            RegistryRecoveryTarget::Unpinned { state } => {
                if !self
                    .unpinned_registry_ratchets
                    .commit_rebootstrap(&source_key, state.residual)
                {
                    return Err(RegistryLockRecoveryError::ProviderStateNotFound {
                        provider: source_key,
                    });
                }
            }
        }
        Ok(())
    }

    /// Prepare an explicit identity re-pin without mutating the lock file.
    pub fn prepare_registry_identity_repin(
        &mut self,
        provider: &str,
    ) -> Result<PreparedRegistryIdentityRepin<'_>, RegistryLockRecoveryError> {
        let ResolvedRegistryRecovery { source_key, target } =
            self.resolve_registry_recovery(provider)?;
        let error_provider = source_key.clone();
        let target =
            target.try_map_state(|ratchets| ratchets.into_identity_repin_state(error_provider))?;
        Ok(PreparedRegistryIdentityRepin {
            lock_file: self,
            source_key,
            target,
        })
    }

    /// Prepare an explicit registry re-bootstrap without mutating the lock file.
    /// For a pinned provider, committing installs a persisted reset-pending
    /// anchor state that only a subsequent successful resolution consumes.
    /// Pre-pin observations have no anchor and remain first contact after their
    /// freshness observation is discarded.
    pub fn prepare_registry_rebootstrap(
        &mut self,
        provider: &str,
    ) -> Result<PreparedRegistryRebootstrap<'_>, RegistryLockRecoveryError> {
        let ResolvedRegistryRecovery { source_key, target } =
            self.resolve_registry_recovery(provider)?;
        let target = target.map_state(RegistryRatchets::into_rebootstrap_state);
        Ok(PreparedRegistryRebootstrap {
            lock_file: self,
            source_key,
            target,
        })
    }

    /// Prepare an explicit host discovery re-pin without mutating the lock.
    /// The returned exclusive borrow is the single lookup used for preview and
    /// commit, so the displayed host state cannot diverge from the write.
    pub fn prepare_registry_discovery_repin(
        &mut self,
        host: &str,
    ) -> Result<PreparedRegistryDiscoveryRepin<'_>, RegistryLockRecoveryError> {
        let hostname = CanonicalRegistryHostname::from(host);
        let host = hostname.as_str().to_owned();
        let Self { registry_host, .. } = self;
        let host_lock = registry_host.get_mut(hostname.as_str()).ok_or_else(|| {
            RegistryLockRecoveryError::RegistryHostStateNotFound { host: host.clone() }
        })?;
        let discarded = match &host_lock.discovery {
            RegistryDiscoveryPinState::Pinned(pin) => PreparedRegistryDiscoveryRepinState::Pinned {
                discarded: pin.consumed_values(),
                retained: pin.additional.clone(),
            },
            RegistryDiscoveryPinState::MigrationPendingAuthorization(pin) => {
                PreparedRegistryDiscoveryRepinState::MigrationPending(pin.clone())
            }
            RegistryDiscoveryPinState::Unpinned(_) => {
                return Err(RegistryLockRecoveryError::DiscoveryAlreadyUnpinned { host });
            }
        };
        Ok(PreparedRegistryDiscoveryRepin {
            host: host_lock,
            hostname: host,
            discarded,
        })
    }

    /// Find a revision-mode entry whose `resolved_sha` matches. Version and
    /// file entries can't have a resolved SHA, so they never match.
    fn find_by_source_and_sha(
        &self,
        source: &str,
        sha: &CommitSha,
    ) -> Option<&LockEntry<RegistryLock>> {
        self.provider.iter().find(|e| {
            Self::sources_match(&e.source, source)
                && matches!(
                    &e.kind,
                    LockEntryKind::Revision { resolved_sha, .. } if resolved_sha == sha
                )
        })
    }

    /// Find a revision pin selected by a validated remote provider source.
    pub fn find_by_source_key_and_sha(
        &self,
        source: &RemoteSourceKey,
        sha: &CommitSha,
    ) -> Option<&LockEntry<RegistryLock>> {
        self.find_by_source_and_sha(source.as_str(), sha)
    }

    fn known_registry_ratchets(
        &self,
        source: &str,
    ) -> Result<RegistryRatchets, RegistryIdentityPinConflict> {
        let recorded = self
            .find_registry_by_source(source)
            .map(RegistryRatchets::from)
            .unwrap_or_default();
        let source_key = canonical_lock_source(source);
        match self.unpinned_registry_ratchets.get(&source_key) {
            Some(unpinned) => recorded.merge(unpinned),
            None => Ok(recorded),
        }
    }

    fn known_registry_ratchets_by_source_key(
        &self,
        source: &RemoteSourceKey,
    ) -> Result<RegistryRatchets, RegistryIdentityPinConflict> {
        self.known_registry_ratchets(source.as_str())
    }

    fn registry_sequence_previous_state(&self, source: &str) -> RegistrySequencePreviousState {
        self.find_registry_by_source(source)
            .map(|registry| registry.sequence_anchor)
            .map(RegistrySequenceAnchor::into_previous_state)
            .unwrap_or(RegistrySequencePreviousState::FirstContact)
    }

    fn registry_sequence_previous_state_by_source_key(
        &self,
        source: &RemoteSourceKey,
    ) -> RegistrySequencePreviousState {
        self.registry_sequence_previous_state(source.as_str())
    }

    #[cfg(test)]
    fn registry_sequence_anchor(&self, source: &str) -> Option<RegistrySequenceAnchor> {
        self.find_registry_by_source(source)
            .map(|registry| registry.sequence_anchor)
    }

    fn attach_unpinned_registry_ratchets(
        &mut self,
    ) -> Result<(), RegistryIdentityPinConflictRecord> {
        for entry in &mut self.provider {
            let Some(registry) = entry.registry.as_mut() else {
                continue;
            };
            let source_key = canonical_lock_source(&entry.source);
            if let Some(unpinned) = self.unpinned_registry_ratchets.remove(&source_key) {
                unpinned.merge_into_registry(registry).map_err(|source| {
                    RegistryIdentityPinConflictRecord {
                        provider: source_key,
                        source,
                    }
                })?;
            }
        }
        Ok(())
    }

    fn store_registry_ratchets(
        &mut self,
        source: &str,
        ratchets: RegistryRatchets,
    ) -> Result<(), RegistryIdentityPinConflict> {
        let source_key = canonical_lock_source(source);
        if let Some(registry) = self
            .provider
            .iter_mut()
            .find(|entry| Self::sources_match(&entry.source, &source_key))
            .and_then(|entry| entry.registry.as_mut())
        {
            ratchets.merge_into_registry(registry)?;
            self.unpinned_registry_ratchets.remove(&source_key);
        } else {
            self.unpinned_registry_ratchets
                .merge(source_key, ratchets)?;
        }
        Ok(())
    }

    fn replace_legacy_signer_pin(
        &mut self,
        source: &str,
        next: SignerPinState,
    ) -> Result<(), String> {
        let SignerPinState::Current(_) = next else {
            return Err("legacy signer conversion did not produce current signer pins".into());
        };
        let source_key = canonical_lock_source(source);
        let signature = self
            .provider
            .iter_mut()
            .find(|entry| Self::sources_match(&entry.source, &source_key))
            .and_then(|entry| entry.registry.as_mut())
            .map(|registry| &mut registry.signature)
            .or_else(|| {
                self.unpinned_registry_ratchets
                    .0
                    .get_mut(&source_key)
                    .map(|ratchets| &mut ratchets.signature)
            })
            .ok_or_else(|| "legacy signer conversion lost its persisted pin state".to_string())?;
        if !matches!(
            signature,
            RegistrySignatureProtection::Required(SignerPinState::Legacy(_))
        ) {
            return Err("legacy signer conversion lost its legacy pin before commit".into());
        }
        *signature = RegistrySignatureProtection::Required(next);
        Ok(())
    }

    pub fn upsert(&mut self, entry: LockEntry<NoRegistryLock>) {
        self.upsert_entry(entry.into_stored());
    }

    #[cfg(test)]
    fn upsert_registry(
        &mut self,
        mut entry: LockEntry<RegistryLock>,
        host: RegistryHostLock,
    ) -> Result<(), RegistryIdentityPinConflict> {
        if let Some(registry) = entry.registry.as_mut() {
            let observed = self.known_registry_ratchets(&entry.source)?;
            observed.merge_into_registry(registry)?;
            self.registry_host
                .insert(registry.resolved_hostname.clone(), host);
        }
        self.upsert_entry(entry);
        Ok(())
    }

    fn upsert_entry(&mut self, entry: LockEntry<RegistryLock>) {
        self.legacy
            .retain(|legacy| !Self::sources_match(&legacy.source, &entry.source));
        if entry.registry.is_some() {
            self.unpinned_registry_ratchets
                .remove(&canonical_lock_source(&entry.source));
        }
        let matching_source_count = self
            .provider
            .iter()
            .filter(|existing| Self::sources_match(&existing.source, &entry.source))
            .count();
        let matching_slot = self.provider.iter().position(|existing| {
            Self::sources_match(&existing.source, &entry.source)
                && existing.kind.resolution_slot() == entry.kind.resolution_slot()
        });
        let replacement = matching_slot.or_else(|| {
            (matching_source_count == 1).then(|| {
                self.provider
                    .iter()
                    .position(|existing| Self::sources_match(&existing.source, &entry.source))
                    .expect("the source count proves a matching entry exists")
            })
        });
        if let Some(index) = replacement {
            let existing = &mut self.provider[index];
            let old_key = EgressArtifactKey::from_entry(existing);
            let egress = self.egress.remove(&old_key);
            *existing = entry;
            if let Some(egress) = egress {
                self.egress
                    .entry(EgressArtifactKey::from_entry(existing))
                    .or_insert(egress);
            }
        } else {
            self.provider.push(entry);
        }
    }
}

/// Failure to derive the only hostname permission accepted by a runtime
/// provider instance from the installed bytes and the project lock.
#[derive(Debug)]
pub enum LockedEgressLoadError {
    LockFile(LockFileError),
}

impl fmt::Display for LockedEgressLoadError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LockFile(source) => source.fmt(formatter),
        }
    }
}

impl std::error::Error for LockedEgressLoadError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::LockFile(source) => source.source(),
        }
    }
}

/// Load the optional egress record for the canonical source of these exact
/// verified bytes. The host binds it to the declaration from the same load.
pub fn load_locked_egress(
    project_dir: &Path,
    load: &VerifiedLoad,
) -> Result<Option<crate::LockedEgress>, LockedEgressLoadError> {
    let Some(loaded) = LockFile::load(project_dir).map_err(LockedEgressLoadError::LockFile)? else {
        return Ok(None);
    };
    let (lock_file, _migration) = loaded.into_parts();
    let source = crate::CanonicalSource::from_load(load);
    Ok(lock_file.locked_egress_for_artifact(&source, load.artifact().sha256(), project_dir))
}

fn load_lock_file(project_dir: &Path) -> Result<Option<LockFile>, LockFileError> {
    let loaded = LockFile::load(project_dir)?;
    Ok(loaded.map(LoadedLockFile::into_resolution_lock_file))
}

#[cfg(test)]
fn load_lock_file_for_test(path: &Path) -> Result<Option<LockFile>, LockFileError> {
    LockFile::load_from_path(path).map(|loaded| loaded.map(LoadedLockFile::into_lock_file))
}

/// The non-ratchet fields and validated sequence proof needed for a final
/// registry provider entry. Persisted ratchets remain absent: the upsert can
/// obtain them only from [`PersistentLockFile`].
struct RegistryProviderLockEntry {
    name: String,
    source: RemoteSourceKey,
    kind: LockEntryKind,
    sha256: String,
    registry: ResolvedRegistry,
    validated_sequence: ValidatedRegistrySequence,
}

/// A lock-file handle whose ratchet operations include the write that makes
/// accepted observations durable. The live [`LockFile`] is replaced only
/// after that write succeeds, so accepted registry security observations
/// cannot exist only in memory.
struct PersistentLockFile<'borrow, 'lock> {
    lock_file: &'borrow mut GuardedLockFile<'lock>,
}

impl<'borrow, 'lock> PersistentLockFile<'borrow, 'lock> {
    fn new(lock_file: &'borrow mut GuardedLockFile<'lock>) -> Self {
        Self { lock_file }
    }

    fn lock_file(&self) -> &LockFile {
        self.lock_file
    }

    fn install_lock(&self) -> &'lock ProviderInstallLock {
        self.lock_file.install_lock()
    }

    fn persist_lock_file_update(
        &mut self,
        observation: &str,
        update: impl FnOnce(&mut GuardedLockFile<'lock>) -> Result<(), String>,
    ) -> Result<(), String> {
        let path = provider_lock_path(self.lock_file.install_lock().project_dir());
        let mut persisted = self.lock_file.clone_for_save();
        let result = update(&mut persisted).and_then(|()| {
            persisted.save().map_err(|error| {
                format!(
                    "Failed to persist registry {observation} observation to {}: {error}",
                    path.display()
                )
            })
        });

        match result {
            Ok(()) => {
                *self.lock_file = persisted;
                Ok(())
            }
            Err(error) => {
                self.lock_file
                    .restore_registry_sequence_notices_from(&mut persisted);
                Err(error)
            }
        }
    }

    fn persist_registry_ratchets(
        &mut self,
        source: &RemoteSourceKey,
        observation: &str,
        update: impl FnOnce(&mut RegistryRatchets) -> Result<(), String>,
    ) -> Result<(), String> {
        self.persist_lock_file_update(observation, |persisted| {
            let mut ratchets = persisted
                .known_registry_ratchets_by_source_key(source)
                .map_err(|error| error.to_string())?;
            update(&mut ratchets)?;
            persisted
                .store_registry_ratchets(source.as_str(), ratchets)
                .map_err(|error| error.to_string())
        })
    }

    fn validate_and_record_registry_listing(
        &mut self,
        source: &RegistrySource,
        source_key: &RemoteSourceKey,
        versions: &RegistryVersions,
    ) -> Result<ValidatedRegistrySequence, String> {
        let locked = self
            .lock_file
            .known_registry_ratchets_by_source_key(source_key)
            .map_err(|error| error.to_string())?;
        let previous_sequence_state = self
            .lock_file
            .registry_sequence_previous_state_by_source_key(source_key);
        let validated = ValidatedRegistryListing::validate(
            source,
            versions,
            &locked,
            previous_sequence_state,
            self.lock_file.install_lock().project_dir(),
        )?;
        let (observations, validated_sequence) = validated.into_parts();

        if let Some(observations) = observations {
            self.persist_registry_ratchets(source_key, "validated listing", |ratchets| {
                *ratchets = ratchets
                    .clone()
                    .merge(&observations)
                    .map_err(|error| error.to_string())?;
                Ok(())
            })?;
        }
        Ok(validated_sequence)
    }

    fn record_registry_transparency_log_presence(
        &mut self,
        source: &RemoteSourceKey,
        present: bool,
    ) -> Result<(), String> {
        if !present {
            return Ok(());
        }
        self.persist_registry_ratchets(source, "transparency_log presence", |ratchets| {
            ratchets.transparency_log_present = true;
            Ok(())
        })
    }

    fn record_registry_signature_presence(
        &mut self,
        source: &RemoteSourceKey,
        present: bool,
    ) -> Result<(), String> {
        if !present {
            return Ok(());
        }
        self.persist_registry_ratchets(source, "signature presence", |ratchets| {
            ratchets.signature = ratchets
                .signature
                .merge(&RegistrySignatureProtection::Required(
                    SignerPinState::Unpinned,
                ))
                .map_err(|error| error.to_string())?;
            Ok(())
        })
    }

    fn record_signer_acceptance(
        &mut self,
        source: &RemoteSourceKey,
        acceptance: SignerAcceptance,
    ) -> Result<(), String> {
        let SignerAcceptance { next, transition } = acceptance;
        if transition == SignerTransition::LegacyConverted {
            return self.persist_lock_file_update("verified signature", |persisted| {
                persisted.replace_legacy_signer_pin(source.as_str(), next)
            });
        }
        let verified = RegistryRatchets {
            signature: RegistrySignatureProtection::Required(next.clone()),
            ..RegistryRatchets::default()
        };
        self.persist_registry_ratchets(source, "verified signature", |ratchets| {
            *ratchets = ratchets
                .clone()
                .merge(&verified)
                .map_err(|error| error.to_string())?;
            Ok(())
        })
    }

    fn upsert_registry_provider(&mut self, entry: RegistryProviderLockEntry) -> Result<(), String> {
        let RegistryProviderLockEntry {
            name,
            source,
            kind,
            sha256,
            registry,
            validated_sequence,
        } = entry;
        let ratchets = self
            .lock_file
            .known_registry_ratchets_by_source_key(&source)
            .map_err(|error| error.to_string())?;
        let registry_with_host =
            RegistryLock::from_resolved_registry(registry, ratchets, validated_sequence, &source);
        self.lock_file.upsert_registry_with_host(
            LockEntry {
                name,
                source: source.to_string(),
                kind,
                sha256,
                registry: None,
            },
            registry_with_host,
        );
        Ok(())
    }
}

/// A resolved provider artifact path that is guaranteed to have a `.wasm`
/// extension.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WasmArtifactPath(PathBuf);

impl WasmArtifactPath {
    pub(crate) fn new(path: PathBuf, provider_name: &str) -> Result<Self, String> {
        if path
            .extension()
            .is_some_and(|extension| extension == "wasm")
        {
            Ok(Self(path))
        } else {
            Err(format!(
                "Provider '{provider_name}': native binaries are no longer supported. Use a .wasm component instead."
            ))
        }
    }

    pub fn as_path(&self) -> &Path {
        &self.0
    }
}

/// An installed provider artifact together with the resolution provenance that
/// selected it. [`InstalledProvider::load_with`] gives the loader a single
/// [`VerifiedLoad`] that binds the bytes retained from lookup (and verified
/// there for lock-controlled artifacts) to their resolver-derived identity.
/// [`InstalledProvider::path`] is for display and provenance only.
///
/// Lock provenance also has no public attachment constructor:
///
/// ```compile_fail,E0624
/// use carina_provider_resolver::{InstalledProvider, VerifiedArtifact};
/// # let artifact: VerifiedArtifact = panic!();
/// let installed = InstalledProvider::from_verified(artifact, "aws".to_string());
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InstalledProvider {
    artifact: InstalledArtifact,
    provider_name: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum InstalledArtifact {
    LockFile(Box<VerifiedArtifact>),
    File {
        path: WasmArtifactPath,
        bytes: ProviderArtifactBytes,
        source: FileSource,
        canonical_source: PathBuf,
        project_dir: PathBuf,
    },
}

impl InstalledProvider {
    pub fn path(&self) -> &WasmArtifactPath {
        match &self.artifact {
            InstalledArtifact::LockFile(artifact) => artifact.path(),
            InstalledArtifact::File {
                path,
                bytes: _,
                source: _,
                canonical_source: _,
                project_dir: _,
            } => path,
        }
    }

    pub fn provenance(&self) -> ProviderArtifactProvenance {
        match &self.artifact {
            InstalledArtifact::LockFile(artifact) => ProviderArtifactProvenance::LockFile {
                project_dir: artifact.project_dir().to_path_buf(),
                pin: artifact.pin().clone(),
            },
            InstalledArtifact::File {
                path: _,
                bytes: _,
                source,
                canonical_source: _,
                project_dir: _,
            } => ProviderArtifactProvenance::File {
                source: format!("file://{}", source.path()),
            },
        }
    }

    pub fn provider_name(&self) -> &str {
        &self.provider_name
    }

    pub(crate) fn from_verified(artifact: VerifiedArtifact, provider_name: String) -> Self {
        Self {
            artifact: InstalledArtifact::LockFile(Box::new(artifact)),
            provider_name,
        }
    }

    pub(crate) fn file_source(
        path: WasmArtifactPath,
        provider_name: String,
        source: FileSource,
        project_dir: &Path,
    ) -> Result<Self, String> {
        let bytes = ProviderArtifactBytes::read(path.as_path()).map_err(|error| {
            format!(
                "Failed to read provider artifact {}: {error}",
                path.as_path().display()
            )
        })?;
        let canonical_source =
            crate::egress::canonical_project_relative_path(project_dir, Path::new(source.path()))
                .map_err(|error| {
                format!(
                    "Failed to derive project-relative provider source {}: {error}",
                    source.path()
                )
            })?;
        Ok(Self {
            artifact: InstalledArtifact::File {
                path,
                bytes,
                source,
                canonical_source,
                project_dir: project_dir.to_path_buf(),
            },
            provider_name,
        })
    }

    fn artifact_bytes(&self) -> ProviderArtifactBytes {
        match &self.artifact {
            InstalledArtifact::LockFile(artifact) => artifact.bytes().clone(),
            InstalledArtifact::File {
                path: _,
                bytes,
                source: _,
                canonical_source: _,
                project_dir: _,
            } => bytes.clone(),
        }
    }

    fn load_identity(
        &self,
        user_dirs: &UserDirs,
        grants: &TrustedLocalGrants,
        notice_sink: &mut impl FnMut(&str),
    ) -> Result<ProviderLoadIdentity, ProviderLoadIdentityError> {
        let (trust, notice, source) = match &self.artifact {
            InstalledArtifact::LockFile(artifact) => (
                remote_provider_trust(user_dirs, artifact)?,
                None,
                ProviderLoadSource::Remote {
                    source: artifact.source().clone(),
                },
            ),
            InstalledArtifact::File {
                path: _,
                bytes,
                source,
                canonical_source,
                project_dir,
            } => {
                let (trust, notice, path) =
                    local_provider_trust(source, bytes, project_dir, grants, notice_sink);
                (
                    trust,
                    notice,
                    ProviderLoadSource::LocalFile {
                        path,
                        canonical_source: canonical_source.clone(),
                    },
                )
            }
        };
        let identity = ProviderLoadIdentity::new(self.provider_name.clone(), trust, source)?;
        if let Some(notice) = notice {
            notice_sink(&notice);
        }
        Ok(identity)
    }

    fn verified_load<E>(
        &self,
        user_dirs: &UserDirs,
        grants: &TrustedLocalGrants,
    ) -> Result<VerifiedLoad, ProviderArtifactLoadError<E>> {
        let mut notice_sink = |line: &str| eprintln!("{line}");
        let identity = self
            .load_identity(user_dirs, grants, &mut notice_sink)
            .map_err(|error| self.with_identity_error(error))?;
        let bytes = self.artifact_bytes();
        let artifact = match &self.artifact {
            InstalledArtifact::LockFile(artifact) => {
                LoadedArtifactIdentity::locked(&bytes, artifact.source().clone(), artifact.pin())
            }
            InstalledArtifact::File { .. } => LoadedArtifactIdentity::file(&bytes),
        };
        Ok(VerifiedLoad::new(bytes, identity, artifact))
    }

    /// Attach this artifact's provenance to a load failure without flattening
    /// the underlying error. Display always renders the load error first.
    pub fn with_load_error<E>(&self, error: E) -> ProviderArtifactLoadError<E> {
        ProviderArtifactLoadError {
            error: ProviderArtifactLoadFailure::Loader(Box::new(error)),
            provider_name: self.provider_name.clone(),
            artifact_path: self.path().as_path().to_path_buf(),
            provenance: Box::new(self.provenance()),
        }
    }

    fn with_identity_error<E>(
        &self,
        error: ProviderLoadIdentityError,
    ) -> ProviderArtifactLoadError<E> {
        ProviderArtifactLoadError {
            error: ProviderArtifactLoadFailure::Identity(Box::new(error)),
            provider_name: self.provider_name.clone(),
            artifact_path: self.path().as_path().to_path_buf(),
            provenance: Box::new(self.provenance()),
        }
    }

    /// Load through a caller-supplied async function, supplying one value that
    /// binds verified artifact bytes to the resolver-owned load identity while
    /// making provenance attachment mandatory on the error path.
    pub async fn load_with<T, E, F, Fut>(
        &self,
        user_dirs: &UserDirs,
        grants: &TrustedLocalGrants,
        loader: F,
    ) -> Result<T, ProviderArtifactLoadError<E>>
    where
        F: FnOnce(VerifiedLoad) -> Fut,
        Fut: std::future::Future<Output = Result<T, E>>,
    {
        self.load_with_notice_sink(user_dirs, grants, |line| eprintln!("{line}"), loader)
            .await
    }

    async fn load_with_notice_sink<T, E, F, Fut, S>(
        &self,
        user_dirs: &UserDirs,
        grants: &TrustedLocalGrants,
        mut notice_sink: S,
        loader: F,
    ) -> Result<T, ProviderArtifactLoadError<E>>
    where
        F: FnOnce(VerifiedLoad) -> Fut,
        Fut: std::future::Future<Output = Result<T, E>>,
        S: FnMut(&str),
    {
        let identity = self
            .load_identity(user_dirs, grants, &mut notice_sink)
            .map_err(|error| self.with_identity_error(error))?;
        let bytes = self.artifact_bytes();
        let artifact = match &self.artifact {
            InstalledArtifact::LockFile(artifact) => {
                LoadedArtifactIdentity::locked(&bytes, artifact.source().clone(), artifact.pin())
            }
            InstalledArtifact::File { .. } => LoadedArtifactIdentity::file(&bytes),
        };
        loader(VerifiedLoad::new(bytes, identity, artifact))
            .await
            .map_err(|error| self.with_load_error(error))
    }
}

fn remote_provider_trust(
    user_dirs: &UserDirs,
    artifact: &VerifiedArtifact,
) -> Result<ProviderTrust, ProviderLoadIdentityError> {
    if !ProviderTrust::remote_source_is_allowlisted(artifact.source()) {
        return Ok(ProviderTrust::untrusted());
    }

    match load_user_verified_identity(user_dirs, artifact.sha256(), artifact.source()) {
        Ok(Some(identity)) => ProviderTrust::from_verified_remote(&identity).ok_or_else(|| {
            ProviderLoadIdentityError::non_carina_official_signer(
                artifact.source(),
                artifact.project_dir(),
            )
        }),
        Ok(None) => Err(ProviderLoadIdentityError::missing_official_record(
            artifact.source(),
            artifact.project_dir(),
        )),
        Err(error) => Err(ProviderLoadIdentityError::invalid_official_record(
            artifact.source(),
            artifact.project_dir(),
            error,
        )),
    }
}

fn local_provider_trust(
    source: &FileSource,
    installed_bytes: &ProviderArtifactBytes,
    project_dir: &Path,
    grants: &TrustedLocalGrants,
    notice_sink: &mut impl FnMut(&str),
) -> (ProviderTrust, Option<String>, PathBuf) {
    let canonical_path = match fs::canonicalize(source.path()) {
        Ok(canonical_path) => canonical_path,
        Err(_canonicalize_error) => {
            let label_path = std::path::absolute(source.path())
                .unwrap_or_else(|_absolute_error| PathBuf::from(source.path()));
            return (ProviderTrust::untrusted(), None, label_path);
        }
    };
    let Some(grant) = grants.matching(&canonical_path) else {
        return (ProviderTrust::untrusted(), None, canonical_path);
    };
    let installed_sha256 = format!("{:x}", Sha256::digest(installed_bytes.as_bytes()));
    let current_sha256 = sha256_file(&canonical_path).ok();
    if current_sha256.as_deref() != Some(installed_sha256.as_str()) {
        notice_sink(&format!(
            "carina: local provider {} does not match the installed bytes; re-run `{}` before trusting it",
            canonical_path.display(),
            ProjectCommand::new("init", project_dir),
        ));
        return (ProviderTrust::untrusted(), None, canonical_path);
    }
    (grant.trust(), Some(grant.notice()), canonical_path)
}

/// Where an installed provider artifact came from. Locked variants cannot
/// represent `file://`, so only lock-controlled artifacts can produce a stale
/// lock hint.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProviderArtifactProvenance {
    LockFile {
        project_dir: PathBuf,
        pin: LockedProviderPin,
    },
    File {
        source: String,
    },
}

/// The lock-entry modes that can select a cached provider artifact.
/// [`LockEntryKind::File`] is deliberately absent: file artifacts have their
/// own provenance variant and are never candidates for a stale-lock hint.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LockedProviderPin {
    Version {
        version: String,
        constraint: Option<String>,
    },
    GithubRelease {
        version: String,
        tag: ReleaseTag,
        asset_id: AssetId,
        constraint: Option<String>,
    },
    Revision {
        revision: String,
        resolved_sha: CommitSha,
        artifact_id: ArtifactId,
    },
    RegistryRevision {
        revision: String,
        version: String,
    },
}

impl fmt::Display for LockedProviderPin {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LockedProviderPin::Version {
                version,
                constraint,
            } => {
                write!(f, "version {version}")?;
                if let Some(constraint) = constraint {
                    write!(f, ", constraint {constraint}")?;
                }
                Ok(())
            }
            LockedProviderPin::GithubRelease {
                version,
                tag,
                asset_id,
                constraint,
            } => {
                write!(
                    f,
                    "GitHub release {version}, tag {tag}, asset id {asset_id}"
                )?;
                if let Some(constraint) = constraint {
                    write!(f, ", constraint {constraint}")?;
                }
                Ok(())
            }
            LockedProviderPin::Revision {
                revision,
                resolved_sha,
                artifact_id,
            } => write!(
                f,
                "revision {revision}, resolved_sha {resolved_sha}, artifact_id {artifact_id}"
            ),
            LockedProviderPin::RegistryRevision { revision, version } => {
                write!(f, "registry revision {revision}, version {version}")
            }
        }
    }
}

impl fmt::Display for ProviderArtifactProvenance {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ProviderArtifactProvenance::LockFile { project_dir, pin } => {
                let lock_path = provider_lock_path(project_dir);
                write!(
                    f,
                    "provider resolved from {} ({pin}); if this lock is stale, run `{}`",
                    lock_path.display(),
                    ProjectCommand::new("init --upgrade", project_dir)
                )
            }
            ProviderArtifactProvenance::File { source } => write!(
                f,
                "provider resolved from {source}; file providers are not controlled by carina-providers.lock"
            ),
        }
    }
}

/// A provider load failure that retains both the typed underlying error and
/// the artifact provenance selected by the resolver.
#[derive(Debug)]
pub struct ProviderArtifactLoadError<E> {
    error: ProviderArtifactLoadFailure<E>,
    provider_name: String,
    artifact_path: PathBuf,
    provenance: Box<ProviderArtifactProvenance>,
}

#[derive(Debug)]
enum ProviderArtifactLoadFailure<E> {
    Identity(Box<ProviderLoadIdentityError>),
    Loader(Box<E>),
}

impl<E> ProviderArtifactLoadError<E> {
    pub fn identity_error(&self) -> Option<&ProviderLoadIdentityError> {
        match &self.error {
            ProviderArtifactLoadFailure::Identity(error) => Some(error.as_ref()),
            ProviderArtifactLoadFailure::Loader(_) => None,
        }
    }

    pub fn loader_error(&self) -> Option<&E> {
        match &self.error {
            ProviderArtifactLoadFailure::Identity(_) => None,
            ProviderArtifactLoadFailure::Loader(error) => Some(error.as_ref()),
        }
    }

    pub fn into_identity_error(self) -> Result<ProviderLoadIdentityError, Self> {
        let Self {
            error,
            provider_name,
            artifact_path,
            provenance,
        } = self;
        match error {
            ProviderArtifactLoadFailure::Identity(error) => Ok(*error),
            ProviderArtifactLoadFailure::Loader(error) => Err(Self {
                error: ProviderArtifactLoadFailure::Loader(error),
                provider_name,
                artifact_path,
                provenance,
            }),
        }
    }
}

impl<E: fmt::Display> fmt::Display for ProviderArtifactLoadError<E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let error: &dyn fmt::Display = match &self.error {
            ProviderArtifactLoadFailure::Identity(error) => error.as_ref(),
            ProviderArtifactLoadFailure::Loader(error) => error.as_ref(),
        };
        write!(
            f,
            "{}\nProvider: {}\nArtifact: {}\n{}",
            error,
            self.provider_name,
            self.artifact_path.display(),
            self.provenance
        )
    }
}

// `Display` is the sole rendering surface for this composite diagnostic: CLI
// and LSP callers require one self-contained message containing both the child
// error and provenance. Exposing the same child through `source()` would make
// standard chain walkers print it again.
impl<E> std::error::Error for ProviderArtifactLoadError<E> where E: std::error::Error + 'static {}

fn missing_locked_artifact_error(
    base_dir: &Path,
    pin: &LockedProviderPin,
    requested_revision: Option<&str>,
) -> String {
    let command = ProjectCommand::new("init", base_dir);
    let lock_path = provider_lock_path(base_dir);
    let action = match requested_revision {
        Some(revision) => {
            format!("not installed. Run `{command}` to install (revision: {revision})")
        }
        None => format!("not installed. Run `{command}`"),
    };
    format!(
        "{action}\nConsulted {} ({pin}), but its artifact is missing.",
        lock_path.display()
    )
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FindInstalledProviderError {
    LegacyEntry(LegacyLockEntryError),
    Other(String),
}

impl fmt::Display for FindInstalledProviderError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LegacyEntry(error) => error.fmt(formatter),
            Self::Other(message) => formatter.write_str(message),
        }
    }
}

impl std::error::Error for FindInstalledProviderError {}

impl From<String> for FindInstalledProviderError {
    fn from(message: String) -> Self {
        Self::Other(message)
    }
}

// Registry sequence advances only when the canonical version-set digest changes;
// timestamp-only re-issues reuse it. Once a successful resolve establishes an
// anchor, later successful pins can advance it by at most this amount. A failed
// observation cannot move that anchor, and true first contact has no numeric base.
const MAX_SEQUENCE_FAST_FORWARD: u64 = 1_000_000;
const MAX_SIGNATURE_BUNDLE_BYTES: usize = 1024 * 1024;

/// Per-provider security state or immutable protocol rule that can cause a
/// registry response to be refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProviderLockState {
    // Current refusals consult the sequence anchor or presence bit, but the
    // independently persisted observation is still cleared by re-bootstrap.
    #[cfg_attr(not(test), allow(dead_code))]
    SequenceObservation,
    SequenceReferencePoint,
    SequencePresence,
    SignerPins,
    SignaturePresence,
    ValidUntilPresence,
    TransparencyLogPresence,
    YankedFlag,
    ShasumPin,
    HostnamePin,
    StableSourceRefRule,
}

#[cfg(test)]
#[repr(usize)]
enum ProviderLockStateIndex {
    SequenceObservation,
    SequenceReferencePoint,
    SequencePresence,
    SignerPins,
    SignaturePresence,
    ValidUntilPresence,
    TransparencyLogPresence,
    YankedFlag,
    ShasumPin,
    HostnamePin,
    StableSourceRefRule,
    Count,
}

#[cfg(test)]
const PROVIDER_LOCK_STATE_COUNT: usize = ProviderLockStateIndex::Count as usize;

impl ProviderLockState {
    #[cfg(test)]
    const ALL: [Self; PROVIDER_LOCK_STATE_COUNT] = [
        Self::SequenceObservation,
        Self::SequenceReferencePoint,
        Self::SequencePresence,
        Self::SignerPins,
        Self::SignaturePresence,
        Self::ValidUntilPresence,
        Self::TransparencyLogPresence,
        Self::YankedFlag,
        Self::ShasumPin,
        Self::HostnamePin,
        Self::StableSourceRefRule,
    ];

    #[cfg(test)]
    const fn index(self) -> usize {
        match self {
            Self::SequenceObservation => ProviderLockStateIndex::SequenceObservation as usize,
            Self::SequenceReferencePoint => ProviderLockStateIndex::SequenceReferencePoint as usize,
            Self::SequencePresence => ProviderLockStateIndex::SequencePresence as usize,
            Self::SignerPins => ProviderLockStateIndex::SignerPins as usize,
            Self::SignaturePresence => ProviderLockStateIndex::SignaturePresence as usize,
            Self::ValidUntilPresence => ProviderLockStateIndex::ValidUntilPresence as usize,
            Self::TransparencyLogPresence => {
                ProviderLockStateIndex::TransparencyLogPresence as usize
            }
            Self::YankedFlag => ProviderLockStateIndex::YankedFlag as usize,
            Self::ShasumPin => ProviderLockStateIndex::ShasumPin as usize,
            Self::HostnamePin => ProviderLockStateIndex::HostnamePin as usize,
            Self::StableSourceRefRule => ProviderLockStateIndex::StableSourceRefRule as usize,
        }
    }
}

/// Per-host security state that can cause registry discovery to be refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HostLockState {
    DiscoveryPin,
    LegacyDiscoveryValues,
}

#[cfg(test)]
#[repr(usize)]
enum HostLockStateIndex {
    DiscoveryPin,
    LegacyDiscoveryValues,
    Count,
}

#[cfg(test)]
const HOST_LOCK_STATE_COUNT: usize = HostLockStateIndex::Count as usize;

impl HostLockState {
    #[cfg(test)]
    const ALL: [Self; HOST_LOCK_STATE_COUNT] = [Self::DiscoveryPin, Self::LegacyDiscoveryValues];

    #[cfg(test)]
    const fn index(self) -> usize {
        match self {
            Self::DiscoveryPin => HostLockStateIndex::DiscoveryPin as usize,
            Self::LegacyDiscoveryValues => HostLockStateIndex::LegacyDiscoveryValues as usize,
        }
    }
}

