mod recovery {
    use super::{
        HostLockState, HostRefusalTarget, Path, ProjectCommand, ProviderLockState,
        ProviderRefusalTarget, fmt,
    };

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum ProviderRecovery {
        Rebootstrap,
        IdentityRepin,
    }

    impl ProviderRecovery {
        #[cfg(test)]
        pub(super) const ALL: [Self; 2] = [Self::Rebootstrap, Self::IdentityRepin];

        const fn subcommand(self) -> &'static str {
            match self {
                Self::Rebootstrap => "providers re-bootstrap",
                Self::IdentityRepin => "providers repin-identity",
            }
        }
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum HostRecovery {
        DiscoveryRepin,
    }

    impl HostRecovery {
        #[cfg(test)]
        pub(super) const ALL: [Self; 1] = [Self::DiscoveryRepin];

        const fn subcommand(self) -> &'static str {
            match self {
                Self::DiscoveryRepin => "providers repin-discovery",
            }
        }
    }

    #[cfg(test)]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum RecoveryKind {
        Rebootstrap,
        IdentityRepin,
        DiscoveryRepin,
    }

    impl ProviderLockState {
        pub(super) const fn cleared_by(self) -> Option<ProviderRecovery> {
            match self {
                Self::SequenceObservation
                | Self::SequenceReferencePoint
                | Self::SequencePresence => Some(ProviderRecovery::Rebootstrap),
                Self::SignerPins => Some(ProviderRecovery::IdentityRepin),
                Self::SignaturePresence
                | Self::ValidUntilPresence
                | Self::TransparencyLogPresence
                | Self::YankedFlag
                | Self::ShasumPin
                | Self::HostnamePin
                | Self::StableSourceRefRule => None,
            }
        }
    }

    impl HostLockState {
        pub(super) const fn cleared_by(self) -> Option<HostRecovery> {
            match self {
                Self::DiscoveryPin | Self::LegacyDiscoveryValues => {
                    Some(HostRecovery::DiscoveryRepin)
                }
            }
        }
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum RemediationKind<'a> {
        Provider(
            ProviderRecovery,
            ProviderLockState,
            &'a ProviderRefusalTarget,
        ),
        Host(HostRecovery, HostLockState, &'a HostRefusalTarget),
    }

    /// A recovery paired with the only target scope accepted by that operation.
    /// Its private representation makes derivation from a lock-state cause the
    /// only construction path.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) struct Remediation<'a>(RemediationKind<'a>);

    impl<'a> Remediation<'a> {
        pub(super) const fn for_provider(
            cause: ProviderLockState,
            target: &'a ProviderRefusalTarget,
        ) -> Option<Self> {
            match cause.cleared_by() {
                Some(operation) => Some(Self(RemediationKind::Provider(operation, cause, target))),
                None => None,
            }
        }

        pub(super) const fn for_host(
            cause: HostLockState,
            target: &'a HostRefusalTarget,
        ) -> Option<Self> {
            match cause.cleared_by() {
                Some(operation) => Some(Self(RemediationKind::Host(operation, cause, target))),
                None => None,
            }
        }

        pub(super) fn command(self) -> ProjectCommand<'a> {
            match self.0 {
                RemediationKind::Provider(operation, _, target) => {
                    ProjectCommand::new(operation.subcommand(), &target.project_dir)
                        .with_argument(&target.source_key)
                }
                RemediationKind::Host(operation, _, target) => {
                    ProjectCommand::new(operation.subcommand(), &target.project_dir)
                        .with_argument(&target.host)
                }
            }
        }

        pub(super) fn same_operation_and_target(self, other: Self) -> bool {
            match (self.0, other.0) {
                (
                    RemediationKind::Provider(operation, _, target),
                    RemediationKind::Provider(other_operation, _, other_target),
                ) => operation == other_operation && target == other_target,
                (
                    RemediationKind::Host(operation, _, target),
                    RemediationKind::Host(other_operation, _, other_target),
                ) => operation == other_operation && target == other_target,
                (RemediationKind::Provider(_, _, _), RemediationKind::Host(_, _, _))
                | (RemediationKind::Host(_, _, _), RemediationKind::Provider(_, _, _)) => false,
            }
        }

        fn project_dir(self) -> &'a Path {
            match self.0 {
                RemediationKind::Provider(_, _, target) => &target.project_dir,
                RemediationKind::Host(_, _, target) => &target.project_dir,
            }
        }

        #[cfg(test)]
        pub(super) const fn subcommand(self) -> &'static str {
            match self.0 {
                RemediationKind::Provider(operation, _, _) => operation.subcommand(),
                RemediationKind::Host(operation, _, _) => operation.subcommand(),
            }
        }

        #[cfg(test)]
        pub(super) const fn kind(self) -> RecoveryKind {
            match self.0 {
                RemediationKind::Provider(ProviderRecovery::Rebootstrap, _, _) => {
                    RecoveryKind::Rebootstrap
                }
                RemediationKind::Provider(ProviderRecovery::IdentityRepin, _, _) => {
                    RecoveryKind::IdentityRepin
                }
                RemediationKind::Host(HostRecovery::DiscoveryRepin, _, _) => {
                    RecoveryKind::DiscoveryRepin
                }
            }
        }

        pub(super) fn fmt(self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            let command = self.command();
            let init = ProjectCommand::new("init", self.project_dir());
            match self.0 {
                RemediationKind::Provider(ProviderRecovery::Rebootstrap, _, _) => write!(
                    formatter,
                    "After verifying out-of-band that resetting registry freshness is intended, run `{command}` to clear only the persisted sequence observation, anchor and presence record, then re-run `{init}`."
                ),
                RemediationKind::Provider(ProviderRecovery::IdentityRepin, _, _) => write!(
                    formatter,
                    "After verifying out-of-band that the signing-identity change is intended, run `{command}` to clear only the identity pin, then re-run `{init}` to acquire and verify a new pin."
                ),
                RemediationKind::Host(
                    HostRecovery::DiscoveryRepin,
                    HostLockState::DiscoveryPin,
                    _,
                ) => write!(
                    formatter,
                    "After verifying out-of-band that the change to the pinned discovery values (today, the resolved API base) is intended, run `{command}` to clear only those host discovery values, then re-run `{init}` to acquire and verify new values."
                ),
                RemediationKind::Host(
                    HostRecovery::DiscoveryRepin,
                    HostLockState::LegacyDiscoveryValues,
                    _,
                ) => write!(
                    formatter,
                    "After verifying out of band that discarding this host's legacy discovery values is intended, run `{command}` to clear only those legacy host discovery values, then re-run `{init}`."
                ),
            }
        }
    }
}

use recovery::Remediation;

#[cfg(test)]
use recovery::{HostRecovery, ProviderRecovery, RecoveryKind};

#[derive(Debug, Clone, Copy)]
enum ScopedRegistryRefusal<'a> {
    Provider {
        cause: ProviderLockState,
        target: &'a ProviderRefusalTarget,
    },
    Host {
        cause: HostLockState,
        target: &'a HostRefusalTarget,
    },
}

impl<'a> ScopedRegistryRefusal<'a> {
    fn recovery(self) -> Option<Remediation<'a>> {
        match self {
            Self::Provider { cause, target } => Remediation::for_provider(cause, target),
            Self::Host { cause, target } => Remediation::for_host(cause, target),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RegistryRefusal {
    SequenceFieldDisappeared {
        target: ProviderRefusalTarget,
    },
    SequenceRollback {
        previous: u64,
        current: u64,
        target: ProviderRefusalTarget,
    },
    SequenceFastForward {
        anchor: u64,
        current: u64,
        target: ProviderRefusalTarget,
    },
    YankedFlagDisappeared {
        versions: Vec<String>,
        target: ProviderRefusalTarget,
    },
    ValidUntilFieldDisappeared {
        target: ProviderRefusalTarget,
    },
    DiscoveryMigrationAuthorizationRequired {
        target: HostRefusalTarget,
    },
    DiscoveryPinMismatch {
        pinned: String,
        resolved: String,
        target: HostRefusalTarget,
    },
    LegacyShasumPinMismatch {
        version: String,
        locked: String,
        resolved: String,
        target: ProviderRefusalTarget,
    },
    LegacySignatureMissing {
        version: String,
        target: ProviderRefusalTarget,
    },
    ShasumPinMismatch {
        version: String,
        locked: String,
        resolved: String,
        target: ProviderRefusalTarget,
    },
    HostnamePinMismatch {
        locked: String,
        resolved: String,
        target: ProviderRefusalTarget,
    },
    SignatureFieldDisappeared {
        target: ProviderRefusalTarget,
    },
    TransparencyLogFieldDisappeared {
        target: ProviderRefusalTarget,
    },
    Signer {
        rejection: SignerRejection,
        target: ProviderRefusalTarget,
    },
}

impl RegistryRefusal {
    fn from_signer_rejection(rejection: SignerRejection, source: &str, project_dir: &Path) -> Self {
        Self::Signer {
            rejection,
            target: ProviderRefusalTarget::new(source, project_dir),
        }
    }

    fn scoped(&self) -> ScopedRegistryRefusal<'_> {
        match self {
            Self::SequenceFieldDisappeared { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::SequencePresence,
                target,
            },
            Self::SequenceRollback { target, .. } | Self::SequenceFastForward { target, .. } => {
                ScopedRegistryRefusal::Provider {
                    cause: ProviderLockState::SequenceReferencePoint,
                    target,
                }
            }
            Self::YankedFlagDisappeared { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::YankedFlag,
                target,
            },
            Self::ValidUntilFieldDisappeared { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::ValidUntilPresence,
                target,
            },
            Self::DiscoveryMigrationAuthorizationRequired { target, .. } => {
                ScopedRegistryRefusal::Host {
                    cause: HostLockState::LegacyDiscoveryValues,
                    target,
                }
            }
            Self::DiscoveryPinMismatch { target, .. } => ScopedRegistryRefusal::Host {
                cause: HostLockState::DiscoveryPin,
                target,
            },
            // Identity re-pin would bypass legacy conversion, but it does not
            // clear changed immutable-version content and is not its recovery.
            Self::LegacyShasumPinMismatch { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::ShasumPin,
                target,
            },
            Self::LegacySignatureMissing { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::SignaturePresence,
                target,
            },
            Self::ShasumPinMismatch { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::ShasumPin,
                target,
            },
            Self::SignatureFieldDisappeared { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::SignaturePresence,
                target,
            },
            Self::HostnamePinMismatch { target, .. } => ScopedRegistryRefusal::Provider {
                cause: ProviderLockState::HostnamePin,
                target,
            },
            Self::TransparencyLogFieldDisappeared { target, .. } => {
                ScopedRegistryRefusal::Provider {
                    cause: ProviderLockState::TransparencyLogPresence,
                    target,
                }
            }
            Self::Signer { rejection, target } => {
                let cause = match rejection {
                    SignerRejection::StableSourceRef { .. } => {
                        ProviderLockState::StableSourceRefRule
                    }
                    SignerRejection::LegacyIdentity
                    | SignerRejection::SourceMismatch { .. }
                    | SignerRejection::Workflow { .. } => ProviderLockState::SignerPins,
                };
                ScopedRegistryRefusal::Provider { cause, target }
            }
        }
    }

    fn recovery(&self) -> Option<Remediation<'_>> {
        self.scoped().recovery()
    }

    fn fmt_reason(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::SequenceFieldDisappeared { target } => write!(
                formatter,
                "registry sequence field disappeared for {}",
                target.source_key
            ),
            Self::SequenceRollback {
                previous,
                current,
                target,
            } => write!(
                formatter,
                "registry sequence rollback for {}: previous {previous}, got {current}",
                target.source_key
            ),
            Self::SequenceFastForward {
                anchor,
                current,
                target,
            } => write!(
                formatter,
                "registry sequence fast-forward for {} is too large: established anchor {anchor}, got {current}",
                target.source_key
            ),
            Self::YankedFlagDisappeared { versions, target } => write!(
                formatter,
                "registry yanked flag disappeared for {} version(s): {}",
                target.source_key,
                versions.join(", ")
            ),
            Self::ValidUntilFieldDisappeared { target } => write!(
                formatter,
                "registry valid_until field disappeared for {}",
                target.source_key
            ),
            Self::DiscoveryMigrationAuthorizationRequired { target } => write!(
                formatter,
                "registry discovery for host {} is blocked because its legacy lock-format migration requires operator authorization",
                target.host
            ),
            Self::DiscoveryPinMismatch {
                pinned,
                resolved,
                target,
            } => write!(
                formatter,
                "registry pinned discovery values mismatch for host {}: pinned providers.v1 was {pinned}; resolved providers.v1 is {resolved}",
                target.host
            ),
            Self::LegacyShasumPinMismatch {
                version,
                locked,
                resolved,
                target,
            } => write!(
                formatter,
                "registry shasum for the legacy-pinned version {}@{version} differs from carina-providers.lock: lock has {locked}, registry returned {resolved}",
                target.source_key
            ),
            Self::LegacySignatureMissing { version, target } => write!(
                formatter,
                "legacy-pinned version {}@{version} was obtained without its required registry signature",
                target.source_key
            ),
            Self::ShasumPinMismatch {
                version,
                locked,
                resolved,
                target,
            } => write!(
                formatter,
                "registry shasum pin mismatch for {}@{version}: lock has {locked}, registry returned {resolved}",
                target.source_key
            ),
            Self::HostnamePinMismatch {
                locked,
                resolved,
                target,
            } => write!(
                formatter,
                "registry hostname pin mismatch for {}: lock has {locked}, resolved {resolved}",
                target.source_key
            ),
            Self::SignatureFieldDisappeared { target } => write!(
                formatter,
                "the resolved version of {} has no registry signature, but carina-providers.lock records signatures as required for this provider; downgrades from signed to unsigned versions are refused and have no override",
                target.source_key
            ),
            Self::TransparencyLogFieldDisappeared { target } => write!(
                formatter,
                "registry transparency_log field disappeared for {}",
                target.source_key
            ),
            Self::Signer { rejection, .. } => {
                write!(
                    formatter,
                    "{rejection}; signature verification has no override"
                )
            }
        }
    }
}

impl fmt::Display for RegistryRefusal {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.fmt_reason(formatter)?;
        formatter.write_str(". ")?;
        match self.recovery() {
            Some(remediation) => remediation.fmt(formatter),
            None => formatter.write_str("No sanctioned recovery operation clears this refusal."),
        }
    }
}

impl std::error::Error for RegistryRefusal {}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RegistryRefusals {
    first: RegistryRefusal,
    rest: Vec<RegistryRefusal>,
}

impl RegistryRefusals {
    fn new(first: RegistryRefusal) -> Self {
        Self {
            first,
            rest: Vec::new(),
        }
    }

    fn insert(refusals: &mut Option<Self>, refusal: RegistryRefusal) {
        match refusals {
            Some(refusals) => refusals.rest.push(refusal),
            None => *refusals = Some(Self::new(refusal)),
        }
    }

    fn iter(&self) -> impl Iterator<Item = &RegistryRefusal> {
        std::iter::once(&self.first).chain(&self.rest)
    }
}

impl fmt::Display for RegistryRefusals {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.rest.is_empty() {
            return self.first.fmt(formatter);
        }

        formatter.write_str("Registry response was refused for multiple reasons: ")?;
        for (index, refusal) in self.iter().enumerate() {
            if index > 0 {
                formatter.write_str("; ")?;
            }
            refusal.fmt_reason(formatter)?;
        }
        formatter.write_str(". ")?;

        let mut remediations = Vec::new();
        for refusal in self.iter() {
            let Some(remediation) = refusal.recovery() else {
                return formatter
                    .write_str("No sanctioned recovery operation clears all of these refusals.");
            };
            if !remediations
                .iter()
                .any(|existing| remediation.same_operation_and_target(*existing))
            {
                remediations.push(remediation);
            }
        }
        for (index, remediation) in remediations.into_iter().enumerate() {
            if index > 0 {
                formatter.write_str(" ")?;
            }
            remediation.fmt(formatter)?;
        }
        Ok(())
    }
}

impl std::error::Error for RegistryRefusals {}

/// A registry whose hostname and API base were resolved through §1 discovery.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ResolvedRegistry {
    hostname: String,
    discovery_pin: RegistryDiscoveryPin,
}

impl ResolvedRegistry {
    fn api_base_url(&self) -> &str {
        self.discovery_pin.api_base_url()
    }
}

mod registry_resource_url {
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub(super) struct RegistryResourceUrl(String);

    #[derive(Debug)]
    pub(super) enum RegistryResourceUrlError {
        Invalid(url::ParseError),
        MustUseHttps,
        MustHaveHost,
        ContainsUserinfo,
    }

    impl RegistryResourceUrl {
        pub(super) fn parse(raw: &str) -> Result<Self, RegistryResourceUrlError> {
            let parsed = url::Url::parse(raw).map_err(RegistryResourceUrlError::Invalid)?;
            if !parsed.username().is_empty() || parsed.password().is_some() {
                return Err(RegistryResourceUrlError::ContainsUserinfo);
            }
            if parsed.scheme() != "https" {
                return Err(RegistryResourceUrlError::MustUseHttps);
            }
            if !super::is_absolute_https_url(&parsed) {
                return Err(RegistryResourceUrlError::MustHaveHost);
            }
            Ok(Self(raw.to_owned()))
        }

        pub(super) fn as_str(&self) -> &str {
            &self.0
        }
    }
}

use registry_resource_url::{RegistryResourceUrl, RegistryResourceUrlError};

fn parse_registry_resource_url(
    raw: &str,
    description: &str,
) -> Result<RegistryResourceUrl, String> {
    RegistryResourceUrl::parse(raw).map_err(|error| match error {
        RegistryResourceUrlError::Invalid(source) => {
            format!("{description} must be an absolute HTTPS URL: {source}")
        }
        RegistryResourceUrlError::MustUseHttps => {
            format!("{description} must use HTTPS: {raw}")
        }
        RegistryResourceUrlError::MustHaveHost => {
            format!("{description} must be an absolute HTTPS URL with a host")
        }
        RegistryResourceUrlError::ContainsUserinfo => {
            format!("{description} must not contain userinfo")
        }
    })
}

#[derive(Debug, Clone, Copy)]
enum RegistryHttpRequest<'a> {
    Discovery(&'a str),
    Resource(&'a RegistryResourceUrl),
}

impl<'a> RegistryHttpRequest<'a> {
    fn url(self) -> &'a str {
        match self {
            Self::Discovery(url) => url,
            Self::Resource(url) => url.as_str(),
        }
    }
}

#[derive(Debug, Clone)]
enum HttpResponse {
    Success { body: Vec<u8> },
    Failure { status: u16 },
}

#[derive(Debug)]
enum RegistryDownloadError {
    Transport(String),
    HttpStatus { status: u16, url: String },
    LocalIo(String),
}

impl RegistryDownloadError {
    fn is_unavailable(&self) -> bool {
        matches!(
            self,
            Self::Transport(_) | Self::HttpStatus { status: 404, .. }
        )
    }
}

impl fmt::Display for RegistryDownloadError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Transport(message) | Self::LocalIo(message) => formatter.write_str(message),
            Self::HttpStatus { status, url } => {
                write!(formatter, "Download failed with status {status}: {url}")
            }
        }
    }
}

trait RegistryHttp {
    fn get(&self, request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String>;

    #[cfg(any(test, feature = "test-utils"))]
    fn fixture_signer_identity(&self) -> Option<signing::VerifiedSignerIdentity> {
        None
    }

    fn download_into(
        &self,
        url: &RegistryResourceUrl,
        out: &mut StagedArtifact<'_>,
    ) -> Result<(), RegistryDownloadError> {
        let raw_url = url.as_str();
        let body = match self
            .get(RegistryHttpRequest::Resource(url))
            .map_err(RegistryDownloadError::Transport)?
        {
            HttpResponse::Success { body } => body,
            HttpResponse::Failure { status } => {
                return Err(RegistryDownloadError::HttpStatus {
                    status,
                    url: raw_url.to_string(),
                });
            }
        };
        out.write_all(&body).map_err(|error| {
            RegistryDownloadError::LocalIo(format!("Failed to write downloaded file: {error}"))
        })?;
        Ok(())
    }
}

/// In-memory registry transport used by cross-crate integration tests. It is
/// feature-gated so production callers cannot accidentally bypass the HTTPS
/// transport, while still exercising the complete resolver and verifier.
#[cfg(any(test, feature = "test-utils"))]
#[derive(Clone, Default)]
pub struct FixtureRegistryHttp {
    responses: HashMap<String, FixtureRegistryResponse>,
    downloads: HashMap<String, Vec<u8>>,
    requested: std::sync::Arc<std::sync::Mutex<Vec<String>>>,
    signer_identity: Option<signing::VerifiedSignerIdentity>,
}

#[cfg(any(test, feature = "test-utils"))]
#[derive(Clone)]
enum FixtureRegistryResponse {
    Body { status: u16, body: Vec<u8> },
    TransportError(String),
}

#[cfg(any(test, feature = "test-utils"))]
impl FixtureRegistryHttp {
    /// Override the identity extracted from an otherwise genuinely verified
    /// fixture bundle. This keeps cross-crate install tests small: they can use
    /// the conformance artifact and bundle while exercising official-signer
    /// trust-record behavior without checking a production provider WASM into
    /// this repository.
    #[allow(clippy::too_many_arguments)]
    pub fn verified_signer_identity(
        mut self,
        certificate_san: &str,
        oidc_issuer: &str,
        repository_owner_id: &str,
        repository_id: &str,
        source_ref: &str,
        workflow: &str,
        repository_digest: Option<&str>,
    ) -> Self {
        self.signer_identity = Some(signing::VerifiedSignerIdentity::for_test(
            certificate_san,
            oidc_issuer,
            repository_owner_id,
            repository_id,
            source_ref,
            workflow,
            repository_digest,
        ));
        self
    }

    pub fn json(mut self, url: &str, body: impl AsRef<[u8]>) -> Self {
        self.responses.insert(
            url.to_string(),
            FixtureRegistryResponse::Body {
                status: 200,
                body: body.as_ref().to_vec(),
            },
        );
        self
    }

    pub fn response(mut self, url: &str, status: u16, body: impl AsRef<[u8]>) -> Self {
        self.downloads.remove(url);
        self.responses.insert(
            url.to_string(),
            FixtureRegistryResponse::Body {
                status,
                body: body.as_ref().to_vec(),
            },
        );
        self
    }

    pub fn transport_error(mut self, url: &str, error: impl Into<String>) -> Self {
        self.downloads.remove(url);
        self.responses.insert(
            url.to_string(),
            FixtureRegistryResponse::TransportError(error.into()),
        );
        self
    }

    pub fn downloadable_bytes(mut self, url: &str, body: impl Into<Vec<u8>>) -> Self {
        self.downloads.insert(url.to_string(), body.into());
        self
    }

    pub fn requested_urls(&self) -> Vec<String> {
        self.requested.lock().unwrap().clone()
    }
}

#[cfg(any(test, feature = "test-utils"))]
impl RegistryHttp for FixtureRegistryHttp {
    fn fixture_signer_identity(&self) -> Option<signing::VerifiedSignerIdentity> {
        self.signer_identity.clone()
    }

    fn get(&self, request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String> {
        let url = request.url();
        self.requested.lock().unwrap().push(url.to_string());
        match self.responses.get(url) {
            Some(FixtureRegistryResponse::Body { status, body }) => {
                if (200..300).contains(status) {
                    Ok(HttpResponse::Success { body: body.clone() })
                } else {
                    Ok(HttpResponse::Failure { status: *status })
                }
            }
            Some(FixtureRegistryResponse::TransportError(error)) => Err(error.clone()),
            None => Err(format!("unexpected fixture registry URL: {url}")),
        }
    }

    fn download_into(
        &self,
        url: &RegistryResourceUrl,
        out: &mut StagedArtifact<'_>,
    ) -> Result<(), RegistryDownloadError> {
        let url = url.as_str();
        self.requested.lock().unwrap().push(url.to_string());
        let body = match self.downloads.get(url) {
            Some(body) => body,
            None => match self.responses.get(url) {
                Some(FixtureRegistryResponse::Body { status, body })
                    if (200..300).contains(status) =>
                {
                    body
                }
                Some(FixtureRegistryResponse::Body { status, .. }) => {
                    return Err(RegistryDownloadError::HttpStatus {
                        status: *status,
                        url: url.to_string(),
                    });
                }
                Some(FixtureRegistryResponse::TransportError(error)) => {
                    return Err(RegistryDownloadError::Transport(error.clone()));
                }
                None => {
                    return Err(RegistryDownloadError::Transport(format!(
                        "unexpected fixture registry download URL: {url}"
                    )));
                }
            },
        };
        out.write_all(body).map_err(|error| {
            RegistryDownloadError::LocalIo(format!("Failed to write downloaded file: {error}"))
        })
    }
}

struct UreqRegistryHttp;

impl UreqRegistryHttp {
    fn agent(request: RegistryHttpRequest<'_>) -> ureq::Agent {
        match request {
            RegistryHttpRequest::Discovery(_) => ureq::Agent::config_builder()
                .max_redirects(0)
                .build()
                .into(),
            RegistryHttpRequest::Resource(_) => ureq::Agent::config_builder()
                .https_only(true)
                .build()
                .into(),
        }
    }
}

impl RegistryHttp for UreqRegistryHttp {
    fn get(&self, request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String> {
        let url = request.url();
        let response = Self::agent(request).get(url).call();
        let response = match response {
            Ok(response) => response,
            Err(ureq::Error::StatusCode(status)) => {
                return Ok(HttpResponse::Failure { status });
            }
            Err(e) => return Err(format!("Failed to fetch {url}: {e}")),
        };
        let status = response.status().into();
        if !(200..300).contains(&status) {
            return Ok(HttpResponse::Failure { status });
        }
        let body = response
            .into_body()
            .read_to_vec()
            .map_err(|e| format!("Failed to read response body from {url}: {e}"))?;
        Ok(HttpResponse::Success { body })
    }

    fn download_into(
        &self,
        url: &RegistryResourceUrl,
        out: &mut StagedArtifact<'_>,
    ) -> Result<(), RegistryDownloadError> {
        let request = RegistryHttpRequest::Resource(url);
        let url = url.as_str();
        let response = match Self::agent(request).get(url).call() {
            Ok(response) => response,
            Err(ureq::Error::StatusCode(status)) => {
                return Err(RegistryDownloadError::HttpStatus {
                    status,
                    url: url.to_string(),
                });
            }
            Err(error) => {
                return Err(RegistryDownloadError::Transport(format!(
                    "Failed to download {url}: {error}"
                )));
            }
        };

        let status = response.status().into();
        if status != 200 {
            return Err(RegistryDownloadError::HttpStatus {
                status,
                url: url.to_string(),
            });
        }

        let mut reader = response.into_body().into_reader();
        let mut buffer = [0_u8; 64 * 1024];
        loop {
            let read = reader.read(&mut buffer).map_err(|error| {
                RegistryDownloadError::Transport(format!(
                    "Failed to read download response from {url}: {error}"
                ))
            })?;
            if read == 0 {
                break;
            }
            out.write_all(&buffer[..read]).map_err(|error| {
                RegistryDownloadError::LocalIo(format!("Failed to write downloaded file: {error}"))
            })?;
        }

        Ok(())
    }
}

#[derive(Debug, Deserialize)]
struct DiscoveryDocument {
    #[serde(rename = "providers.v1")]
    providers_v1: String,
}

#[derive(Debug, Deserialize)]
struct RegistryVersions {
    sequence: Option<u64>,
    valid_until: Option<String>,
    versions: Vec<RegistryVersion>,
}

#[derive(Debug, Deserialize)]
struct RegistryVersion {
    version: String,
    #[serde(default)]
    yanked: bool,
}

mod registry_listing_validation {
    use super::*;

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum RegistrySequenceTransition {
        Unchanged,
        Advanced { previous: u64, current: u64 },
        Established(u64),
        StillUnestablished,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    enum RegistrySequenceNoticeKind {
        Established(u64),
        StillUnestablished,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub(crate) struct RegistrySequenceNotice {
        source_key: String,
        kind: RegistrySequenceNoticeKind,
    }

    impl fmt::Display for RegistrySequenceNotice {
        fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            match self.kind {
                RegistrySequenceNoticeKind::Established(sequence) => write!(
                    formatter,
                    "carina: established registry sequence anchor for {}: {sequence}",
                    self.source_key
                ),
                RegistrySequenceNoticeKind::StillUnestablished => write!(
                    formatter,
                    "carina: registry listing for {} has no sequence; no reference point established",
                    self.source_key
                ),
            }
        }
    }

    impl RegistrySequenceTransition {
        fn into_notice(self, source_key: &RemoteSourceKey) -> Option<RegistrySequenceNotice> {
            let kind = match self {
                Self::Unchanged | Self::Advanced { .. } => None,
                Self::Established(sequence) => {
                    Some(RegistrySequenceNoticeKind::Established(sequence))
                }
                Self::StillUnestablished => Some(RegistrySequenceNoticeKind::StillUnestablished),
            }?;
            Some(RegistrySequenceNotice {
                source_key: source_key.to_string(),
                kind,
            })
        }
    }

    /// The sequence from a listing that passed every listing-level check.
    /// Only this proof can establish the anchor written by a successful pin.
    #[derive(Debug)]
    pub(super) struct ValidatedRegistrySequence {
        sequence: RegistrySequence,
        transition: RegistrySequenceTransition,
    }

    impl ValidatedRegistrySequence {
        pub(super) fn into_anchor_and_notice(
            self,
            source_key: &RemoteSourceKey,
        ) -> (RegistrySequenceAnchor, Option<RegistrySequenceNotice>) {
            let anchor = match self.sequence {
                RegistrySequence::Absent => RegistrySequenceAnchor::Unestablished,
                RegistrySequence::Present(sequence) => {
                    RegistrySequenceAnchor::Established(sequence)
                }
            };
            (anchor, self.transition.into_notice(source_key))
        }
    }

    /// Listing observations that can only be constructed after every listing
    /// check has accepted the response.
    #[derive(Debug)]
    pub(super) struct ValidatedRegistryListing {
        observations: Option<RegistryRatchets>,
        sequence: ValidatedRegistrySequence,
    }

    impl ValidatedRegistryListing {
        pub(super) fn validate(
            source: &RegistrySource,
            versions: &RegistryVersions,
            locked: &RegistryRatchets,
            previous_sequence_state: RegistrySequencePreviousState,
            project_dir: &Path,
        ) -> Result<Self, String> {
            enum SequenceValidation {
                Accepted(RegistrySequenceTransition),
                Refused(RegistryRefusals),
            }

            let source_key = source.source_key();
            let target = ProviderRefusalTarget::new(source_key.as_str(), project_dir);
            let valid_until_present = versions.valid_until.is_some();

            let sequence_validation = match (previous_sequence_state, versions.sequence) {
                (
                    RegistrySequencePreviousState::FirstContact
                    | RegistrySequencePreviousState::ResetPending,
                    None,
                ) => SequenceValidation::Accepted(RegistrySequenceTransition::StillUnestablished),
                (RegistrySequencePreviousState::Unestablished, None) => {
                    SequenceValidation::Accepted(RegistrySequenceTransition::Unchanged)
                }
                (
                    RegistrySequencePreviousState::FirstContact
                    | RegistrySequencePreviousState::Unestablished
                    | RegistrySequencePreviousState::ResetPending,
                    Some(current),
                ) => SequenceValidation::Accepted(RegistrySequenceTransition::Established(current)),
                (RegistrySequencePreviousState::Established(_previous), None) => {
                    SequenceValidation::Refused(RegistryRefusals::new(
                        RegistryRefusal::SequenceFieldDisappeared {
                            target: target.clone(),
                        },
                    ))
                }
                (RegistrySequencePreviousState::Established(previous), Some(current))
                    if current < previous =>
                {
                    SequenceValidation::Refused(RegistryRefusals::new(
                        RegistryRefusal::SequenceRollback {
                            previous,
                            current,
                            target: target.clone(),
                        },
                    ))
                }
                (RegistrySequencePreviousState::Established(previous), Some(current))
                    if current.saturating_sub(previous) > MAX_SEQUENCE_FAST_FORWARD =>
                {
                    SequenceValidation::Refused(RegistryRefusals::new(
                        RegistryRefusal::SequenceFastForward {
                            anchor: previous,
                            current,
                            target: target.clone(),
                        },
                    ))
                }
                (RegistrySequencePreviousState::Established(previous), Some(current))
                    if current == previous =>
                {
                    SequenceValidation::Accepted(RegistrySequenceTransition::Unchanged)
                }
                (RegistrySequencePreviousState::Established(previous), Some(current)) => {
                    SequenceValidation::Accepted(RegistrySequenceTransition::Advanced {
                        previous,
                        current,
                    })
                }
            };
            let mut refusals = None;
            let stripped_versions = locked.yanked_versions.stripped_from(&versions.versions);
            if !stripped_versions.is_empty() {
                RegistryRefusals::insert(
                    &mut refusals,
                    RegistryRefusal::YankedFlagDisappeared {
                        versions: stripped_versions,
                        target: target.clone(),
                    },
                );
            }
            if locked.valid_until_present && !valid_until_present {
                RegistryRefusals::insert(
                    &mut refusals,
                    RegistryRefusal::ValidUntilFieldDisappeared { target },
                );
            }
            let sequence_transition = match (sequence_validation, refusals) {
                (SequenceValidation::Accepted(transition), None) => transition,
                (SequenceValidation::Accepted(_), Some(refusals))
                | (SequenceValidation::Refused(refusals), None) => {
                    return Err(refusals.to_string());
                }
                (SequenceValidation::Refused(mut sequence_refusals), Some(refusals)) => {
                    sequence_refusals.rest.push(refusals.first);
                    sequence_refusals.rest.extend(refusals.rest);
                    return Err(sequence_refusals.to_string());
                }
            };

            let valid_until = versions
                .valid_until
                .as_deref()
                .map(|raw_valid_until| {
                    OffsetDateTime::parse(raw_valid_until, &Rfc3339)
                        .map_err(|error| format!("Invalid registry valid_until timestamp: {error}"))
                })
                .transpose()?;
            if valid_until.is_some_and(|valid_until| valid_until < OffsetDateTime::now_utc()) {
                return Err(format!(
                    "registry versions listing valid_until is expired for {}/{}",
                    source.namespace(),
                    source.name()
                ));
            }

            let sequence = versions
                .sequence
                .map(RegistrySequence::Present)
                .unwrap_or(RegistrySequence::Absent);
            let yanked_versions =
                YankedRegistryVersions::default().with_observed(&versions.versions);
            let has_observations =
                versions.sequence.is_some() || valid_until_present || !yanked_versions.is_empty();
            let observations = has_observations.then_some(RegistryRatchets {
                sequence: sequence.clone(),
                valid_until_present,
                yanked_versions,
                signature: RegistrySignatureProtection::NotRequired,
                transparency_log_present: false,
            });
            Ok(Self {
                observations,
                sequence: ValidatedRegistrySequence {
                    sequence,
                    transition: sequence_transition,
                },
            })
        }

        pub(super) fn into_parts(self) -> (Option<RegistryRatchets>, ValidatedRegistrySequence) {
            (self.observations, self.sequence)
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn source() -> RegistrySource {
            let ProviderSource::Remote(RemoteSource::Registry(source)) =
                "carina-rs/aws".parse::<ProviderSource>().unwrap()
            else {
                panic!("expected registry source")
            };
            source
        }

        fn validate_sequence(
            previous: RegistrySequencePreviousState,
            sequence: Option<u64>,
        ) -> Result<ValidatedRegistryListing, String> {
            ValidatedRegistryListing::validate(
                &source(),
                &RegistryVersions {
                    sequence,
                    valid_until: None,
                    versions: Vec::new(),
                },
                &RegistryRatchets::default(),
                previous,
                Path::new("."),
            )
        }

        #[test]
        fn registry_sequence_transition_table_is_exhaustive() {
            for (previous, listing, expected) in [
                (
                    RegistrySequencePreviousState::FirstContact,
                    None,
                    RegistrySequenceTransition::StillUnestablished,
                ),
                (
                    RegistrySequencePreviousState::FirstContact,
                    Some(7),
                    RegistrySequenceTransition::Established(7),
                ),
                (
                    RegistrySequencePreviousState::Unestablished,
                    None,
                    RegistrySequenceTransition::Unchanged,
                ),
                (
                    RegistrySequencePreviousState::Unestablished,
                    Some(7),
                    RegistrySequenceTransition::Established(7),
                ),
                (
                    RegistrySequencePreviousState::ResetPending,
                    None,
                    RegistrySequenceTransition::StillUnestablished,
                ),
                (
                    RegistrySequencePreviousState::ResetPending,
                    Some(7),
                    RegistrySequenceTransition::Established(7),
                ),
                (
                    RegistrySequencePreviousState::Established(7),
                    Some(7),
                    RegistrySequenceTransition::Unchanged,
                ),
                (
                    RegistrySequencePreviousState::Established(5),
                    Some(7),
                    RegistrySequenceTransition::Advanced {
                        previous: 5,
                        current: 7,
                    },
                ),
            ] {
                let transition = validate_sequence(previous, listing)
                    .unwrap()
                    .sequence
                    .transition;
                assert_eq!(transition, expected, "{previous:?} + {listing:?}");
            }

            for (previous, listing, expected_error) in [
                (
                    RegistrySequencePreviousState::Established(7),
                    None,
                    "registry sequence field disappeared",
                ),
                (
                    RegistrySequencePreviousState::Established(7),
                    Some(6),
                    "registry sequence rollback",
                ),
                (
                    RegistrySequencePreviousState::Established(7),
                    Some(7 + MAX_SEQUENCE_FAST_FORWARD + 1),
                    "registry sequence fast-forward",
                ),
            ] {
                let error = validate_sequence(previous, listing)
                    .expect_err("the established-anchor transition must be refused");
                assert!(
                    error.contains(expected_error),
                    "{previous:?} + {listing:?}: {error}"
                );
            }
        }

        #[test]
        fn reset_pending_with_sequence_is_announced_once_then_silent() {
            let first = validate_sequence(RegistrySequencePreviousState::ResetPending, Some(7))
                .unwrap()
                .sequence;
            let (anchor, notice) = first.into_anchor_and_notice(&source().source_key());
            assert_eq!(anchor, RegistrySequenceAnchor::Established(7));
            assert_eq!(
                notice.unwrap().to_string(),
                "carina: established registry sequence anchor for carina-rs/aws: 7"
            );

            let second = validate_sequence(anchor.into_previous_state(), Some(7))
                .unwrap()
                .sequence;
            let (anchor, notice) = second.into_anchor_and_notice(&source().source_key());
            assert_eq!(anchor, RegistrySequenceAnchor::Established(7));
            assert!(notice.is_none());
        }

        #[test]
        fn reset_pending_without_sequence_is_announced_once_then_silent() {
            let first = validate_sequence(RegistrySequencePreviousState::ResetPending, None)
                .unwrap()
                .sequence;
            let (anchor, notice) = first.into_anchor_and_notice(&source().source_key());
            assert_eq!(anchor, RegistrySequenceAnchor::Unestablished);
            assert_eq!(
                notice.unwrap().to_string(),
                "carina: registry listing for carina-rs/aws has no sequence; no reference point established"
            );

            let second = validate_sequence(anchor.into_previous_state(), None)
                .unwrap()
                .sequence;
            let (anchor, notice) = second.into_anchor_and_notice(&source().source_key());
            assert_eq!(anchor, RegistrySequenceAnchor::Unestablished);
            assert!(notice.is_none());
        }
    }
}

pub(crate) use registry_listing_validation::RegistrySequenceNotice;
use registry_listing_validation::{ValidatedRegistryListing, ValidatedRegistrySequence};

mod registry_version_candidates {
    use std::collections::HashSet;

    use super::{RegistryVersion, Version};

    /// Parsed registry versions that are structurally safe to select.
    pub(super) struct SelectableRegistryVersions {
        versions: Vec<SelectableRegistryVersion>,
        yanked_versions: Vec<Version>,
    }

    struct SelectableRegistryVersion(Version);

    impl SelectableRegistryVersion {
        fn from_listing(
            entry: &RegistryVersion,
            yanked_version_names: &HashSet<&str>,
        ) -> Option<Self> {
            if entry.yanked || yanked_version_names.contains(entry.version.as_str()) {
                return None;
            }
            Version::parse(&entry.version).ok().map(Self)
        }
    }

    impl SelectableRegistryVersions {
        pub(super) fn from_listing(entries: &[RegistryVersion]) -> Self {
            let yanked_version_names: HashSet<&str> = entries
                .iter()
                .filter(|entry| entry.yanked)
                .map(|entry| entry.version.as_str())
                .collect();
            Self {
                versions: entries
                    .iter()
                    .filter_map(|entry| {
                        SelectableRegistryVersion::from_listing(entry, &yanked_version_names)
                    })
                    .collect(),
                yanked_versions: yanked_version_names
                    .into_iter()
                    .filter_map(|version| Version::parse(version).ok())
                    .collect(),
            }
        }

        pub(super) fn iter(&self) -> impl Iterator<Item = &Version> {
            self.versions.iter().map(|version| &version.0)
        }

        pub(super) fn yanked_matching(
            &self,
            mut predicate: impl FnMut(&Version) -> bool,
        ) -> Vec<String> {
            let mut versions: Vec<Version> = self
                .yanked_versions
                .iter()
                .filter(|version| predicate(version))
                .cloned()
                .collect();
            versions.sort_by(|left, right| right.cmp(left));
            versions.dedup();
            versions
                .into_iter()
                .map(|version| version.to_string())
                .collect()
        }
    }
}

use registry_version_candidates::SelectableRegistryVersions;

#[derive(Debug, Deserialize)]
struct RegistryDownload {
    download_url: String,
    shasum: String,
    #[serde(default, deserialize_with = "deserialize_registry_signature")]
    signature: Option<RegistrySignature>,
    #[serde(default)]
    transparency_log: Option<serde_json::Value>,
}

#[derive(Debug, Deserialize)]
struct RegistryRevisionDownload {
    version: String,
    #[serde(flatten)]
    download: RegistryDownload,
}

#[derive(Debug)]
struct RegistrySignature {
    r#type: String,
    bundle_url: String,
}

#[derive(Deserialize)]
struct RegistrySignatureWire {
    r#type: String,
    #[serde(rename = "certificate_identity")]
    _certificate_identity: String,
    #[serde(rename = "certificate_oidc_issuer")]
    _certificate_oidc_issuer: String,
    bundle_url: String,
}

impl From<RegistrySignatureWire> for RegistrySignature {
    fn from(value: RegistrySignatureWire) -> Self {
        let RegistrySignatureWire {
            r#type,
            _certificate_identity: _,
            _certificate_oidc_issuer: _,
            bundle_url,
        } = value;
        Self { r#type, bundle_url }
    }
}

fn deserialize_registry_signature<'de, D>(
    deserializer: D,
) -> Result<Option<RegistrySignature>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    RegistrySignatureWire::deserialize(deserializer)
        .map(Into::into)
        .map(Some)
        .map_err(|error| {
            serde::de::Error::custom(signing::verification_failure(format!(
                "malformed registry signature block: {error}"
            )))
        })
}

fn canonical_lock_source(source: &str) -> String {
    source
        .parse::<ProviderSource>()
        .map(|source| source.to_string())
        .unwrap_or_else(|_| source.to_string())
}

fn fetch_json<T: for<'de> Deserialize<'de>, H: RegistryHttp>(
    http: &H,
    url: &RegistryResourceUrl,
) -> Result<T, String> {
    let body = match http.get(RegistryHttpRequest::Resource(url))? {
        HttpResponse::Success { body } => body,
        HttpResponse::Failure { status } => {
            return Err(format!(
                "Registry request failed with status {status}: {}",
                url.as_str()
            ));
        }
    };
    let parsed = serde_json::from_slice(&body)
        .map_err(|e| format!("Failed to parse registry JSON from {}: {e}", url.as_str()))?;
    Ok(parsed)
}

fn fetch_discovery_json<T: for<'de> Deserialize<'de>, H: RegistryHttp>(
    http: &H,
    url: &str,
) -> Result<T, String> {
    let body = match http.get(RegistryHttpRequest::Discovery(url))? {
        HttpResponse::Success { body } => body,
        HttpResponse::Failure { status } if (300..400).contains(&status) => {
            return Err(format!(
                "Registry discovery fetch failed: redirect status {status} from {url}"
            ));
        }
        HttpResponse::Failure { status } => {
            return Err(format!(
                "Registry discovery fetch failed with status {status}: {url}"
            ));
        }
    };
    serde_json::from_slice(&body)
        .map_err(|e| format!("Failed to parse registry JSON from {url}: {e}"))
}

fn join_registry_url(base: &str, path: &str) -> String {
    format!("{}{}", base.trim_end_matches('/'), path)
}

fn same_consumed_discovery_values(
    left: &RegistryDiscoveryPin,
    right: &RegistryDiscoveryPin,
) -> bool {
    left.consumed_values() == right.consumed_values()
}

fn resolve_registry<H: RegistryHttp>(
    source: &RegistrySource,
    existing_host: Option<&RegistryHostLock>,
    project_dir: &Path,
    http: &H,
) -> Result<ResolvedRegistry, String> {
    let existing_discovery = match existing_host {
        Some(host) => Some(host.authorized_discovery().map_err(|_| {
            RegistryRefusal::DiscoveryMigrationAuthorizationRequired {
                target: HostRefusalTarget::new(source.hostname(), project_dir),
            }
            .to_string()
        })?),
        None => None,
    };
    let discovery_url = registry_discovery_url(source.hostname())?;
    let discovery: DiscoveryDocument = fetch_discovery_json(http, discovery_url.as_str())?;
    let api_base_url = resolve_api_base_url(&discovery_url, &discovery.providers_v1)?;
    let additional = existing_discovery
        .as_ref()
        .map(AuthorizedRegistryDiscoveryState::additional_values)
        .cloned()
        .unwrap_or_default();
    let discovery_pin = RegistryDiscoveryPin {
        api_base_url,
        additional,
    };
    if let Some(existing_pin) = existing_discovery
        .as_ref()
        .and_then(AuthorizedRegistryDiscoveryState::pin)
        && !same_consumed_discovery_values(existing_pin, &discovery_pin)
    {
        let host = source.hostname();
        return Err(RegistryRefusal::DiscoveryPinMismatch {
            pinned: existing_pin.api_base_url().to_string(),
            resolved: discovery_pin.api_base_url().to_string(),
            target: HostRefusalTarget::new(host, project_dir),
        }
        .to_string());
    }
    Ok(ResolvedRegistry {
        hostname: source.hostname().to_string(),
        discovery_pin,
    })
}

fn registry_discovery_url(hostname: &str) -> Result<url::Url, String> {
    let mut discovery_url = url::Url::parse(&format!("https://{hostname}/")).map_err(|error| {
        format!("invalid registry hostname: expected a host with optional port: {error}")
    })?;
    if !discovery_url.username().is_empty()
        || discovery_url.password().is_some()
        || discovery_url.path() != "/"
        || discovery_url.query().is_some()
        || discovery_url.fragment().is_some()
    {
        return Err(
            "invalid registry hostname: expected a host with optional port and no URL components"
                .into(),
        );
    }
    discovery_url.set_path(REGISTRY_DISCOVERY_PATH);
    Ok(discovery_url)
}

fn resolve_api_base_url(discovery_url: &url::Url, providers_v1: &str) -> Result<String, String> {
    let api_base_url = discovery_url.join(providers_v1).map_err(|error| {
        format!("invalid registry discovery providers.v1 reference {providers_v1:?}: {error}")
    })?;
    if !is_absolute_https_url(&api_base_url) {
        return Err(format!(
            "registry discovery providers.v1 must use HTTPS: {providers_v1}"
        ));
    }
    if !api_base_url.username().is_empty() || api_base_url.password().is_some() {
        return Err("registry discovery providers.v1 API base must not contain userinfo".into());
    }
    if api_base_url.origin() != discovery_url.origin() {
        return Err(format!(
            "registry discovery returned cross-origin providers.v1: {providers_v1}"
        ));
    }
    if api_base_url.path() == discovery_url.path() {
        return Err(format!(
            "registry discovery providers.v1 must not resolve to the discovery document: {providers_v1:?}"
        ));
    }
    if api_base_url.query().is_some() || api_base_url.fragment().is_some() {
        return Err(
            "registry discovery providers.v1 API base must not contain a query or fragment".into(),
        );
    }
    Ok(ensure_trailing_slash(api_base_url).into())
}

fn validate_persisted_api_base_url(value: &str) -> Result<(), RegistryDiscoveryPinError> {
    let api_base_url =
        url::Url::parse(value).map_err(|source| RegistryDiscoveryPinError::InvalidApiBaseUrl {
            value: value.into(),
            source: Some(source),
        })?;
    if !is_absolute_https_url(&api_base_url) {
        return Err(RegistryDiscoveryPinError::InvalidApiBaseUrl {
            value: value.into(),
            source: None,
        });
    }
    Ok(())
}

fn is_absolute_https_url(url: &url::Url) -> bool {
    url.scheme() == "https" && url.has_host() && !url.cannot_be_a_base()
}

fn ensure_trailing_slash(mut url: url::Url) -> url::Url {
    if !url.path().ends_with('/') {
        let mut path = url.path().to_owned();
        path.push('/');
        url.set_path(&path);
    }
    url
}

struct RecordedRegistryListing {
    versions: RegistryVersions,
    validated_sequence: ValidatedRegistrySequence,
}

fn fetch_registry_versions<H: RegistryHttp>(
    registry: &ResolvedRegistry,
    source: &RegistrySource,
    source_key: &RemoteSourceKey,
    lock_file: &mut PersistentLockFile<'_, '_>,
    http: &H,
) -> Result<RecordedRegistryListing, String> {
    let url = join_registry_url(
        registry.api_base_url(),
        &format!("/{}/{}/versions", source.namespace(), source.name()),
    );
    let url = parse_registry_resource_url(&url, "registry versions URL")?;
    let versions: RegistryVersions = fetch_json(http, &url)?;
    let validated_sequence =
        lock_file.validate_and_record_registry_listing(source, source_key, &versions)?;
    Ok(RecordedRegistryListing {
        versions,
        validated_sequence,
    })
}

fn select_registry_version(
    versions: &SelectableRegistryVersions,
    provider_name: &str,
    constraint: Option<&VersionConstraint>,
) -> Result<String, String> {
    match constraint {
        Some(constraint) => {
            let mut candidates: Vec<&Version> = versions
                .iter()
                .filter(|version| constraint.req.matches(version))
                .collect();
            candidates.sort_by(|a, b| b.cmp(a));
            candidates
                .into_iter()
                .next()
                .map(|version| version.to_string())
                .ok_or_else(|| {
                    registry_selection_error(
                        format!(
                            "No release of '{}' matches constraint '{}'",
                            provider_name, constraint.raw
                        ),
                        versions.yanked_matching(|version| constraint.req.matches(version)),
                    )
                })
        }
        None => versions
            .iter()
            .max()
            .map(|version| version.to_string())
            .ok_or_else(|| {
                registry_selection_error(
                    format!("No versions found for provider '{provider_name}'"),
                    versions.yanked_matching(|_| true),
                )
            }),
    }
}

fn registry_selection_error(message: String, yanked_versions: Vec<String>) -> String {
    if yanked_versions.is_empty() {
        message
    } else {
        format!(
            "{message}; yanked versions matching this request were skipped: {}",
            yanked_versions.join(", ")
        )
    }
}

fn fetch_registry_download<H: RegistryHttp>(
    registry: &ResolvedRegistry,
    source: &RegistrySource,
    version: &str,
    http: &H,
) -> Result<RegistryDownload, String> {
    let url = join_registry_url(
        registry.api_base_url(),
        &format!(
            "/{}/{}/{version}/download",
            source.namespace(),
            source.name()
        ),
    );
    let url = parse_registry_resource_url(&url, "registry download metadata URL")?;
    let download: RegistryDownload = fetch_json(http, &url)?;
    Ok(download)
}

fn fetch_registry_revision_download<H: RegistryHttp>(
    registry: &ResolvedRegistry,
    source: &RegistrySource,
    revision: &str,
    http: &H,
) -> Result<RegistryRevisionDownload, String> {
    let mut url = url::Url::parse(registry.api_base_url())
        .map_err(|error| format!("Invalid registry API base URL: {error}"))?;
    {
        let mut segments = url
            .path_segments_mut()
            .map_err(|_| "registry API base URL cannot accept path segments".to_string())?;
        segments.pop_if_empty();
        segments.extend([
            source.namespace(),
            source.name(),
            "revisions",
            revision,
            "download",
        ]);
    }
    let url = parse_registry_resource_url(url.as_str(), "registry revision download metadata URL")?;
    fetch_json(http, &url)
}

fn branch_build_matches(version: &Version, branch: &str) -> bool {
    if !is_zero_prerelease(version) {
        return false;
    }

    let mut version_identifiers = version.pre.as_str().split('.');
    for branch_identifier in branch.split('.') {
        if branch_identifier.is_empty() || version_identifiers.next() != Some(branch_identifier) {
            return false;
        }
    }

    version_identifiers.next().is_some_and(is_numeric)
}

fn is_zero_prerelease(version: &Version) -> bool {
    version.major == 0 && version.minor == 0 && version.patch == 0 && !version.pre.is_empty()
}

fn is_numeric(identifier: &str) -> bool {
    !identifier.is_empty() && identifier.bytes().all(|byte| byte.is_ascii_digit())
}

fn eligible_commit_sha(revision: &str) -> bool {
    revision.len() >= 7 && revision.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn listed_stable_release_for_tag<'a>(
    revision: &str,
    listing: &'a RegistryVersions,
) -> Option<&'a str> {
    let version = revision.strip_prefix('v')?;
    let parsed = Version::parse(version).ok()?;
    if !parsed.pre.is_empty() {
        return None;
    }
    listing
        .versions
        .iter()
        .find(|entry| entry.version == version)
        .map(|entry| entry.version.as_str())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RegistryRevisionSelection {
    Locked,
    Resolved,
}

fn bind_registry_revision_with_selection(
    revision: &str,
    version: &ListedVersion,
    listing: &RegistryVersions,
    identity: Option<&signing::VerifiedSignerIdentity>,
    selection: RegistryRevisionSelection,
) -> Result<(), String> {
    if let Some(identity) = identity {
        let branch_matches = branch_build_matches(&version.parsed, revision)
            && identity.source_ref() == format!("refs/heads/{revision}");
        let release_version = listed_stable_release_for_tag(revision, listing);
        let tag_matches = identity.source_ref() == format!("refs/tags/{revision}")
            && release_version.is_none_or(|release| release == version.raw);
        let sha_matches = eligible_commit_sha(revision)
            && identity.repository_digest().is_some_and(|digest| {
                digest
                    .get(..revision.len())
                    .is_some_and(|prefix| prefix.eq_ignore_ascii_case(revision))
            });
        if branch_matches || tag_matches || sha_matches {
            return Ok(());
        }
        return Err(format!(
            "verified certificate does not bind registry revision {revision:?} to version {}",
            version.raw
        ));
    }

    if eligible_commit_sha(revision) {
        return Err(format!(
            "unsigned registry revision {revision:?} looks like a commit SHA and cannot be bound without a certificate"
        ));
    }
    let branch_shaped_version = branch_build_matches(&version.parsed, revision);
    if branch_shaped_version {
        if selection == RegistryRevisionSelection::Locked {
            return Ok(());
        }
        let highest = listing
            .versions
            .iter()
            .filter(|entry| !entry.yanked)
            .filter_map(|entry| {
                let parsed = Version::parse(&entry.version).ok()?;
                branch_build_matches(&parsed, revision).then_some((parsed, &entry.version))
            })
            .max_by(|(left, _), (right, _)| left.cmp(right))
            .map(|(_, raw)| raw.as_str());
        if highest == Some(version.raw.as_str()) {
            return Ok(());
        }
        return Err(format!(
            "unsigned registry branch revision {revision:?} did not return its highest listed build"
        ));
    }
    if let Some(release) = listed_stable_release_for_tag(revision, listing) {
        if release == version.raw {
            return Ok(());
        }
    } else {
        // With no certificate, a non-release tag has no certificate-derived
        // constraint beyond the already-enforced non-yanked listing membership.
        return Ok(());
    }
    Err(format!(
        "unsigned registry revision {revision:?} does not bind to returned version {}",
        version.raw
    ))
}

#[cfg(test)]
fn bind_registry_revision(
    revision: &str,
    version: &ListedVersion,
    listing: &RegistryVersions,
    identity: Option<&signing::VerifiedSignerIdentity>,
) -> Result<(), String> {
    bind_registry_revision_with_selection(
        revision,
        version,
        listing,
        identity,
        RegistryRevisionSelection::Resolved,
    )
}

enum LegacyFetch<T> {
    Available(T),
    Unavailable,
}

fn fetch_registry_download_for_legacy_conversion<H: RegistryHttp>(
    registry: &ResolvedRegistry,
    source: &RegistrySource,
    version: &str,
    http: &H,
) -> Result<LegacyFetch<RegistryDownload>, String> {
    let url = join_registry_url(
        registry.api_base_url(),
        &format!(
            "/{}/{}/{version}/download",
            source.namespace(),
            source.name()
        ),
    );
    let url = parse_registry_resource_url(&url, "registry download metadata URL")?;
    let body = match http.get(RegistryHttpRequest::Resource(&url)) {
        Ok(HttpResponse::Success { body }) => body,
        Ok(HttpResponse::Failure { status: 404 }) | Err(_) => {
            return Ok(LegacyFetch::Unavailable);
        }
        Ok(HttpResponse::Failure { status }) => {
            return Err(format!(
                "cannot fetch legacy-pinned version metadata from {} (HTTP {status})",
                url.as_str()
            ));
        }
    };
    serde_json::from_slice(&body)
        .map(LegacyFetch::Available)
        .map_err(|error| {
            format!(
                "Failed to parse registry JSON from {}: {error}",
                url.as_str()
            )
        })
}

fn fetch_signature_bundle_for_legacy_conversion<H: RegistryHttp>(
    signature: &RegistrySignature,
    http: &H,
) -> Result<LegacyFetch<Vec<u8>>, String> {
    let bundle_url = parse_registry_resource_url(&signature.bundle_url, "signature bundle URL")
        .map_err(signing::verification_failure)?;
    let body = match http.get(RegistryHttpRequest::Resource(&bundle_url)) {
        Ok(HttpResponse::Success { body }) => body,
        Ok(HttpResponse::Failure { status: 404 }) | Err(_) => {
            return Ok(LegacyFetch::Unavailable);
        }
        Ok(HttpResponse::Failure { status }) => {
            return Err(signing::verification_failure(format!(
                "cannot fetch legacy-pinned signature bundle from {} (HTTP {status})",
                signature.bundle_url
            )));
        }
    };
    if body.len() > MAX_SIGNATURE_BUNDLE_BYTES {
        return Err(signing::verification_failure(format!(
            "signature bundle from {} is {} bytes, exceeding the {MAX_SIGNATURE_BUNDLE_BYTES}-byte limit",
            signature.bundle_url,
            body.len()
        )));
    }
    Ok(LegacyFetch::Available(body))
}

fn convert_obtainable_legacy_signer_pin<H: RegistryHttp>(
    user_dirs: &UserDirs,
    registry: &ResolvedRegistry,
    source: &RegistrySource,
    source_key: &RemoteSourceKey,
    candidate_version: Option<&str>,
    lock_file: &mut PersistentLockFile<'_, '_>,
    http: &H,
) -> Result<(), String> {
    let Some((locked_name, locked_version, locked_sha256, legacy_pin)) = lock_file
        .lock_file()
        .find_by_source_key(source_key)
        .and_then(|entry| {
            let locked_version = entry.kind.resolved_version()?;
            let registry = entry.registry.as_ref()?;
            let RegistrySignatureProtection::Required(SignerPinState::Legacy(pin)) =
                &registry.signature
            else {
                return None;
            };
            Some((
                entry.name.clone(),
                locked_version.to_string(),
                entry.sha256.clone(),
                pin.clone(),
            ))
        })
    else {
        return Ok(());
    };
    if candidate_version == Some(locked_version.as_str()) {
        return Ok(());
    }

    let download = match fetch_registry_download_for_legacy_conversion(
        registry,
        source,
        &locked_version,
        http,
    )? {
        LegacyFetch::Available(download) => download,
        LegacyFetch::Unavailable => return Ok(()),
    };
    if download.shasum != locked_sha256 {
        return Err(RegistryRefusal::LegacyShasumPinMismatch {
            version: locked_version.clone(),
            locked: locked_sha256.clone(),
            resolved: download.shasum.clone(),
            target: ProviderRefusalTarget::new(
                source_key.as_str(),
                lock_file.install_lock().project_dir(),
            ),
        }
        .to_string());
    }
    let signature = download.signature.as_ref().ok_or_else(|| {
        RegistryRefusal::LegacySignatureMissing {
            version: locked_version.clone(),
            target: ProviderRefusalTarget::new(
                source_key.as_str(),
                lock_file.install_lock().project_dir(),
            ),
        }
        .to_string()
    })?;
    signing::ensure_supported_signature_type(&signature.r#type)?;
    let download_url = parse_registry_resource_url(
        &download.download_url,
        "legacy-pinned registry download URL",
    )?;
    let artifact_context =
        format!("legacy-pinned registry provider '{locked_name}' ({source_key}@{locked_version})");
    let artifact = match obtain_registry_artifact(
        RegistryArtifactRequest {
            user_dirs,
            install_lock: lock_file.install_lock(),
            source: source_key,
            version: &locked_version,
            provider_name: &locked_name,
            download_url: &download_url,
            expected_shasum: &locked_sha256,
            context: &artifact_context,
        },
        http,
    ) {
        Ok(artifact) => artifact,
        Err(RegistryArtifactError::Unavailable(_)) => return Ok(()),
        Err(RegistryArtifactError::Invalid(error)) => {
            return Err(format!(
                "legacy-pinned version {source_key}@{locked_version}: {error}"
            ));
        }
    };
    let bundle = match fetch_signature_bundle_for_legacy_conversion(signature, http)? {
        LegacyFetch::Available(bundle) => bundle,
        LegacyFetch::Unavailable => return Ok(()),
    };
    let version = ListedVersion::parse(&locked_version)?;
    let expected_signer = SignerPinState::Legacy(legacy_pin);
    let (_, acceptance) = match verify_and_decide_signer(
        artifact.digest(),
        &bundle,
        &expected_signer,
        &version,
        source_key.as_str(),
        lock_file.install_lock().project_dir(),
        http,
    ) {
        Ok(verified) => verified,
        Err(error) => {
            artifact.remove_if_cached();
            return Err(format!(
                "legacy-pinned version {source_key}@{locked_version}: {error}"
            ));
        }
    };
    debug_assert_eq!(acceptance.transition, SignerTransition::LegacyConverted);
    let artifact_path = artifact.path().as_path().to_path_buf();
    artifact.publish().map_err(|error| {
        format!(
            "legacy-pinned version {source_key}@{locked_version}: Failed to publish provider artifact {}: {error}",
            artifact_path.display()
        )
    })?;
    lock_file.record_signer_acceptance(source_key, acceptance)?;
    Ok(())
}

/// Resolve the global cache path for a WASM provider.
fn global_cache_path_wasm(
    user_dirs: &carina_core::UserDirs,
    source: &RemoteSourceKey,
    version: &str,
) -> Option<GlobalArtifactPath> {
    global_cache_artifact_path(
        user_dirs,
        PathBuf::from(source.as_str())
            .join(version)
            .join(format!("{}.wasm", source.artifact_name())),
    )
}

fn global_cache_path_github_release(
    user_dirs: &carina_core::UserDirs,
    source: &RemoteSourceKey,
    version: &Version,
) -> Option<GlobalArtifactPath> {
    global_cache_path_wasm(user_dirs, source, &version.to_string())
}

/// Resolve the cache path for a WASM provider component.
pub fn cache_path_wasm(base_dir: &Path, source: &RemoteSourceKey, version: &str) -> PathBuf {
    base_dir
        .join(".carina")
        .join("providers")
        .join(source.as_str())
        .join(version)
        .join(format!("{}.wasm", source.artifact_name()))
}

pub(crate) fn cache_path_github_release(
    base_dir: &Path,
    source: &RemoteSourceKey,
    version: &Version,
) -> PathBuf {
    cache_path_wasm(base_dir, source, &version.to_string())
}

/// Compute SHA256 hex digest of a file.
pub fn sha256_file(path: &Path) -> io::Result<String> {
    Ok(sha256_digest_hex(&sha256_file_digest(path)?))
}

fn sha256_file_digest(path: &Path) -> io::Result<Sha256> {
    let mut file = fs::File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 8192];
    loop {
        let n = file.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        hasher.update(&buffer[..n]);
    }
    Ok(hasher)
}

fn sha256_digest_hex(digest: &Sha256) -> String {
    format!("{:x}", digest.clone().finalize())
}

fn hash_and_check(
    wasm_path: &Path,
    expected_shasum: &str,
    context: &str,
    project_dir: &Path,
) -> Result<Sha256, String> {
    let artifact_digest = sha256_file_digest(wasm_path)
        .map_err(|error| format!("Failed to hash WASM binary: {error}"))?;
    let actual_hash = sha256_digest_hex(&artifact_digest);
    if actual_hash != expected_shasum {
        return Err(format!(
            "SHA256 mismatch for {context}. Expected registry shasum {expected_shasum}, got {actual_hash}. Re-run `{}` to re-download.",
            ProjectCommand::new("init", project_dir)
        ));
    }
    Ok(artifact_digest)
}

enum RegistryArtifactState<'a> {
    Cached {
        install_lock: &'a ProviderInstallLock,
        path: WasmArtifactPath,
    },
    Staged {
        artifact: StagedArtifact<'a>,
        path: WasmArtifactPath,
    },
}

struct VerifiedRegistryArtifact<'a> {
    state: RegistryArtifactState<'a>,
    digest: Sha256,
}

impl fmt::Debug for VerifiedRegistryArtifact<'_> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (state, path) = match &self.state {
            RegistryArtifactState::Cached { path, .. } => ("cached", path),
            RegistryArtifactState::Staged { path, .. } => ("staged", path),
        };
        formatter
            .debug_struct("VerifiedRegistryArtifact")
            .field("state", &state)
            .field("path", &path)
            .field("digest", &sha256_digest_hex(&self.digest))
            .finish()
    }
}

impl VerifiedRegistryArtifact<'_> {
    fn digest(&self) -> Sha256 {
        self.digest.clone()
    }

    fn path(&self) -> &WasmArtifactPath {
        match &self.state {
            RegistryArtifactState::Cached { path, .. }
            | RegistryArtifactState::Staged { path, .. } => path,
        }
    }

    fn is_origin_download(&self) -> bool {
        matches!(&self.state, RegistryArtifactState::Staged { .. })
    }

    fn remove_if_cached(self) {
        if let RegistryArtifactState::Cached { install_lock, path } = self.state {
            let _ = install_lock.remove_project_artifact(&path);
        }
    }

    fn publish(self) -> io::Result<WasmArtifactPath> {
        match self.state {
            RegistryArtifactState::Cached { path, .. } => Ok(path),
            RegistryArtifactState::Staged { artifact, path } => {
                artifact.publish()?;
                Ok(path)
            }
        }
    }
}

enum RegistryArtifactError {
    Unavailable(String),
    Invalid(String),
}

impl fmt::Display for RegistryArtifactError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unavailable(message) | Self::Invalid(message) => formatter.write_str(message),
        }
    }
}

struct RegistryArtifactRequest<'lock, 'request> {
    user_dirs: &'request UserDirs,
    install_lock: &'lock ProviderInstallLock,
    source: &'request RemoteSourceKey,
    version: &'request str,
    provider_name: &'request str,
    download_url: &'request RegistryResourceUrl,
    expected_shasum: &'request str,
    context: &'request str,
}

fn obtain_registry_artifact<'lock, H: RegistryHttp>(
    request: RegistryArtifactRequest<'lock, '_>,
    http: &H,
) -> Result<VerifiedRegistryArtifact<'lock>, RegistryArtifactError> {
    let RegistryArtifactRequest {
        user_dirs,
        install_lock,
        source,
        version,
        provider_name,
        download_url,
        expected_shasum,
        context,
    } = request;
    let project_dir = install_lock.project_dir();
    let path = WasmArtifactPath::new(cache_path_wasm(project_dir, source, version), provider_name)
        .map_err(RegistryArtifactError::Invalid)?;
    let (state, digest) = if path.as_path().exists()
        && (!ProviderTrust::remote_source_is_allowlisted(source)
            || user_trust_record_exists(user_dirs, expected_shasum, source))
    {
        match hash_and_check(
            path.as_path(),
            expected_shasum,
            &format!("cached {context}"),
            project_dir,
        ) {
            Ok(digest) => (RegistryArtifactState::Cached { install_lock, path }, digest),
            Err(error) => {
                let _ = install_lock.remove_project_artifact(&path);
                return Err(RegistryArtifactError::Invalid(error));
            }
        }
    } else {
        let mut staged = StagedArtifact::for_project(install_lock, &path).map_err(|error| {
            RegistryArtifactError::Invalid(format!(
                "Failed to stage provider artifact {}: {error}",
                path.as_path().display()
            ))
        })?;
        if let Err(error) = http.download_into(download_url, &mut staged) {
            let message = error.to_string();
            return Err(if error.is_unavailable() {
                RegistryArtifactError::Unavailable(message)
            } else {
                RegistryArtifactError::Invalid(message)
            });
        }
        let digest = hash_and_check(staged.path(), expected_shasum, context, project_dir)
            .map_err(RegistryArtifactError::Invalid)?;
        (
            RegistryArtifactState::Staged {
                artifact: staged,
                path,
            },
            digest,
        )
    };
    Ok(VerifiedRegistryArtifact { state, digest })
}

fn verify_and_decide_signer<H: RegistryHttp>(
    artifact_digest: Sha256,
    bundle: &[u8],
    expected_signer: &SignerPinState,
    version: &ListedVersion,
    source: &str,
    project_dir: &Path,
    http: &H,
) -> Result<(signing::VerifiedSignerIdentity, SignerAcceptance), String> {
    let identity = signing::verify_artifact(artifact_digest, bundle)?;
    #[cfg(any(test, feature = "test-utils"))]
    let identity = http.fixture_signer_identity().unwrap_or(identity);
    #[cfg(not(any(test, feature = "test-utils")))]
    let _ = http;
    let acceptance = decide_signer(expected_signer, &identity, version).map_err(|error| {
        RegistryRefusal::from_signer_rejection(error, source, project_dir).to_string()
    })?;
    Ok((identity, acceptance))
}

fn record_verified_github_release_pin(
    lock_file: &mut LockFile,
    artifact: &VerifiedArtifact,
    pin: GithubReleaseArtifactPin,
    resolved: &ResolvedGithubRelease,
    name: &str,
) {
    lock_file.upsert(LockEntry {
        name: name.to_string(),
        source: artifact.source().to_string(),
        kind: LockEntryKind::GithubRelease {
            version: resolved.version().clone(),
            tag: resolved.tag().clone(),
            asset_id: resolved.asset_id(),
            constraint: pin.constraint,
        },
        sha256: artifact.sha256().to_string(),
        registry: None,
    });
}

struct VerifiedRegistryLockPin {
    existing_constraint: Option<String>,
    expected_signer: Option<SignerPinState>,
}

fn verify_registry_lock_pin(
    lock_file: &mut PersistentLockFile<'_, '_>,
    source_key: &RemoteSourceKey,
    version: &str,
    expected_shasum: &str,
    registry: &ResolvedRegistry,
    signature: Option<&RegistrySignature>,
    transparency_log_present: bool,
) -> Result<VerifiedRegistryLockPin, String> {
    let project_dir = lock_file.install_lock().project_dir().to_path_buf();
    let current_lock = lock_file.lock_file();
    let entry = current_lock.find_by_source_key(source_key);
    let existing_constraint = entry.and_then(|entry| match &entry.kind {
        LockEntryKind::Version {
            version: _,
            constraint,
        } => constraint.clone(),
        LockEntryKind::GithubRelease {
            version: _,
            tag: _,
            asset_id: _,
            constraint: _,
        }
        | LockEntryKind::Revision {
            revision: _,
            resolved_sha: _,
            artifact_id: _,
        }
        | LockEntryKind::RegistryRevision {
            revision: _,
            version: _,
        }
        | LockEntryKind::File => None,
    });
    if let Some(entry) = entry
        && entry.kind.resolved_version().as_deref() == Some(version)
        && entry.sha256 != expected_shasum
    {
        return Err(RegistryRefusal::ShasumPinMismatch {
            version: version.to_string(),
            locked: entry.sha256.clone(),
            resolved: expected_shasum.to_string(),
            target: ProviderRefusalTarget::new(source_key.as_str(), project_dir),
        }
        .to_string());
    }
    let locked_registry = entry.and_then(|entry| entry.registry.as_ref());
    if let Some(locked_registry) = locked_registry
        && locked_registry.resolved_hostname() != registry.hostname
    {
        return Err(RegistryRefusal::HostnamePinMismatch {
            locked: locked_registry.resolved_hostname().to_string(),
            resolved: registry.hostname.clone(),
            target: ProviderRefusalTarget::new(source_key.as_str(), project_dir),
        }
        .to_string());
    }
    let ratchets = current_lock
        .known_registry_ratchets(source_key.as_str())
        .map_err(|error| error.to_string())?;
    if ratchets.signature.is_required() && signature.is_none() {
        return Err(RegistryRefusal::SignatureFieldDisappeared {
            target: ProviderRefusalTarget::new(source_key.as_str(), project_dir),
        }
        .to_string());
    }
    let expected_signer = signature.map(|_| {
        ratchets
            .signature
            .pin_state()
            .cloned()
            .unwrap_or(SignerPinState::Unpinned)
    });
    if ratchets.transparency_log_present && !transparency_log_present {
        return Err(RegistryRefusal::TransparencyLogFieldDisappeared {
            target: ProviderRefusalTarget::new(source_key.as_str(), project_dir),
        }
        .to_string());
    }
    // Lock-pin validation is the presence observation's acceptance gate.
    // Persist both independent presence ratchets before later signature-type
    // and artifact checks; a failed signature must never make a later
    // unsigned response acceptable.
    lock_file.record_registry_signature_presence(source_key, signature.is_some())?;
    lock_file.record_registry_transparency_log_presence(source_key, transparency_log_present)?;
    Ok(VerifiedRegistryLockPin {
        existing_constraint,
        expected_signer,
    })
}

fn fetch_signature_bundle<H: RegistryHttp>(
    signature: &RegistrySignature,
    http: &H,
) -> Result<Vec<u8>, String> {
    let bundle_url = parse_registry_resource_url(&signature.bundle_url, "signature bundle URL")
        .map_err(signing::verification_failure)?;
    let response = http
        .get(RegistryHttpRequest::Resource(&bundle_url))
        .map_err(|error| {
        format!(
            "cannot fetch the signature bundle from {} ({error}); signature verification cannot proceed and has no override",
            signature.bundle_url
        )
    })?;
    let body = match response {
        HttpResponse::Success { body } => body,
        HttpResponse::Failure { status } => {
            return Err(format!(
                "cannot fetch the signature bundle from {} (HTTP {status}); signature verification cannot proceed and has no override",
                signature.bundle_url
            ));
        }
    };
    if body.len() > MAX_SIGNATURE_BUNDLE_BYTES {
        return Err(signing::verification_failure(format!(
            "signature bundle from {} is {} bytes, exceeding the {MAX_SIGNATURE_BUNDLE_BYTES}-byte limit",
            signature.bundle_url,
            body.len()
        )));
    }
    Ok(body)
}

fn resolve_registry_provider_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    source: &RegistrySource,
    source_key: &RemoteSourceKey,
    version: &str,
    name: &str,
    lock_file: &mut GuardedLockFile<'_>,
    http: &H,
) -> Result<WasmArtifactPath, String> {
    let install_lock = lock_file.install_lock();
    let project_dir = install_lock.project_dir();
    let existing_host = lock_file.registry_host_lock(source.hostname()).cloned();
    let registry = resolve_registry(source, existing_host.as_ref(), project_dir, http)?;
    let mut persistent_lock = PersistentLockFile::new(lock_file);
    let RecordedRegistryListing {
        versions,
        validated_sequence,
    } = fetch_registry_versions(&registry, source, source_key, &mut persistent_lock, http)?;
    convert_obtainable_legacy_signer_pin(
        user_dirs,
        &registry,
        source,
        source_key,
        Some(version),
        &mut persistent_lock,
        http,
    )?;
    let listed_version = require_listed_registry_version(
        &versions,
        version,
        source_key.as_str(),
        persistent_lock
            .lock_file()
            .find_by_source_key_and_version(source_key, version)
            .is_some(),
    )?;
    let download = fetch_registry_download(&registry, source, version, http)?;
    accept_registry_download_with_http(
        user_dirs,
        PendingRegistryDownload {
            source_key,
            version: listed_version,
            name,
            registry,
            validated_sequence,
            download,
            intent: RegistryDownloadIntent::Version,
        },
        &mut persistent_lock,
        http,
    )
}

fn resolve_registry_revision_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    source: &RegistrySource,
    revision: &str,
    name: &str,
    lock_file: &mut GuardedLockFile<'_>,
    mode: LockMode,
    http: &H,
) -> Result<WasmArtifactPath, String> {
    let install_lock = lock_file.install_lock();
    let project_dir = install_lock.project_dir();
    let source_key = source.source_key();
    let existing_host = lock_file.registry_host_lock(source.hostname()).cloned();
    let registry = resolve_registry(source, existing_host.as_ref(), project_dir, http)?;
    let mut persistent_lock = PersistentLockFile::new(lock_file);
    let RecordedRegistryListing {
        versions,
        validated_sequence,
    } = fetch_registry_versions(&registry, source, &source_key, &mut persistent_lock, http)?;
    let locked_version = if mode == LockMode::Upgrade {
        None
    } else {
        persistent_lock
            .lock_file()
            .find_by_source_key(&source_key)
            .and_then(|entry| match &entry.kind {
                LockEntryKind::RegistryRevision {
                    revision: locked_revision,
                    version,
                } if locked_revision == revision => Some(version.clone()),
                LockEntryKind::Version {
                    version: _,
                    constraint: _,
                }
                | LockEntryKind::GithubRelease {
                    version: _,
                    tag: _,
                    asset_id: _,
                    constraint: _,
                }
                | LockEntryKind::Revision {
                    revision: _,
                    resolved_sha: _,
                    artifact_id: _,
                }
                | LockEntryKind::RegistryRevision {
                    revision: _,
                    version: _,
                }
                | LockEntryKind::File => None,
            })
    };
    let (listed_version, download, selection) = if let Some(locked_version) = locked_version {
        convert_obtainable_legacy_signer_pin(
            user_dirs,
            &registry,
            source,
            &source_key,
            Some(&locked_version),
            &mut persistent_lock,
            http,
        )?;
        let listed_version =
            require_listed_registry_version(&versions, &locked_version, source_key.as_str(), true)?;
        let download = fetch_registry_download(&registry, source, &locked_version, http)?;
        (listed_version, download, RegistryRevisionSelection::Locked)
    } else {
        convert_obtainable_legacy_signer_pin(
            user_dirs,
            &registry,
            source,
            &source_key,
            None,
            &mut persistent_lock,
            http,
        )?;
        let response = fetch_registry_revision_download(&registry, source, revision, http)?;
        let listed_version = require_listed_registry_version(
            &versions,
            &response.version,
            source_key.as_str(),
            false,
        )?;
        (
            listed_version,
            response.download,
            RegistryRevisionSelection::Resolved,
        )
    };
    accept_registry_download_with_http(
        user_dirs,
        PendingRegistryDownload {
            source_key: &source_key,
            version: listed_version,
            name,
            registry,
            validated_sequence,
            download,
            intent: RegistryDownloadIntent::Revision {
                requested: revision,
                listing: &versions,
                selection,
            },
        },
        &mut persistent_lock,
        http,
    )
}

fn require_listed_registry_version(
    versions: &RegistryVersions,
    version: &str,
    source_key: &str,
    permit_locked_yanked: bool,
) -> Result<ListedVersion, String> {
    let entry = versions
        .versions
        .iter()
        .find(|entry| entry.version == version)
        .ok_or_else(|| {
            format!("Registry provider {source_key} does not contain version {version}")
        })?;
    if entry.yanked && !permit_locked_yanked {
        return Err(format!(
            "Registry provider {source_key} version {version} is yanked and cannot be newly pinned"
        ));
    }
    if entry.yanked {
        eprintln!(
            "carina: warning: registry provider {source_key}@{version} is yanked; continuing because carina-providers.lock pins this version"
        );
    }
    ListedVersion::parse(&entry.version)
}

enum RegistryDownloadIntent<'a> {
    Version,
    Revision {
        requested: &'a str,
        listing: &'a RegistryVersions,
        selection: RegistryRevisionSelection,
    },
}

struct PendingRegistryDownload<'a> {
    source_key: &'a RemoteSourceKey,
    version: ListedVersion,
    name: &'a str,
    registry: ResolvedRegistry,
    validated_sequence: ValidatedRegistrySequence,
    download: RegistryDownload,
    intent: RegistryDownloadIntent<'a>,
}

fn accept_registry_download_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    pending: PendingRegistryDownload<'_>,
    persistent_lock: &mut PersistentLockFile<'_, '_>,
    http: &H,
) -> Result<WasmArtifactPath, String> {
    let PendingRegistryDownload {
        source_key,
        version,
        name,
        registry,
        validated_sequence,
        download,
        intent,
    } = pending;
    let install_lock = persistent_lock.install_lock();
    let project_dir = install_lock.project_dir();
    let version_string = version.raw.as_str();
    let download_url =
        parse_registry_resource_url(&download.download_url, "registry download URL")?;
    let transparency_log_present = download.transparency_log.is_some();
    let VerifiedRegistryLockPin {
        existing_constraint,
        expected_signer,
    } = verify_registry_lock_pin(
        persistent_lock,
        source_key,
        version_string,
        &download.shasum,
        &registry,
        download.signature.as_ref(),
        transparency_log_present,
    )?;
    // Transparency-log presence is an independently accepted promotion, so
    // the pin check records it before this downstream signature-type gate.
    if let Some(signature) = &download.signature {
        signing::ensure_supported_signature_type(&signature.r#type)?;
    }
    let provider_context = format!("registry provider '{name}' ({source_key}@{version_string})");
    let signed = download.signature.as_ref().zip(expected_signer);

    let artifact = obtain_registry_artifact(
        RegistryArtifactRequest {
            user_dirs,
            install_lock,
            source: source_key,
            version: version_string,
            provider_name: name,
            download_url: &download_url,
            expected_shasum: &download.shasum,
            context: &provider_context,
        },
        http,
    )
    .map_err(|error| error.to_string())?;

    let verified_signature = match signed {
        Some((signature, expected_signer)) => {
            let bundle = fetch_signature_bundle(signature, http)
                .map_err(|error| format!("{provider_context}: {error}"))?;
            match verify_and_decide_signer(
                artifact.digest(),
                &bundle,
                &expected_signer,
                &version,
                source_key.as_str(),
                project_dir,
                http,
            ) {
                Ok(verified) => Some(verified),
                Err(error) => {
                    artifact.remove_if_cached();
                    return Err(format!("{provider_context}: {error}"));
                }
            }
        }
        None => None,
    };
    let origin_downloaded = artifact.is_origin_download();

    let kind = match intent {
        RegistryDownloadIntent::Version => LockEntryKind::Version {
            version: version.raw.clone(),
            constraint: existing_constraint,
        },
        RegistryDownloadIntent::Revision {
            requested,
            listing,
            selection,
        } => {
            if let Err(error) = bind_registry_revision_with_selection(
                requested,
                &version,
                listing,
                verified_signature.as_ref().map(|(identity, _)| identity),
                selection,
            ) {
                artifact.remove_if_cached();
                return Err(error);
            }
            LockEntryKind::RegistryRevision {
                revision: requested.to_string(),
                version: version.raw.clone(),
            }
        }
    };

    let artifact_path = artifact.path().as_path().to_path_buf();
    let artifact = artifact.publish().map_err(|error| {
        format!(
            "Failed to publish provider artifact {}: {error}",
            artifact_path.display()
        )
    })?;

    if let Some((_, acceptance)) = &verified_signature {
        let transition = acceptance.transition.clone();
        persistent_lock.record_signer_acceptance(source_key, acceptance.clone())?;
        if transition != SignerTransition::Unchanged {
            eprintln!("carina: updated verified signer pins for {source_key}: {transition:?}");
        }
    }

    let artifact_sha256 = download.shasum.clone();
    persistent_lock.upsert_registry_provider(RegistryProviderLockEntry {
        name: name.to_string(),
        source: source_key.clone(),
        kind,
        sha256: download.shasum,
        registry,
        validated_sequence,
    })?;
    // Registry discovery legitimately permits artifacts on a different host.
    // `obtain_registry_artifact` already matched the shasum; require the
    // unforgeable signer identity from verification before minting user trust.
    if origin_downloaded && let Some((verified_signer, acceptance)) = &verified_signature {
        let signer = RegistrySignatureProtection::Required(acceptance.next.clone());
        record_verified_registry_origin_download(
            user_dirs,
            source_key,
            download_url.as_str(),
            &artifact_sha256,
            &signer,
            verified_signer,
        )?;
    }
    Ok(artifact)
}

fn annotate_version_lock_entry(
    source: &RemoteSourceKey,
    version: &str,
    constraint: Option<&VersionConstraint>,
    lock_file: &mut LockFile,
) {
    if let Some(entry) = lock_file.provider.iter_mut().find(|entry| {
        LockFile::sources_match(&entry.source, source.as_str())
            && matches!(
                &entry.kind,
                LockEntryKind::Version {
                    version: locked_version,
                    constraint: _
                } if locked_version == version
            )
    }) && let LockEntryKind::Version {
        constraint: locked_constraint,
        ..
    } = &mut entry.kind
    {
        *locked_constraint = constraint.map(|constraint| constraint.raw.clone());
    }
}

fn annotate_github_release_lock_entry(
    source: &RemoteSourceKey,
    version: &Version,
    constraint: Option<&VersionConstraint>,
    lock_file: &mut LockFile,
) {
    if let Some(entry) = lock_file.provider.iter_mut().find(|entry| {
        LockFile::sources_match(&entry.source, source.as_str())
            && matches!(
                &entry.kind,
                LockEntryKind::GithubRelease {
                    version: locked_version,
                    tag: _,
                    asset_id: _,
                    constraint: _
                } if locked_version == version
            )
    }) && let LockEntryKind::GithubRelease {
        version: _,
        tag: _,
        asset_id: _,
        constraint: locked_constraint,
    } = &mut entry.kind
    {
        *locked_constraint = constraint.map(|constraint| constraint.raw.clone());
    }
}

/// A GitHub release selected from fresh API metadata, or release coordinates
/// restored from a typed lock entry that still require origin verification.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ResolvedGithubRelease {
    Verified(VerifiedReleaseAsset),
    Locked {
        version: Version,
        tag: ReleaseTag,
        asset_id: AssetId,
    },
}

impl ResolvedGithubRelease {
    fn from_selected_release(
        repo: RepoSlug,
        release: GithubRelease,
    ) -> Result<Self, ReleaseAssetVerificationError> {
        verify_fresh_release_asset(repo, release).map(Self::Verified)
    }

    fn from_lock_entry(version: Version, tag: ReleaseTag, asset_id: AssetId) -> Self {
        Self::Locked {
            version,
            tag,
            asset_id,
        }
    }

    fn version(&self) -> &Version {
        match self {
            Self::Verified(asset) => asset.version(),
            Self::Locked {
                version,
                tag: _,
                asset_id: _,
            } => version,
        }
    }

    fn tag(&self) -> &ReleaseTag {
        match self {
            Self::Verified(asset) => asset.tag(),
            Self::Locked {
                version: _,
                tag,
                asset_id: _,
            } => tag,
        }
    }

    fn asset_id(&self) -> AssetId {
        match self {
            Self::Verified(asset) => asset.asset_id(),
            Self::Locked {
                version: _,
                tag: _,
                asset_id,
            } => *asset_id,
        }
    }

    fn verified_asset_for_download<G: GithubHttp + ?Sized>(
        &self,
        repo: &RepoSlug,
        github: &GithubApi<'_, G>,
    ) -> Result<VerifiedReleaseAsset, String> {
        match self {
            Self::Verified(asset) => Ok(asset.clone()),
            Self::Locked {
                version,
                tag,
                asset_id,
            } => github
                .verify_locked_release_asset(repo, version, tag, *asset_id)
                .map_err(|error| format!("Failed to verify locked GitHub release asset: {error}")),
        }
    }
}

fn resolve_github_provider_with_clients<G>(
    user_dirs: &UserDirs,
    source: &GithubSource,
    resolved: &ResolvedGithubRelease,
    constraint: Option<&VersionConstraint>,
    name: &str,
    lock_file: &mut GuardedLockFile<'_>,
    github: &GithubApi<'_, G>,
) -> Result<WasmArtifactPath, String>
where
    G: GithubHttp + ?Sized,
{
    let asset_id = resolved.asset_id();
    let repo = RepoSlug::try_from(source).map_err(|error| error.to_string())?;
    let install_lock = lock_file.install_lock();
    let project_dir = install_lock.project_dir();
    let source_key = source.source_key();
    let version = resolved.version();
    let artifact_pin = lookup_github_release_artifact_pin(lock_file, &source_key, version, name);

    // Machine-local caches are accelerators, not trust anchors. Without both a
    // matching lock pin and a user-owned trust record, project and global cache
    // entries are skipped and the artifact is downloaded from its origin.
    // This deliberately preserves issue #2032 only for user-verified cache hits.
    let wasm_path = WasmArtifactPath::new(
        cache_path_github_release(project_dir, &source_key, version),
        name,
    )?;
    if wasm_path.as_path().exists()
        && let Some((lock_entry, pin)) = artifact_pin.pinned(user_dirs)
    {
        let pin = pin.clone();
        let verified = match VerifiedArtifact::from_existing(lock_entry, name, project_dir) {
            Ok(verified) => verified,
            Err(VerifiedArtifactError::ChecksumMismatch(mismatch)) => {
                let removal = install_lock.remove_project_artifact(&wasm_path);
                return Err((*mismatch).after_cache_removal(wasm_path.as_path(), removal));
            }
            Err(VerifiedArtifactError::Other(message)) => return Err(message),
        };
        record_verified_github_release_pin(lock_file, &verified, pin, resolved, name);
        return Ok(verified.path().clone());
    }

    // A global cache hit is usable only with the same existing lock pin.
    if let Some((lock_entry, pin)) = artifact_pin.pinned(user_dirs)
        && let Some(global_wasm) = global_cache_path_github_release(user_dirs, &source_key, version)
        && global_wasm.as_path().exists()
    {
        let pin = pin.clone();
        let verified = match install_project_artifact_from_global_cache(
            install_lock,
            global_wasm.as_path(),
            &wasm_path,
            lock_entry,
            name,
        ) {
            Ok(verified) => verified,
            Err(VerifiedArtifactError::ChecksumMismatch(mismatch)) => {
                let removal = fs::remove_file(global_wasm.as_path());
                return Err((*mismatch).after_cache_removal(global_wasm.as_path(), removal));
            }
            Err(VerifiedArtifactError::Other(message)) => return Err(message),
        };
        record_verified_github_release_pin(lock_file, &verified, pin, resolved, name);
        eprintln!(
            "Installed WASM provider '{}' from global cache ({}@{})",
            name, source_key, version
        );
        return Ok(verified.path().clone());
    }

    let verified_asset = resolved.verified_asset_for_download(&repo, github)?;
    let mut staged = StagedArtifact::for_project(install_lock, &wasm_path).map_err(|error| {
        format!(
            "Failed to stage provider artifact {}: {error}",
            wasm_path.as_path().display()
        )
    })?;
    eprintln!(
        "Downloading WASM provider '{}' from GitHub {}/{} tag '{}' asset id {}",
        name,
        repo.owner(),
        repo.repo(),
        resolved.tag(),
        asset_id
    );
    let (bytes, download_location) = github
        .download_release_asset(verified_asset)
        .map_err(|error| {
            format!(
                "Failed to download GitHub release asset id {asset_id} for tag '{}': {error}",
                resolved.tag()
            )
        })?
        .into_parts();
    staged
        .write_all(&bytes)
        .map_err(|error| format!("Failed to write downloaded file: {error}"))?;

    let installed_path = match publish_download(user_dirs, staged, artifact_pin, download_location)?
    {
        DownloadedArtifact::Verified { artifact, pin } => {
            record_verified_github_release_pin(lock_file, &artifact, pin, resolved, name);
            artifact.path().clone()
        }
        DownloadedArtifact::FirstUse {
            path,
            sha256,
            source: _,
        } => {
            lock_file.upsert(LockEntry {
                name: name.to_string(),
                source: source_key.to_string(),
                kind: LockEntryKind::GithubRelease {
                    version: version.clone(),
                    tag: resolved.tag().clone(),
                    asset_id,
                    constraint: constraint.map(|constraint| constraint.raw.clone()),
                },
                sha256,
                registry: None,
            });
            path
        }
    };
    // Save to global cache
    if let Some(global_wasm) = global_cache_path_github_release(user_dirs, &source_key, version) {
        let _ = install_global_artifact_atomically(installed_path.as_path(), &global_wasm);
    }
    eprintln!(
        "Installed WASM provider '{}' ({}@{})",
        name, source_key, version
    );
    Ok(installed_path)
}

/// Resolve a single provider config with lock file management.
///
/// Handles version validation, lock file load/save, and delegation to `resolve_provider`.
pub fn resolve_single_config(
    user_dirs: &UserDirs,
    install_lock: &ProviderInstallLock,
    config: &ProviderConfig,
) -> Result<WasmArtifactPath, String> {
    resolve_single_config_with_http(user_dirs, install_lock, config, &UreqRegistryHttp)
}

fn resolve_single_config_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    install_lock: &ProviderInstallLock,
    config: &ProviderConfig,
    http: &H,
) -> Result<WasmArtifactPath, String> {
    let source = config
        .source
        .as_ref()
        .ok_or_else(|| format!("Provider '{}' has no source", config.name))?;

    let mut lock_file = install_lock
        .load_lock_file_or_default()
        .map_err(|error| error.to_string())?;
    lock_file.report_migration();

    let artifact_path = resolve_config_with_http(
        user_dirs,
        config,
        source,
        &mut lock_file,
        LockMode::Normal,
        http,
    )?;

    lock_file
        .save()
        .map_err(|e| format!("Failed to save carina-providers.lock: {e}"))?;

    Ok(artifact_path)
}

fn resolve_config_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    config: &ProviderConfig,
    source: &ProviderSource,
    lock_file: &mut GuardedLockFile<'_>,
    mode: LockMode,
    http: &H,
) -> Result<WasmArtifactPath, String> {
    let github_http = UreqGithubHttp;
    let token_provider = EnvironmentGithubTokenProvider;
    let github = GithubApi::with_token_provider(&github_http, &token_provider);
    resolve_config_with_clients(user_dirs, config, source, lock_file, mode, http, &github)
}

fn resolve_config_with_clients<R, G>(
    user_dirs: &UserDirs,
    config: &ProviderConfig,
    source: &ProviderSource,
    lock_file: &mut GuardedLockFile<'_>,
    mode: LockMode,
    registry_http: &R,
    github: &GithubApi<'_, G>,
) -> Result<WasmArtifactPath, String>
where
    R: RegistryHttp,
    G: GithubHttp + ?Sized,
{
    let install_lock = lock_file.install_lock();
    match (source, config.revision.as_deref()) {
        (ProviderSource::File(file_source), _) => resolve_file_provider(
            install_lock,
            &config.name,
            &source.to_string(),
            file_source.path(),
            lock_file,
        ),
        (ProviderSource::Remote(RemoteSource::Registry(registry_source)), Some(revision)) => {
            resolve_registry_revision_with_http(
                user_dirs,
                registry_source,
                revision,
                &config.name,
                lock_file,
                mode,
                registry_http,
            )
        }
        (ProviderSource::Remote(RemoteSource::GithubDirect(github_source)), Some(revision)) => {
            let (path, _sha) = crate::revision_resolver::resolve_provider_by_revision_with_api(
                user_dirs,
                lock_file,
                github_source,
                revision,
                &config.name,
                mode,
                github,
            )?;
            Ok(path)
        }
        (ProviderSource::Remote(RemoteSource::Registry(registry_source)), None) => {
            let source_key = registry_source.source_key();
            let version = if mode != LockMode::Upgrade {
                try_reuse_locked_registry_version(&source_key, config.version.as_ref(), lock_file)
            } else {
                None
            }
            .map(Ok)
            .unwrap_or_else(|| {
                resolve_registry_version_with_http(
                    user_dirs,
                    registry_source,
                    &source_key,
                    &config.name,
                    config.version.as_ref(),
                    lock_file,
                    registry_http,
                )
            })?;
            let path = resolve_registry_provider_with_http(
                user_dirs,
                registry_source,
                &source_key,
                &version,
                &config.name,
                lock_file,
                registry_http,
            )?;
            annotate_version_lock_entry(&source_key, &version, config.version.as_ref(), lock_file);
            Ok(path)
        }
        (ProviderSource::Remote(RemoteSource::GithubDirect(github_source)), None) => {
            let source_key = github_source.source_key();
            let release = resolve_github_release(
                github_source,
                &config.name,
                config.version.as_ref(),
                lock_file,
                mode,
                github,
            )?;
            let path = resolve_github_provider_with_clients(
                user_dirs,
                github_source,
                &release,
                config.version.as_ref(),
                &config.name,
                lock_file,
                github,
            )?;
            annotate_github_release_lock_entry(
                &source_key,
                release.version(),
                config.version.as_ref(),
                lock_file,
            );
            Ok(path)
        }
    }
}

fn resolve_file_provider(
    install_lock: &ProviderInstallLock,
    provider_name: &str,
    source: &str,
    file_path: &str,
    lock_file: &mut LockFile,
) -> Result<WasmArtifactPath, String> {
    let src_path = WasmArtifactPath::new(PathBuf::from(file_path), provider_name)?;
    if !src_path.as_path().exists() {
        return Err(format!(
            "Provider '{}': file source not found: {}",
            provider_name, file_path
        ));
    }
    let dest = file_provider_cache_path(install_lock.project_dir(), &src_path, provider_name)?;
    let sha = install_project_artifact_atomically(install_lock, src_path.as_path(), &dest)
        .map_err(|e| format!("Failed to link file:// provider: {e}"))?;

    lock_file.upsert(LockEntry {
        name: provider_name.to_string(),
        source: source.to_string(),
        kind: LockEntryKind::File,
        sha256: sha,
        registry: None,
    });

    Ok(dest)
}

fn file_provider_cache_path(
    base_dir: &Path,
    src_path: &WasmArtifactPath,
    provider_name: &str,
) -> Result<WasmArtifactPath, String> {
    let file_name = src_path
        .as_path()
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("provider");
    let dest = base_dir
        .join(".carina")
        .join("providers")
        .join("file")
        .join(file_name)
        .join(
            src_path
                .as_path()
                .file_name()
                .and_then(|s| s.to_str())
                .unwrap_or("provider.wasm"),
        );
    WasmArtifactPath::new(dest, provider_name)
}

/// Resolve a `file://` provider at its source path without copying it.
///
/// The LSP uses this direct-source view so its drift poll observes the same
/// file it loads, while still retaining typed file provenance.
pub fn find_file_provider_source(
    base_dir: &Path,
    config: &ProviderConfig,
) -> Result<InstalledProvider, String> {
    let source = config
        .source
        .as_ref()
        .ok_or_else(|| format!("Provider '{}' has no source", config.name))?;
    let file_source = match source {
        ProviderSource::File(file_source) => file_source.clone(),
        ProviderSource::Remote(_) => {
            return Err(format!(
                "Provider '{}' is not a file:// source",
                config.name
            ));
        }
    };
    let file_path = file_source.path();
    let path = PathBuf::from(file_path);
    if !path.exists() {
        return Err(format!("file not found: {file_path}"));
    }
    let path = WasmArtifactPath::new(path, &config.name)?;
    InstalledProvider::file_source(path, config.name.clone(), file_source, base_dir)
}

fn lock_entry_matches_remote_config<P: PlaceholderKind, B: BindingAddress>(
    entry: &LockEntry<RegistryLock>,
    config: &ProviderConfig<P, B>,
    source: &RemoteSource,
) -> bool {
    match (source, config.revision.as_deref(), &entry.kind) {
        (
            RemoteSource::Registry(_),
            Some(requested),
            LockEntryKind::RegistryRevision {
                revision,
                version: _,
            },
        ) => revision == requested,
        (
            RemoteSource::GithubDirect(_),
            Some(requested),
            LockEntryKind::Revision {
                revision,
                resolved_sha: _,
                artifact_id: _,
            },
        ) => revision == requested,
        (
            RemoteSource::Registry(_),
            None,
            LockEntryKind::Version {
                version,
                constraint: _,
            },
        ) => config
            .version
            .as_ref()
            .is_none_or(|constraint| constraint.matches(version).unwrap_or(false)),
        (
            RemoteSource::GithubDirect(_),
            None,
            LockEntryKind::GithubRelease {
                version,
                tag: _,
                asset_id: _,
                constraint: _,
            },
        ) => config
            .version
            .as_ref()
            .is_none_or(|constraint| constraint.req.matches(version)),
        (
            RemoteSource::Registry(_),
            Some(_),
            LockEntryKind::Version {
                version: _,
                constraint: _,
            }
            | LockEntryKind::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint: _,
            }
            | LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::File,
        )
        | (
            RemoteSource::GithubDirect(_),
            Some(_),
            LockEntryKind::Version {
                version: _,
                constraint: _,
            }
            | LockEntryKind::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version: _,
            }
            | LockEntryKind::File,
        )
        | (
            RemoteSource::Registry(_),
            None,
            LockEntryKind::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint: _,
            }
            | LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version: _,
            }
            | LockEntryKind::File,
        )
        | (
            RemoteSource::GithubDirect(_),
            None,
            LockEntryKind::Version {
                version: _,
                constraint: _,
            }
            | LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version: _,
            }
            | LockEntryKind::File,
        ) => false,
    }
}

fn select_locked_artifact<'lock, P: PlaceholderKind, B: BindingAddress>(
    base_dir: &Path,
    config: &ProviderConfig<P, B>,
    remote_source: &RemoteSource,
    lock_file: &'lock LockFile,
) -> Result<Option<LockArtifactSelection<'lock>>, FindInstalledProviderError> {
    let source_key = remote_source.source_key();
    if let Some(legacy) = lock_file
        .legacy
        .iter()
        .find(|entry| LockFile::sources_match(&entry.source, source_key.as_str()))
    {
        return Err(FindInstalledProviderError::LegacyEntry(
            legacy.error(base_dir),
        ));
    }
    let selected = lock_file.find_by_remote_config(config, remote_source);

    selected
        .map(|lock_entry| {
            lock_artifact_selection(base_dir, lock_entry, &config.name)
                .map_err(FindInstalledProviderError::from)
        })
        .transpose()
}

fn installed_provider_from_lock(
    provider_name: &str,
    selection: LockArtifactSelection<'_>,
    project_dir: &Path,
) -> Result<InstalledProvider, String> {
    // Registry pins are recorded only after registry shasum and signature
    // verification. Matching the installed bytes to that lock SHA is the
    // offline proof, so runtime loading never needs a signature-bundle fetch.
    let verified = VerifiedArtifact::from_selection(selection, provider_name, project_dir)
        .map_err(|error| error.to_string())?;
    Ok(InstalledProvider::from_verified(
        verified,
        provider_name.to_string(),
    ))
}

/// Cheap filesystem metadata used to detect in-place provider changes without
/// hashing provider bytes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileMetadataFingerprint {
    pub len: u64,
    pub modified: Option<std::time::SystemTime>,
    #[cfg(unix)]
    pub dev: u64,
    #[cfg(unix)]
    pub ino: u64,
}

/// Metadata for the selected provider artifact and its project lock file.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ProviderArtifactFingerprint {
    pub artifact: Option<FileMetadataFingerprint>,
    pub lock_file: Option<FileMetadataFingerprint>,
}

fn file_metadata_fingerprint(path: &Path) -> Option<FileMetadataFingerprint> {
    let metadata = fs::metadata(path).ok()?;
    if !metadata.is_file() {
        return None;
    }
    Some(FileMetadataFingerprint {
        len: metadata.len(),
        modified: metadata.modified().ok(),
        #[cfg(unix)]
        dev: metadata.dev(),
        #[cfg(unix)]
        ino: metadata.ino(),
    })
}

/// Observe the artifact selected for `config` and `carina-providers.lock`.
///
/// This intentionally does not hash bytes or construct an [`InstalledProvider`].
/// It is suitable for frequent drift polling; actual loads still go through
/// [`find_installed_provider`] and lock-pin verification.
pub fn provider_artifact_fingerprint(
    base_dir: &Path,
    config: &ProviderConfig,
) -> Result<ProviderArtifactFingerprint, LegacyLockEntryError> {
    let lock_file = file_metadata_fingerprint(&provider_lock_path(base_dir));
    let artifact = match config.source.as_ref() {
        Some(ProviderSource::File(file_source)) => {
            WasmArtifactPath::new(PathBuf::from(file_source.path()), &config.name)
                .ok()
                .and_then(|path| file_metadata_fingerprint(path.as_path()))
        }
        Some(ProviderSource::Remote(remote_source)) => {
            let Some(loaded_lock) = load_lock_file(base_dir).ok().flatten() else {
                return Ok(ProviderArtifactFingerprint {
                    artifact: None,
                    lock_file,
                });
            };
            match select_locked_artifact(base_dir, config, remote_source, &loaded_lock) {
                Ok(Some(selection)) => file_metadata_fingerprint(selection.path.as_path()),
                Ok(None) | Err(FindInstalledProviderError::Other(_)) => None,
                Err(FindInstalledProviderError::LegacyEntry(error)) => return Err(error),
            }
        }
        None => None,
    };
    Ok(ProviderArtifactFingerprint {
        artifact,
        lock_file,
    })
}

/// Find an already-installed provider without downloading.
///
/// Checks the project-local provider cache and lock file. For `file://`
/// providers, the returned artifact always retains the lock/file
/// provenance that selected it. This is used by the LSP to avoid
/// editor-triggered downloads as well as by CLI load paths after `carina init`
/// has installed the artifact.
pub fn find_installed_provider<P: PlaceholderKind, B: BindingAddress>(
    base_dir: &Path,
    config: &ProviderConfig<P, B>,
) -> Result<InstalledProvider, FindInstalledProviderError> {
    let source = config
        .source
        .as_ref()
        .ok_or_else(|| format!("Provider '{}' has no source", config.name))?;

    let remote_source = match source {
        ProviderSource::File(file_source) => {
            let src = WasmArtifactPath::new(PathBuf::from(file_source.path()), &config.name)?;
            let dest = file_provider_cache_path(base_dir, &src, &config.name)?;
            if dest.as_path().exists() {
                return Ok(InstalledProvider::file_source(
                    dest,
                    config.name.clone(),
                    file_source.clone(),
                    base_dir,
                )?);
            }
            return Err(FindInstalledProviderError::Other(format!(
                "not installed. Run `{}`",
                ProjectCommand::new("init", base_dir)
            )));
        }
        ProviderSource::Remote(remote_source) => remote_source,
    };
    let lock_file = load_lock_file(base_dir)
        .map_err(|error| FindInstalledProviderError::Other(error.to_string()))?
        .unwrap_or_default();

    // Only the project-local `.carina/` counts. The global plugin cache is an
    // install-time optimization consulted by `carina init`; treating it as a
    // runtime source lets validate/plan/apply silently succeed when a prior
    // project already pulled this provider and the current project has no
    // local install yet (issue #2018).
    if let Some(selection) = select_locked_artifact(base_dir, config, remote_source, &lock_file)? {
        if selection.path.as_path().exists() {
            return installed_provider_from_lock(&config.name, selection, base_dir)
                .map_err(FindInstalledProviderError::Other);
        }
        return Err(FindInstalledProviderError::Other(
            missing_locked_artifact_error(base_dir, &selection.pin, config.revision.as_deref()),
        ));
    }

    if let Some(revision) = &config.revision {
        return Err(FindInstalledProviderError::Other(format!(
            "not installed. Run `{}` to install (revision: {revision})",
            ProjectCommand::new("init", base_dir)
        )));
    }

    Err(FindInstalledProviderError::Other(format!(
        "not installed. Run `{}`",
        ProjectCommand::new("init", base_dir)
    )))
}

fn try_reuse_locked_registry_version(
    source: &RemoteSourceKey,
    constraint: Option<&VersionConstraint>,
    lock_file: &LockFile,
) -> Option<String> {
    lock_file.provider.iter().find_map(|entry| {
        if !LockFile::sources_match(&entry.source, source.as_str()) {
            return None;
        }
        match &entry.kind {
            LockEntryKind::Version {
                version,
                constraint: _,
            } if constraint
                .is_none_or(|constraint| constraint.matches(version).unwrap_or(false)) =>
            {
                Some(version.clone())
            }
            LockEntryKind::Version {
                version: _,
                constraint: _,
            }
            | LockEntryKind::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint: _,
            }
            | LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version: _,
            }
            | LockEntryKind::File => None,
        }
    })
}

fn try_reuse_locked_github_release(
    source: &RemoteSourceKey,
    constraint: Option<&VersionConstraint>,
    lock_file: &LockFile,
) -> Result<Option<ResolvedGithubRelease>, String> {
    Ok(lock_file.provider.iter().find_map(|entry| {
        if !LockFile::sources_match(&entry.source, source.as_str()) {
            return None;
        }
        match &entry.kind {
            LockEntryKind::GithubRelease {
                version,
                tag,
                asset_id,
                constraint: _,
            } if constraint.is_none_or(|constraint| constraint.req.matches(version)) => Some(
                ResolvedGithubRelease::from_lock_entry(version.clone(), tag.clone(), *asset_id),
            ),
            LockEntryKind::GithubRelease {
                version: _,
                tag: _,
                asset_id: _,
                constraint: _,
            }
            | LockEntryKind::Version {
                version: _,
                constraint: _,
            }
            | LockEntryKind::Revision {
                revision: _,
                resolved_sha: _,
                artifact_id: _,
            }
            | LockEntryKind::RegistryRevision {
                revision: _,
                version: _,
            }
            | LockEntryKind::File => None,
        }
    }))
}

fn resolve_github_release<G: GithubHttp + ?Sized>(
    source: &GithubSource,
    provider_name: &str,
    constraint: Option<&VersionConstraint>,
    lock_file: &mut GuardedLockFile<'_>,
    mode: LockMode,
    github: &GithubApi<'_, G>,
) -> Result<ResolvedGithubRelease, String> {
    let source_key = source.source_key();
    let repo = RepoSlug::try_from(source).map_err(|error| error.to_string())?;
    if mode != LockMode::Upgrade
        && let Some(release) = try_reuse_locked_github_release(&source_key, constraint, lock_file)?
    {
        return Ok(release);
    }

    if mode == LockMode::Normal
        && let Some((legacy_version, legacy_sha256)) =
            lock_file.legacy_github_version_pin(&source_key)
    {
        if let Some(constraint) = constraint
            && !constraint.matches(&legacy_version).unwrap_or(false)
        {
            return Err(mismatch_error(
                provider_name,
                &format!("version = '{legacy_version}'"),
                &format!("constraint = '{}'", constraint.raw),
                lock_file.project_dir(),
            )
            .to_string());
        }
        let version = Version::parse(&legacy_version).map_err(|error| {
            format!(
                "Invalid semantic version '{}' in legacy GitHub release lock entry for {}: {error}",
                legacy_version, source_key
            )
        })?;
        let releases = fetch_releases_with_api(source, github)?;
        let release = resolve_release_at_version(&releases, &version)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| {
                let available = releases
                    .iter()
                    .map(|release| release.tag().as_str())
                    .collect::<Vec<_>>()
                    .join(", ");
                format!(
                    "No release of '{}' has the legacy-pinned version '{}'. Available: {}",
                    provider_name, legacy_version, available
                )
            })?;
        let resolved = ResolvedGithubRelease::from_selected_release(repo.clone(), release)
            .map_err(|error| error.to_string())?;
        lock_file.upsert(LockEntry {
            name: provider_name.to_string(),
            source: source_key.to_string(),
            kind: LockEntryKind::GithubRelease {
                version: resolved.version().clone(),
                tag: resolved.tag().clone(),
                asset_id: resolved.asset_id(),
                constraint: constraint.map(|constraint| constraint.raw.clone()),
            },
            sha256: legacy_sha256,
            registry: None,
        });
        return Ok(resolved);
    }

    match constraint {
        Some(constraint) => {
            let releases = fetch_releases_with_api(source, github)?;
            let release = resolve_from_releases(&releases, &constraint.req)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| {
                    let available = releases
                        .iter()
                        .map(|release| release.tag().as_str())
                        .collect::<Vec<_>>()
                        .join(", ");
                    format!(
                        "No release of '{}' matches constraint '{}'. Available: {}",
                        provider_name, constraint.raw, available
                    )
                })?;
            ResolvedGithubRelease::from_selected_release(repo, release)
                .map_err(|error| error.to_string())
        }
        None => ResolvedGithubRelease::from_selected_release(
            repo,
            fetch_latest_release_with_api(source, github)?,
        )
        .map_err(|error| error.to_string()),
    }
}

fn resolve_registry_version_with_http<H: RegistryHttp>(
    user_dirs: &UserDirs,
    source: &RegistrySource,
    source_key: &RemoteSourceKey,
    provider_name: &str,
    constraint: Option<&VersionConstraint>,
    lock_file: &mut GuardedLockFile<'_>,
    http: &H,
) -> Result<String, String> {
    let install_lock = lock_file.install_lock();
    let project_dir = install_lock.project_dir();
    let existing_host = lock_file.registry_host_lock(source.hostname()).cloned();
    let registry = resolve_registry(source, existing_host.as_ref(), project_dir, http)?;
    let RecordedRegistryListing { versions, .. } = {
        let mut persistent_lock = PersistentLockFile::new(lock_file);
        let listing =
            fetch_registry_versions(&registry, source, source_key, &mut persistent_lock, http)?;
        convert_obtainable_legacy_signer_pin(
            user_dirs,
            &registry,
            source,
            source_key,
            None,
            &mut persistent_lock,
            http,
        )?;
        listing
    };
    let candidates = SelectableRegistryVersions::from_listing(&versions.versions);
    select_registry_version(&candidates, provider_name, constraint)
}

/// How strictly `resolve_all` treats a pre-existing lock file.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LockMode {
    /// Default for `carina init`: error on mismatch between `.crn` and lock,
    /// but a provider absent from the lock (first-time add) is accepted.
    Normal,
    /// Re-resolve every configured provider while retaining unrelated lock
    /// entries. Set by `carina init --upgrade`.
    Upgrade,
    /// Strict CI mode: the lock must match the `.crn` exactly. A provider
    /// present in `.crn` but missing from the lock is an error.
    /// Set by `carina init --locked`. Mirrors Cargo's `--locked`.
    Locked,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LockMismatchError {
    LegacyEntry(LegacyLockEntryError),
    Mismatch(String),
}

impl fmt::Display for LockMismatchError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LegacyEntry(error) => error.fmt(formatter),
            Self::Mismatch(message) => formatter.write_str(message),
        }
    }
}

impl std::error::Error for LockMismatchError {}

#[derive(Debug)]
pub enum ResolveAllError {
    LockMismatch(LockMismatchError),
    Egress(Box<EgressInitializationError>),
    Other(String),
}

impl fmt::Display for ResolveAllError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LockMismatch(error) => error.fmt(formatter),
            Self::Egress(error) => error.fmt(formatter),
            Self::Other(message) => formatter.write_str(message),
        }
    }
}

impl std::error::Error for ResolveAllError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::LockMismatch(error) => error.source(),
            Self::Egress(error) => error.source(),
            Self::Other(_) => None,
        }
    }
}

impl From<LockMismatchError> for ResolveAllError {
    fn from(error: LockMismatchError) -> Self {
        Self::LockMismatch(error)
    }
}

impl From<EgressInitializationError> for ResolveAllError {
    fn from(error: EgressInitializationError) -> Self {
        Self::Egress(Box::new(error))
    }
}

impl From<String> for ResolveAllError {
    fn from(message: String) -> Self {
        Self::Other(message)
    }
}

#[derive(Debug)]
pub enum EgressInitializationError {
    Installed(FindInstalledProviderError),
    Artifact(Box<ProviderArtifactLoadError<crate::EgressSectionError>>),
    LockedConsent(crate::EgressConsentError),
    Consent(crate::EgressConsentError),
    NonInteractive { source: crate::CanonicalSource },
    Refused { source: crate::CanonicalSource },
    Prompt(io::Error),
}

impl fmt::Display for EgressInitializationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Installed(source) => source.fmt(formatter),
            Self::Artifact(source) => source.fmt(formatter),
            Self::LockedConsent(source) => write!(
                formatter,
                "locked egress consent is missing or stale: {source}"
            ),
            Self::Consent(source) => source.fmt(formatter),
            Self::NonInteractive { source } => write!(
                formatter,
                "provider source {source} requires explicit egress consent, but stdin is not a terminal; re-run with `--accept-egress {source}` or add the source to the comma-separated CARINA_ACCEPT_EGRESS list"
            ),
            Self::Refused { source } => {
                write!(
                    formatter,
                    "egress consent was not granted for provider source {source}"
                )
            }
            Self::Prompt(source) => write!(formatter, "failed to read egress consent: {source}"),
        }
    }
}

impl std::error::Error for EgressInitializationError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Installed(source) => source.source(),
            Self::Artifact(source) => source.source(),
            Self::Consent(source) => source.source(),
            Self::LockedConsent(_)
            | Self::Prompt(_)
            | Self::NonInteractive { .. }
            | Self::Refused { .. } => None,
        }
    }
}

/// Compare `.crn` provider configs against the lock file and return an
/// error when they disagree. Silent rewrites of the lock on mismatch were
/// defeating the reproducibility contract (issue #2026); every mature tool
/// (Cargo, npm ci, Terraform, Bundler) errors instead.
///
/// Categories detected:
/// - Version constraint that no longer accepts the locked version.
/// - `.crn` switched from version mode to revision mode (or vice versa)
///   since the lock was written.
/// - Same mode but different revision.
/// - (`--locked` only) provider present in `.crn` but missing from the lock.
///
/// Orphan lock entries (present in lock, absent in `.crn`) are intentionally
/// not reported here and remain retained by every resolution mode.
/// `project_dir` is the user-facing project argument rendered in any mismatch
/// remediation.
pub fn check_lock_mismatch(
    providers: &[ProviderConfig],
    lock_file: &LockFile,
    mode: LockMode,
    project_dir: &Path,
) -> Result<(), LockMismatchError> {
    if mode == LockMode::Upgrade {
        return Ok(());
    }
    let mismatch_error =
        |name, lock_shape, crn_shape| mismatch_error(name, lock_shape, crn_shape, project_dir);

    for config in providers {
        let remote_source = match &config.source {
            Some(ProviderSource::Remote(source)) => source,
            // No source or file source — either the resolver skips it or the
            // sha256 is refreshed every run, so there's nothing to mismatch.
            Some(ProviderSource::File(_)) | None => continue,
        };
        let source_key = remote_source.source_key();

        let lock_entry = match lock_file.find_source_entry(&source_key) {
            Some(SourceLockEntry::Typed(first_entry)) => lock_file
                .find_by_remote_config(config, remote_source)
                .unwrap_or(first_entry),
            Some(SourceLockEntry::Legacy(entry)) => {
                match &entry.reason {
                    LegacyReason::GithubDirectVersionWithoutTag {
                        version: legacy_version,
                        sha256: _,
                    } => {
                        if let Some(crn_revision) = &config.revision {
                            return Err(mismatch_error(
                                &config.name,
                                &format!("version = '{legacy_version}'"),
                                &format!("revision = '{crn_revision}'"),
                            ));
                        }
                        if let Some(constraint) = &config.version
                            && !constraint.matches(legacy_version).unwrap_or(false)
                        {
                            return Err(mismatch_error(
                                &config.name,
                                &format!("version = '{legacy_version}'"),
                                &format!("constraint = '{}'", constraint.raw),
                            ));
                        }
                    }
                    LegacyReason::RevisionWithoutArtifactId {
                        revision: locked_revision,
                        resolved_sha: _,
                        sha256: _,
                    } => match &config.revision {
                        Some(crn_revision) if crn_revision == locked_revision => {}
                        Some(crn_revision) => {
                            return Err(mismatch_error(
                                &config.name,
                                &format!("revision = '{locked_revision}'"),
                                &format!("revision = '{crn_revision}'"),
                            ));
                        }
                        None => {
                            let crn_shape = config.version.as_ref().map_or_else(
                                || {
                                    "(no revision, no version constraint — version mode)"
                                        .to_string()
                                },
                                |constraint| format!("version constraint = '{}'", constraint.raw),
                            );
                            return Err(mismatch_error(
                                &config.name,
                                &format!("revision = '{locked_revision}'"),
                                &crn_shape,
                            ));
                        }
                    },
                }
                if mode == LockMode::Locked {
                    return Err(LockMismatchError::LegacyEntry(entry.error(project_dir)));
                }
                continue;
            }
            None => {
                if mode == LockMode::Locked {
                    return Err(LockMismatchError::Mismatch(format!(
                        "provider '{}' is declared in .crn but missing from carina-providers.lock\n\
                         hint: running with --locked requires the lock to be committed up-to-date;\n\
                               re-run without --locked (or `{}`) to populate it.",
                        config.name,
                        ProjectCommand::new("init --upgrade", project_dir)
                    )));
                }
                continue;
            }
        };

        match (&config.revision, &config.version, &lock_entry.kind) {
            // .crn has both revision and version (parser should reject this);
            // treat as accept and let the resolver surface its own error.
            (
                Some(_),
                Some(_),
                LockEntryKind::Version {
                    version: _,
                    constraint: _,
                },
            )
            | (
                Some(_),
                Some(_),
                LockEntryKind::GithubRelease {
                    version: _,
                    tag: _,
                    asset_id: _,
                    constraint: _,
                },
            )
            | (
                Some(_),
                Some(_),
                LockEntryKind::Revision {
                    revision: _,
                    resolved_sha: _,
                    artifact_id: _,
                },
            )
            | (
                Some(_),
                Some(_),
                LockEntryKind::RegistryRevision {
                    revision: _,
                    version: _,
                },
            )
            | (Some(_), Some(_), LockEntryKind::File) => {}
            // .crn revision — lock revision: must match literally.
            (
                Some(crn_rev),
                _,
                LockEntryKind::Revision {
                    revision: locked_rev,
                    resolved_sha: _,
                    artifact_id: _,
                },
            ) => {
                if crn_rev != locked_rev {
                    return Err(mismatch_error(
                        &config.name,
                        &format!("revision = '{locked_rev}'"),
                        &format!("revision = '{crn_rev}'"),
                    ));
                }
            }
            // .crn revision — lock registry-revision: the locked branch must match.
            (
                Some(crn_rev),
                _,
                LockEntryKind::RegistryRevision {
                    revision: locked_rev,
                    version: _,
                },
            ) => {
                if crn_rev != locked_rev {
                    return Err(mismatch_error(
                        &config.name,
                        &format!("revision = '{locked_rev}'"),
                        &format!("revision = '{crn_rev}'"),
                    ));
                }
            }
            // .crn revision — lock plain version (mode switched).
            (
                Some(crn_rev),
                _,
                LockEntryKind::Version {
                    version: locked_ver,
                    constraint: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("version  = '{locked_ver}'"),
                    &format!("revision = '{crn_rev}'"),
                ));
            }
            (
                Some(crn_rev),
                _,
                LockEntryKind::GithubRelease {
                    version: locked_ver,
                    tag: locked_tag,
                    asset_id: _,
                    constraint: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("version = '{locked_ver}', tag = '{locked_tag}'"),
                    &format!("revision = '{crn_rev}'"),
                ));
            }
            // .crn version constraint — lock version: constraint must still accept it.
            (
                None,
                Some(constraint),
                LockEntryKind::Version {
                    version: locked_ver,
                    constraint: _,
                },
            ) => {
                if !constraint.matches(locked_ver).unwrap_or(false) {
                    return Err(mismatch_error(
                        &config.name,
                        &format!("version = '{locked_ver}'"),
                        &format!("constraint = '{}'", constraint.raw),
                    ));
                }
            }
            (
                None,
                Some(constraint),
                LockEntryKind::GithubRelease {
                    version: locked_ver,
                    tag: _,
                    asset_id: _,
                    constraint: _,
                },
            ) => {
                if !constraint.req.matches(locked_ver) {
                    return Err(mismatch_error(
                        &config.name,
                        &format!("version = '{locked_ver}'"),
                        &format!("constraint = '{}'", constraint.raw),
                    ));
                }
            }
            // .crn version — lock revision (mode switched).
            (
                None,
                Some(constraint),
                LockEntryKind::Revision {
                    revision: locked_rev,
                    resolved_sha: _,
                    artifact_id: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("revision = '{locked_rev}'"),
                    &format!("version constraint = '{}'", constraint.raw),
                ));
            }
            // .crn version — lock registry revision (mode switched).
            (
                None,
                Some(constraint),
                LockEntryKind::RegistryRevision {
                    revision: locked_rev,
                    version: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("revision = '{locked_rev}'"),
                    &format!("constraint = '{}'", constraint.raw),
                ));
            }
            // No constraint and no revision in .crn: the user didn't pin
            // anything explicitly. That implies version mode (latest tag).
            // Any pre-existing lock entry must also be version mode — a
            // revision-mode entry was written under a `.crn` that had
            // `revision = '...'` and is now gone, which is still a mismatch.
            (
                None,
                None,
                LockEntryKind::RegistryRevision {
                    revision: locked_rev,
                    version: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("revision = '{locked_rev}'"),
                    "(no revision, no version constraint — version mode)",
                ));
            }
            (
                None,
                None,
                LockEntryKind::Version {
                    version: _,
                    constraint: _,
                },
            ) => {}
            (
                None,
                None,
                LockEntryKind::GithubRelease {
                    version: _,
                    tag: _,
                    asset_id: _,
                    constraint: _,
                },
            ) => {}
            (
                None,
                None,
                LockEntryKind::Revision {
                    revision: locked_rev,
                    resolved_sha: _,
                    artifact_id: _,
                },
            ) => {
                return Err(mismatch_error(
                    &config.name,
                    &format!("revision = '{locked_rev}'"),
                    "(no revision, no version constraint — version mode)",
                ));
            }
            // .crn provider vs a file-mode lock entry: sources shouldn't match,
            // so this arm is effectively unreachable, but bail safely.
            (_, _, LockEntryKind::File) => {}
        }
    }

    Ok(())
}

fn mismatch_error(
    name: &str,
    lock_shape: &str,
    crn_shape: &str,
    project_dir: &Path,
) -> LockMismatchError {
    LockMismatchError::Mismatch(format!(
        "lock file does not match providers.crn\n  \
         provider '{name}':\n    \
         providers.crn:  {crn_shape}\n    \
         lock:           {lock_shape}\n  \
         hint: run `{}` to resolve providers from the current\n        \
         configuration and rewrite carina-providers.lock",
        ProjectCommand::new("init --upgrade", project_dir)
    ))
}

/// Resolve all configured provider sources.
pub fn resolve_all(
    user_dirs: &UserDirs,
    install_lock: &ProviderInstallLock,
    providers: &[ProviderConfig],
    mode: LockMode,
) -> Result<HashMap<String, WasmArtifactPath>, ResolveAllError> {
    let github_http = UreqGithubHttp;
    let token_provider = EnvironmentGithubTokenProvider;
    let github = GithubApi::with_token_provider(&github_http, &token_provider);
    resolve_all_with_http(
        user_dirs,
        install_lock,
        providers,
        mode,
        &UreqRegistryHttp,
        &github,
    )
}

/// Resolve providers and record or verify the egress declaration carried by
/// each exact installed artifact.
pub fn resolve_all_with_egress(
    user_dirs: &UserDirs,
    install_lock: &ProviderInstallLock,
    providers: &[ProviderConfig],
    mode: LockMode,
    accepted_sources: &crate::AcceptedEgressSources,
) -> Result<HashMap<String, WasmArtifactPath>, ResolveAllError> {
    let github_http = UreqGithubHttp;
    let token_provider = EnvironmentGithubTokenProvider;
    let github = GithubApi::with_token_provider(&github_http, &token_provider);
    resolve_all_with_http_and_egress(
        user_dirs,
        install_lock,
        providers,
        mode,
        &UreqRegistryHttp,
        &github,
        ResolveEgress::Initialize(accepted_sources),
    )
}

