    fn pending_discovery_pins_in(serialized: &str, hostname: &str) -> Vec<toml::Value> {
        let lock: toml::Value = toml::from_str(serialized).unwrap();
        lock.get("registry_host")
            .and_then(|hosts| hosts.get(hostname))
            .and_then(|host| host.get("migration_pending_discovery_pins"))
            .and_then(toml::Value::as_array)
            .expect("migrated hosts must serialize a pending-pin array")
            .clone()
    }

    fn unpinned_v2_lock_toml() -> String {
        fully_protected_v2_lock_toml().replace(
            r#"discovery_pin_present = true
api_base_url = "https://registry.carina-rs.dev/v1/providers/"
discovery_sha256 = "legacy-discovery-sha256""#,
            "discovery_pin_present = false",
        )
    }

    fn two_host_v2_lock_toml() -> String {
        let mut lock = fully_protected_v2_lock_toml().replace(
            "\n[[provider]]",
            r#"

[registry_host."registry.example.test"]
discovery_pin_present = true
api_base_url = "https://registry.example.test/v1/providers/"
discovery_sha256 = "other-legacy-discovery-sha256"

[[provider]]"#,
        );
        lock.push_str(
            r#"
[[provider]]
name = "random"
source = "registry.example.test/carina-rs/random"
mode = "version"
version = "1.0.0"
sha256 = "other-pinned-provider-sha256"

[provider.registry]
resolved_hostname = "registry.example.test"
sequence_present = false
sequence_anchor_established = false
valid_until_present = false
signature_present = false
transparency_log_present = false
"#,
        );
        lock
    }

    fn lock_with_registry_security_state(signature: RegistrySignatureProtection) -> LockFile {
        lock_with_registry_security_state_for_host("registry.carina-rs.dev", signature)
    }

    fn lock_with_registry_security_state_for_host(
        hostname: &str,
        signature: RegistrySignatureProtection,
    ) -> LockFile {
        let api_base_url = format!("https://{hostname}/v1/providers/");
        LockFile {
            version: LockFile::CURRENT_VERSION,
            registry_host: registry_host_table(hostname, &api_base_url),
            provider: vec![LockEntry {
                name: "aws".into(),
                source: "carina-rs/aws".into(),
                kind: LockEntryKind::Version {
                    version: "0.5.0".into(),
                    constraint: Some("^0.5".into()),
                },
                sha256: "pinned-shasum".into(),
                registry: Some(RegistryLock {
                    resolved_hostname: hostname.into(),
                    sequence: RegistrySequence::Present(7),
                    sequence_anchor: RegistrySequenceAnchor::Established(5),
                    valid_until_present: true,
                    yanked_versions: YankedRegistryVersions(BTreeSet::from(["0.4.0".into()])),
                    signature,
                    transparency_log_present: true,
                }),
            }],
            egress: BTreeMap::new(),
            legacy: Vec::new(),
            unpinned_registry_ratchets: UnpinnedRegistryRatchets::default(),
        }
    }

    fn lock_with_duplicate_registry_source(signature: RegistrySignatureProtection) -> LockFile {
        let mut lock = lock_with_registry_security_state(signature);
        let protected = lock.provider.pop().unwrap();
        lock.provider = vec![
            version_entry::<RegistryLock>("carina-rs/aws", "0.4.0"),
            protected,
        ];
        lock
    }

    fn assert_known_yank_is_still_refused(lock: &LockFile) {
        let source = registry_source("carina-rs/aws");
        let known = lock.known_registry_ratchets("carina-rs/aws").unwrap();
        assert!(
            known.yanked_versions.contains("0.4.0"),
            "the consumer-facing ratchets must retain the recorded yank"
        );
        let listing = RegistryVersions {
            sequence: Some(7),
            valid_until: Some("2999-01-01T00:00:00Z".into()),
            versions: vec![RegistryVersion {
                version: "0.4.0".into(),
                yanked: false,
            }],
        };
        let error = match ValidatedRegistryListing::validate(
            &source,
            &listing,
            &known,
            lock.registry_sequence_previous_state("carina-rs/aws"),
            Path::new("."),
        ) {
            Ok(_) => panic!("an explicitly recorded yank must not be reversible"),
            Err(error) => error,
        };
        assert!(error.contains("yanked flag disappeared"), "{error}");
        assert!(error.contains("0.4.0"), "{error}");
    }

    fn lock_toml_error(content: &str) -> LockFileError {
        let dir = tempfile::tempdir().unwrap();
        let lock_path = dir.path().join("carina-providers.lock");
        fs::write(&lock_path, content).unwrap();
        load_lock_file_for_test(&lock_path)
            .expect_err("invalid protection metadata must be rejected")
    }

    fn assert_lock_toml_is_rejected(content: &str) {
        let error = lock_toml_error(content);
        assert!(matches!(error, LockFileError::Parse { .. }), "{error}");
    }

    fn version_entry<R>(source: &str, version: &str) -> LockEntry<R> {
        LockEntry {
            name: "awscc".into(),
            source: source.into(),
            kind: LockEntryKind::Version {
                version: version.into(),
                constraint: None,
            },
            sha256: "abc".into(),
            registry: None,
        }
    }

    fn github_release_entry<R>(source: &str, version: &str) -> LockEntry<R> {
        LockEntry {
            name: "awscc".into(),
            source: source.into(),
            kind: LockEntryKind::GithubRelease {
                version: Version::parse(version).unwrap(),
                tag: ReleaseTag::from_lock(format!("v{version}")),
                asset_id: release_asset_id(42),
                constraint: None,
            },
            sha256: "abc".into(),
            registry: None,
        }
    }

    fn revision_entry<R>(source: &str, revision: &str, sha: &str) -> LockEntry<R> {
        LockEntry {
            name: "awscc".into(),
            source: source.into(),
            kind: LockEntryKind::Revision {
                revision: revision.into(),
                resolved_sha: commit_sha(sha),
                artifact_id: artifact_id(42),
            },
            sha256: "abc".into(),
            registry: None,
        }
    }

    #[test]
    fn revision_lock_round_trip_preserves_artifact_id() {
        let mut lock = LockFile::default();
        lock.upsert(revision_entry(
            "github.com/carina-rs/carina-provider-awscc",
            "main",
            TEST_COMMIT_SHA,
        ));

        let serialized = lock.to_toml_string().unwrap();
        assert!(serialized.contains("artifact_id = 42"), "{serialized}");

        let parsed =
            LockFile::from_toml_str(&serialized, Path::new("carina-providers.lock")).unwrap();
        assert_eq!(
            parsed.provider[0].kind,
            LockEntryKind::Revision {
                revision: "main".into(),
                resolved_sha: commit_sha(TEST_COMMIT_SHA),
                artifact_id: artifact_id(42),
            }
        );
    }

    #[test]
    fn legacy_revision_lock_is_reselected_in_normal_mode_and_rejected_in_locked_mode() {
        let user_dirs = carina_core::TestUserDirs::new();
        let source = "github.com/carina-rs/carina-provider-awscc";
        let serialized = format!(
            r#"version = {}

[[provider]]
name = "awscc"
source = "{source}"
mode = "revision"
revision = "main"
resolved_sha = "{TEST_COMMIT_SHA}"
sha256 = "legacy"
"#,
            LockFile::CURRENT_VERSION
        );
        let lock =
            LockFile::from_toml_str(&serialized, Path::new("carina-providers.lock")).unwrap();
        let config = provider_config(source, Some("main"));

        assert!(lock.provider.is_empty());
        check_lock_mismatch(std::slice::from_ref(&config), &lock, LockMode::Normal).unwrap();
        let error = check_lock_mismatch(&[config], &lock, LockMode::Locked).unwrap_err();
        assert!(matches!(
            &error,
            LockMismatchError::LegacyEntry(LegacyLockEntryError {
                source: locked_source,
                reason: LegacyReason::RevisionWithoutArtifactId {
                    revision,
                    resolved_sha,
                    sha256,
                },
                project_dir: _,
            }) if locked_source == source
                && revision == "main"
                && resolved_sha == &commit_sha(TEST_COMMIT_SHA)
                && sha256 == "legacy"
        ));
        let rendered = error.to_string();
        assert!(rendered.contains(source), "{rendered}");
        assert!(rendered.contains("carina init"), "{rendered}");
        assert!(
            lock.to_toml_string()
                .unwrap()
                .contains("mode = \"revision\"")
        );

        let project = tempfile::tempdir().unwrap();
        fs::write(provider_lock_path(project.path()), &serialized).unwrap();
        let install_lock = ProviderInstallLock::acquire(project.path()).unwrap();
        let error = resolve_all(
            &user_dirs,
            &install_lock,
            &[provider_config(source, Some("main"))],
            LockMode::Locked,
        )
        .unwrap_err();
        assert!(matches!(
            &error,
            ResolveAllError::LockMismatch(LockMismatchError::LegacyEntry(
                LegacyLockEntryError {
                    source: locked_source,
                    reason: LegacyReason::RevisionWithoutArtifactId {
                        revision,
                        resolved_sha,
                        sha256,
                    },
                    project_dir: _,
                }
            )) if locked_source == source
                && revision == "main"
                && resolved_sha == &commit_sha(TEST_COMMIT_SHA)
                && sha256 == "legacy"
        ));
        let rendered = error.to_string();
        assert!(rendered.contains(source), "{rendered}");
        assert!(rendered.contains("carina init"), "{rendered}");
    }

    #[test]
    fn legacy_revision_filter_requires_exact_keys_and_allows_registry() {
        let mut entry = toml::Table::new();
        for (key, value) in [
            ("name", "awscc"),
            ("source", "github.com/carina-rs/carina-provider-awscc"),
            ("mode", "revision"),
            ("revision", "main"),
            ("resolved_sha", TEST_COMMIT_SHA),
            ("sha256", "legacy"),
        ] {
            entry.insert(key.to_string(), toml::Value::String(value.to_string()));
        }

        let (retained, legacy) = split_legacy_entries(vec![entry.clone()]).unwrap();
        assert!(retained.is_empty());
        assert!(matches!(
            legacy.as_slice(),
            [LegacyLockEntry {
                source,
                reason: LegacyReason::RevisionWithoutArtifactId {
                    revision,
                    resolved_sha,
                    sha256,
                },
                raw: _,
            }] if source == "github.com/carina-rs/carina-provider-awscc"
                && revision == "main"
                && resolved_sha == &commit_sha(TEST_COMMIT_SHA)
                && sha256 == "legacy"
        ));
        entry.insert("registry".into(), toml::Value::Table(toml::Table::new()));
        let (retained, legacy) = split_legacy_entries(vec![entry.clone()]).unwrap();
        assert!(retained.is_empty());
        assert_eq!(legacy.len(), 1);
        entry.insert("artifact_ld".into(), toml::Value::Integer(42));
        let (retained, legacy) = split_legacy_entries(vec![entry.clone()]).unwrap();
        assert_eq!(retained, vec![entry]);
        assert!(legacy.is_empty());
    }

