    #[test]
    fn malformed_current_revision_shas_fail_lock_parsing_without_panicking() {
        let invalid_values = [
            "../..".to_string(),
            "日本語".to_string(),
            TEST_COMMIT_SHA.to_ascii_uppercase(),
            format!("{TEST_COMMIT_SHA}&event=x"),
        ];

        for invalid in invalid_values {
            let serialized = format!(
                r#"version = {}

[[provider]]
name = "awscc"
source = "github.com/carina-rs/carina-provider-awscc"
mode = "revision"
revision = "main"
resolved_sha = {invalid:?}
artifact_id = 42
sha256 = "malformed"
"#,
                LockFile::CURRENT_VERSION
            );

            let result = std::panic::catch_unwind(|| {
                LockFile::from_toml_str(&serialized, Path::new("carina-providers.lock"))
            });
            let error = result
                .expect("malformed resolved SHA must not panic")
                .expect_err("malformed resolved SHA must fail lock parsing");
            assert!(matches!(error, LockFileError::Parse { .. }), "{error}");
        }
    }

    #[test]
    fn malformed_legacy_revision_shas_return_typed_parse_errors() {
        for invalid in [
            "../..",
            "日本語",
            "ABCDEF0123456789ABCDEF0123456789ABCDEF01",
        ] {
            let serialized = format!(
                r#"version = {}

[[provider]]
name = "awscc"
source = "github.com/carina-rs/carina-provider-awscc"
mode = "revision"
revision = "main"
resolved_sha = {invalid:?}
sha256 = "malformed"
"#,
                LockFile::CURRENT_VERSION
            );

            let error = LockFile::from_toml_str(&serialized, Path::new("carina-providers.lock"))
                .expect_err("malformed legacy resolved SHA must fail lock parsing");
            assert!(matches!(
                error,
                LockFileError::LegacyEntryParse {
                    source: LegacyLockEntryParseError::InvalidResolvedSha {
                        source,
                        value,
                    },
                    path: _,
                } if source == "github.com/carina-rs/carina-provider-awscc" && value == invalid
            ));
        }
    }

    fn provider_config(source: &str, revision: Option<&str>) -> ProviderConfig {
        ProviderConfig {
            name: "awscc".into(),
            source: Some(source.parse().unwrap()),
            version: None,
            revision: revision.map(|r| r.into()),
            attributes: IndexMap::new(),
            default_tags: IndexMap::new(),
            unresolved_attributes: IndexMap::new(),
            binding: None,
        }
    }

    fn local_file_source(path: &Path) -> FileSource {
        match format!("file://{}", path.display())
            .parse::<ProviderSource>()
            .unwrap()
        {
            ProviderSource::File(source) => source,
            ProviderSource::Remote(_) => panic!("expected file source"),
        }
    }

    #[test]
    fn registry_version_models_optional_yanked_flag() {
        let listing: RegistryVersions = serde_json::from_str(
            r#"{"versions":[{"version":"1.2.3","protocols":["1"]},{"version":"1.1.0","protocols":["1"],"yanked":false},{"version":"1.0.0","protocols":["1"],"yanked":true}]}"#,
        )
        .unwrap();

        assert!(!listing.versions[0].yanked);
        assert!(!listing.versions[1].yanked);
        assert!(listing.versions[2].yanked);
    }

    fn listed_version(version: &str, yanked: bool) -> RegistryVersion {
        RegistryVersion {
            version: version.into(),
            yanked,
        }
    }

    fn select_from_listing(
        versions: &[RegistryVersion],
        config: &ProviderConfig,
    ) -> Result<String, String> {
        let candidates = SelectableRegistryVersions::from_listing(versions);
        select_registry_version(&candidates, &config.name, config.version.as_ref())
    }

