    #[test]
    fn non_wasm_file_provider_is_rejected_at_resolver_boundary() {
        let user_dirs = carina_core::TestUserDirs::new();
        let tmp = tempfile::tempdir().unwrap();
        let native_path = tmp.path().join("native-provider");
        fs::write(&native_path, b"native provider fixture").unwrap();
        let config = provider_config(&format!("file://{}", native_path.display()), None);
        let expected = "Provider 'awscc': native binaries are no longer supported. Use a .wasm component instead.";

        let direct_error = find_file_provider_source(tmp.path(), &config)
            .expect_err("a direct file lookup must reject native binaries");
        assert_eq!(direct_error, expected);

        let installed_error = find_installed_provider(tmp.path(), &config)
            .expect_err("an installed file lookup must reject native binaries");
        assert_eq!(installed_error.to_string(), expected);

        let install_lock = ProviderInstallLock::acquire(tmp.path()).unwrap();
        let error = resolve_all(
            &user_dirs,
            &install_lock,
            std::slice::from_ref(&config),
            LockMode::Normal,
        )
        .expect_err("file:// native binaries must be rejected by the resolver");

        assert_eq!(error.to_string(), expected);
        assert!(
            !provider_lock_path(tmp.path()).exists(),
            "a rejected artifact must not update the provider lock"
        );
    }

    #[derive(Clone)]
    enum FakeHttpAnswer {
        Response { status: u16, body: Vec<u8> },
        Redirect { status: u16, location: String },
    }

    #[derive(Default)]
    struct FakeRegistryHttp {
        responses: HashMap<String, FakeHttpAnswer>,
        downloads: HashMap<String, Vec<u8>>,
        requested: std::sync::Mutex<Vec<String>>,
    }

    impl FakeRegistryHttp {
        fn response(mut self, url: &str, status: u16, body: &[u8]) -> Self {
            self.responses.insert(
                url.to_string(),
                FakeHttpAnswer::Response {
                    status,
                    body: body.to_vec(),
                },
            );
            self
        }

        fn json(mut self, url: &str, body: &str) -> Self {
            self.responses.insert(
                url.to_string(),
                FakeHttpAnswer::Response {
                    status: 200,
                    body: body.as_bytes().to_vec(),
                },
            );
            self
        }

        fn bytes(mut self, url: &str, body: &[u8]) -> Self {
            self.responses.insert(
                url.to_string(),
                FakeHttpAnswer::Response {
                    status: 200,
                    body: body.to_vec(),
                },
            );
            self
        }

        fn redirect(mut self, url: &str, status: u16, location: &str) -> Self {
            assert!((300..400).contains(&status));
            self.responses.insert(
                url.to_string(),
                FakeHttpAnswer::Redirect {
                    status,
                    location: location.to_string(),
                },
            );
            self
        }

        fn downloadable_bytes(mut self, url: &str, body: &[u8]) -> Self {
            self.downloads.insert(url.to_string(), body.to_vec());
            self
        }

        fn was_requested(&self, needle: &str) -> bool {
            self.requested
                .lock()
                .unwrap()
                .iter()
                .any(|url| url.contains(needle))
        }

        fn request_count(&self, url: &str) -> usize {
            self.requested
                .lock()
                .unwrap()
                .iter()
                .filter(|requested| requested.as_str() == url)
                .count()
        }
    }

    impl RegistryHttp for FakeRegistryHttp {
        fn get(&self, request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String> {
            let url = request.url();
            let follows_redirects = matches!(request, RegistryHttpRequest::Resource(_));
            let mut current_url = url.to_string();
            for _ in 0..=10 {
                self.requested.lock().unwrap().push(current_url.clone());
                match self.responses.get(&current_url).cloned() {
                    Some(FakeHttpAnswer::Response { status, body }) => {
                        return Ok(if (200..300).contains(&status) {
                            HttpResponse::Success { body }
                        } else {
                            HttpResponse::Failure { status }
                        });
                    }
                    Some(FakeHttpAnswer::Redirect { location, .. }) if follows_redirects => {
                        current_url = location;
                    }
                    Some(FakeHttpAnswer::Redirect { status, .. }) => {
                        return Ok(HttpResponse::Failure { status });
                    }
                    None => return Err(format!("unexpected test URL: {current_url}")),
                }
            }
            Err(format!("too many test redirects from {url}"))
        }

        fn download_into(
            &self,
            url: &RegistryResourceUrl,
            out: &mut StagedArtifact<'_>,
        ) -> Result<(), RegistryDownloadError> {
            let url = url.as_str();
            self.requested.lock().unwrap().push(url.to_string());
            let body = match self.downloads.get(url) {
                Some(body) => body,
                None => match self.responses.get(url) {
                    Some(FakeHttpAnswer::Response { status, body })
                        if (200..300).contains(status) =>
                    {
                        body
                    }
                    Some(FakeHttpAnswer::Response { status, .. })
                    | Some(FakeHttpAnswer::Redirect { status, .. }) => {
                        return Err(RegistryDownloadError::HttpStatus {
                            status: *status,
                            url: url.to_string(),
                        });
                    }
                    None => {
                        return Err(RegistryDownloadError::Transport(format!(
                            "unexpected test download URL: {url}"
                        )));
                    }
                },
            };
            out.write_all(body).map_err(|error| {
                RegistryDownloadError::LocalIo(format!("Failed to write downloaded file: {error}"))
            })?;
            Ok(())
        }
    }

    struct PartialFailingRegistryHttp {
        final_path: PathBuf,
    }

    impl RegistryHttp for PartialFailingRegistryHttp {
        fn get(&self, _request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String> {
            unreachable!("the artifact path uses the streaming download seam")
        }

        fn download_into(
            &self,
            _url: &RegistryResourceUrl,
            out: &mut crate::install_lock::StagedArtifact<'_>,
        ) -> Result<(), RegistryDownloadError> {
            out.write_all(b"partial bytes").unwrap();
            assert!(
                !self.final_path.exists(),
                "download implementations must not make partial bytes visible at the final path"
            );
            Err(RegistryDownloadError::Transport(
                "injected interrupted download".into(),
            ))
        }
    }

    struct WrongHashRegistryHttp;

    impl RegistryHttp for WrongHashRegistryHttp {
        fn get(&self, _request: RegistryHttpRequest<'_>) -> Result<HttpResponse, String> {
            unreachable!("the artifact path uses the streaming download seam")
        }

        fn download_into(
            &self,
            _url: &RegistryResourceUrl,
            out: &mut crate::install_lock::StagedArtifact<'_>,
        ) -> Result<(), RegistryDownloadError> {
            out.write_all(b"wrong bytes").unwrap();
            Ok(())
        }
    }

    fn assert_empty_artifact_directory(path: &Path) {
        let entries = fs::read_dir(path)
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .collect::<Vec<_>>();
        assert!(
            entries.is_empty(),
            "temporary artifacts remain: {entries:?}"
        );
    }

