    #[test]
    fn registry_source_streams_large_wasm_instead_of_using_capped_get() {
        let user_dirs = carina_core::TestUserDirs::new();
        let dir = tempfile::tempdir().unwrap();
        let body = vec![b'w'; 10 * 1024 * 1024 + 1];
        let shasum = sha256_bytes(&body);
        let http = FakeRegistryHttp::default()
            .json(
                "https://registry.carina-rs.dev/.well-known/carina.json",
                r#"{"providers.v1":"/v1/providers/"}"#,
            )
            .json(
                "https://registry.carina-rs.dev/v1/providers/carina-rs/aws/versions",
                r#"{"sequence":7,"valid_until":"2999-01-01T00:00:00Z","versions":[{"version":"0.5.0","protocols":["1"]}]}"#,
            )
            .json(
                "https://registry.carina-rs.dev/v1/providers/carina-rs/aws/0.5.0/download",
                &format!(
                    r#"{{"protocols":["1"],"filename":"aws.wasm","download_url":"https://downloads.example.test/large-aws.wasm","shasum":"{shasum}","shasum_authored_by":"registry"}}"#
                ),
            )
            .downloadable_bytes("https://downloads.example.test/large-aws.wasm", &body);
        let mut lock_file = LockFile::default();

        let path = resolve_provider_with_http(
            &user_dirs,
            dir.path(),
            &provider_source("carina-rs/aws"),
            "0.5.0",
            "aws",
            &mut lock_file,
            &http,
        )
        .expect("registry WASM download should stream to disk instead of using capped get");

        assert_eq!(sha256_file(path.as_path()).unwrap(), shasum);
        assert_eq!(
            fs::metadata(path.as_path()).unwrap().len(),
            body.len() as u64
        );
    }

    #[test]
    fn github_release_lock_reinstall_uses_pinned_asset_id_without_listing() {
        let user_dirs = carina_core::TestUserDirs::new();
        let project = tempfile::tempdir().unwrap();
        let global = user_dirs.plugin_cache_dir();
        std::fs::create_dir_all(global).unwrap();
        let source = "github.com/acme/widget";
        let version = "0.1.0";
        let tag = ReleaseTag::from_lock("0.1.0".into());
        let bytes = b"recorded-tag provider";
        let mut lock = LockFile::default();
        lock.upsert(LockEntry {
            name: "widget".into(),
            source: source.into(),
            kind: LockEntryKind::GithubRelease {
                version: Version::parse(version).unwrap(),
                tag,
                asset_id: release_asset_id(42),
                constraint: Some("^0.1".into()),
            },
            sha256: sha256_bytes(bytes),
            registry: None,
        });
        lock.save(&provider_lock_path(project.path())).unwrap();
        let release_url = github_release_by_tag_url(source, "0.1.0");
        let asset_url = github_asset_url(source, 42);
        let github_http = FixtureGithubHttp::default()
            .json(
                &release_url,
                r#"{"tag_name":"0.1.0","assets":[{"name":"provider.wasm","id":42}]}"#,
            )
            .bytes(&asset_url, bytes);
        let github = GithubApi::new(&github_http, None);

        let resolved = resolve_all_with_github_in(
            &user_dirs,
            project.path(),
            &[versioned_config(source, "^0.1")],
            LockMode::Normal,
            &FixtureRegistryHttp::default(),
            &github,
        )
        .unwrap();

        assert_eq!(fs::read(resolved["awscc"].as_path()).unwrap(), bytes);
        assert_eq!(
            github_http
                .requests()
                .iter()
                .map(|request| request.url())
                .collect::<Vec<_>>(),
            [release_url, asset_url]
        );
        assert_eq!(
            github_http.requests()[1].accept(),
            "application/octet-stream"
        );
        assert_eq!(github_http.requests()[1].authorization(), None);
    }

